INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：「有点像」表示轻微的相似，符合「那座山的样子」和「一只大象」的描述。"}, {"text": "养", "is_correct": false, "explanation": "配价：「养」要求有生命的主语，「山的样子」不能养大象。"}, {"text": "吃", "is_correct": false, "explanation": "语义：山的样子不会吃大象，句子说不通。"}, {"text": "记得", "is_correct": false, "explanation": "语义：「记得」指记忆，「山的样子记得一只大象」说不通。"}], "explanations": {"有点像": "正确：「有点像」表示轻微的相似，符合「那座山的样子」和「一只大象」的描述。", "养": "配价：「养」要求有生命的主语，「山的样子」不能养大象。", "吃": "语义：山的样子不会吃大象，句子说不通。", "记得": "语义：「记得」指记忆，「山的样子记得一只大象」说不通。"}, "sentence_index": 6, "correct_answer": "有点像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和弟弟的身高完全相同，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是完全相同，与之矛盾。"}, {"text": "这两个杯子毫无差别，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是完全没有区别，与之矛盾。"}, {"text": "这张照片就是我本人，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是同一个人，完全相同，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只猫的样子有点像了小老虎。", "corrected_sentence": "这只猫的样子有点像小老虎。", "error_description": "多余的“了”：“有点像”后面直接接宾语时不能加“了”，应去掉“了”，写成“有点像小老虎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个面的味道不有点像我妈妈做的。", "corrected_sentence": "这个面的味道有点像我妈妈做的。", "error_description": "多余的否定词“不”：“有点像”是肯定形式，前面不能加“不”，应去掉“不”，写成“有点像我妈妈做的”，表示味道相似。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
