INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引导事物向前发展或使别人跟着自己的行动。", "primary_collocate": null, "pronunciation": "dài dòng", "ipa": "tai⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这位老板的努力带动了全公司的进步。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项新政策带动了农村经济的发展。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè xiàng xīn zhèng cè dài dòng le nóng cūn jīng jì de fā zhǎn", "sentence_source": "generated"}, {"text": "他的好成绩带动了全班同学努力学习。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂带动了这个小镇的发展。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带动大家一起唱歌。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位班长的积极态度带动了全班的学习热情。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè wèi bān zhǎng de jī jí tài dù dài dòng le quán bān de xué xí rè qíng", "sentence_source": "generated"}, {"text": "小王的热情带动了身边的人。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游带动了当地的经济。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公益项目带动了很多志愿者参与社区服务。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè ge gōng yì xiàng mù dài dòng le hěn duō zhì yuàn zhě cān yǔ shè qū fú wù", "sentence_source": "generated"}, {"text": "好的领导能带动整个团队进步。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带动了", "label": "体标"}, {"form": "带动着", "label": "体标"}, {"form": "带动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "引导事物发展或使别人跟着行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。"}, {"text": "大洞", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。"}, {"text": "耐冻", "is_correct": false, "explanation": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。"}, {"text": "带痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。"}], "explanations": {"带动": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。", "大洞": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。", "耐冻": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。", "带痛": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确：「带动」表示引导事物向前发展，「这位老板的努力带动了全公司的进步」符合句意。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：「阻止」与「进步」意思相反，「阻止了全公司的进步」与「努力」的正面语境矛盾。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：「拖累」是妨碍、拖后腿，与「努力」的正面语境相反，句子说不通。"}, {"text": "依靠", "is_correct": false, "explanation": "搭配：「依靠」后接可依靠的人或力量，「依靠了全公司的进步」说不通。"}], "explanations": {"带动": "正确：「带动」表示引导事物向前发展，「这位老板的努力带动了全公司的进步」符合句意。", "阻止": "语义：「阻止」与「进步」意思相反，「阻止了全公司的进步」与「努力」的正面语境矛盾。", "拖累": "语义：「拖累」是妨碍、拖后腿，与「努力」的正面语境相反，句子说不通。", "依靠": "搭配：「依靠」后接可依靠的人或力量，「依靠了全公司的进步」说不通。"}, "sentence_index": 0, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天带动一箱牛奶上楼。", "explanation": "这里应该用〈搬〉。带动表示引导事物发展或使别人跟着行动，搬运东西上楼要用「搬」，不能说「带动」。"}, {"text": "这次合作带动了不少麻烦。", "explanation": "这里应该用〈带来〉。带动表示带领、促使事物向前发展，带来不好的结果要用带来。"}, {"text": "这个消息带动他离开了公司。", "explanation": "这里应该用〈促使〉。带动多指带头或引导他人跟着行动、让事情向前发展，消息让人做出决定要用促使。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。"}, {"text": "大动", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。"}, {"text": "再动", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。"}, {"text": "打动", "is_correct": false, "explanation": "dǎ 与 dài 声母相同，韵母和声调不同，意思是“使人感动”。"}], "explanations": {"带动": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。", "大动": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。", "再动": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。", "打动": "dǎ 与 dài 声母相同，韵母和声调不同，意思是“使人感动”。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”与“热情”矛盾，热情的人不会冷落身边的人。"}, {"text": "带动", "is_correct": true, "explanation": "“小王的热情带动了身边的人”表示热情影响了周围的人，符合句意。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”的对象多是钱财、时间、资源，不能说“浪费了身边的人”。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”与“热情”矛盾，句子的意思被颠倒了。"}], "explanations": {"冷落": "语义：“冷落”与“热情”矛盾，热情的人不会冷落身边的人。", "带动": "“小王的热情带动了身边的人”表示热情影响了周围的人，符合句意。", "浪费": "搭配：“浪费”的对象多是钱财、时间、资源，不能说“浪费了身边的人”。", "忽视": "语义：“忽视”与“热情”矛盾，句子的意思被颠倒了。"}, "sentence_index": 6, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天细心带动生病的爷爷。", "explanation": "这里应该用〈照顾〉。带动指引导事物发展或使别人跟着行动，照顾指关心并料理病人，不能说“带动”爷爷。"}, {"text": "警察带动了那个嫌疑人。", "explanation": "这里应该用〈带走〉。带动是引导发展或促使跟着行动，把人带离某处要用带走。"}, {"text": "他每天带动汽车去上班。", "explanation": "这里应该用〈驾驶〉。带动不能用来说操纵车辆，开车上班要用驾驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的交通线了带动沿线城市的发展。", "corrected_sentence": "新的交通线带动沿线城市的发展。", "error_description": "“了”放错了位置：“带动”前不能加“了”，应去掉，写成“新的交通线带动沿线城市的发展”；若要表示完成，“了”应放在“带动”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂的新产品带动得附近的服务业。", "corrected_sentence": "这家工厂的新产品带动了附近的服务业。", "error_description": "“得”放错了（应为“了”）：“带动”后面表示已经发生应用“了”，写成“带动得”后不能直接接“附近的服务业”，应说“带动了附近的服务业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
