INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续地创造新事物或提出新想法。", "primary_collocate": null, "pronunciation": "bú duàn chuàng xīn", "ipa": "pu˧˥ tuan˥˩ ʈʂʰuaŋ˥˩ ɕin˥", "syllable_count": 4, "sentences": [{"text": "经过不断创新，这种电脑变得越来越便宜，也更好用了。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想一直做得好，就必须不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们不断创新，才发明了这种新电池。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有不断创新，我们的产品才能卖得好。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不断创新，让手机的功能越来越多。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师不断创新教学方法，学生都喜欢上他的课。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不断创新是这家小店成功的原因。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让工作更有意思，你要不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民不断创新种田的办法，今年的粮食更多了。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市不断创新，现在已经是有名的科技中心。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不断地创新", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "持续地创造新事物或提出新想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不断涨价", "is_correct": false, "explanation": "语义：“不断涨价”与“变得越来越便宜”矛盾，涨价不会让东西越来越便宜。"}, {"text": "不断创新", "is_correct": true, "explanation": "“经过不断创新，这种电脑变得越来越便宜，也更好用了”前后连贯，是正确答案。"}, {"text": "不断退步", "is_correct": false, "explanation": "语义：“不断退步”与“也更好用了”矛盾，退步不会让东西变得更好用。"}, {"text": "不断堆积", "is_correct": false, "explanation": "搭配：“堆积”指东西越积越多，不能用来表示使商品变便宜的过程。"}], "explanations": {"不断涨价": "语义：“不断涨价”与“变得越来越便宜”矛盾，涨价不会让东西越来越便宜。", "不断创新": "“经过不断创新，这种电脑变得越来越便宜，也更好用了”前后连贯，是正确答案。", "不断退步": "语义：“不断退步”与“也更好用了”矛盾，退步不会让东西变得更好用。", "不断堆积": "搭配：“堆积”指东西越积越多，不能用来表示使商品变便宜的过程。"}, "sentence_index": 0, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天不断创新学习英语。", "explanation": "这里应该用〈努力〉。不断创新指持续想出新东西，学习英语要用努力，不能用创新。"}, {"text": "我们正在不断创新产品的质量。", "explanation": "这里应该用〈改进〉。创新是提出新事物或新想法，提高质量要用改进。"}, {"text": "他不断创新同样的错误。", "explanation": "这里应该用〈重复〉。不断创新是持续想出新东西，同样的错误反复出现要用重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不断亏损", "is_correct": false, "explanation": "语义：“不断亏损”与“成功的原因”矛盾，亏损不可能是成功的原因。"}, {"text": "不断创新", "is_correct": true, "explanation": "“不断创新是这家小店成功的原因”表示持续创新带来了成功，符合句意。"}, {"text": "不断偷懒", "is_correct": false, "explanation": "语义：“不断偷懒”与“成功的原因”矛盾，偷懒不会带来成功。"}, {"text": "不断抱怨", "is_correct": false, "explanation": "搭配：“抱怨”是表达不满的动作，不适合作为“成功的原因”的主语。"}], "explanations": {"不断亏损": "语义：“不断亏损”与“成功的原因”矛盾，亏损不可能是成功的原因。", "不断创新": "“不断创新是这家小店成功的原因”表示持续创新带来了成功，符合句意。", "不断偷懒": "语义：“不断偷懒”与“成功的原因”矛盾，偷懒不会带来成功。", "不断抱怨": "搭配：“抱怨”是表达不满的动作，不适合作为“成功的原因”的主语。"}, "sentence_index": 6, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "侦探不断创新线索。", "explanation": "这里应该用〈寻找〉。不断创新指持续想出新东西，找线索要用寻找。"}, {"text": "妈妈不断创新孩子的作业。", "explanation": "这里应该用〈检查〉。不断创新是持续想出新东西，查看作业有没有错要用检查。"}, {"text": "他不断创新一杯水，然后喝了下去。", "explanation": "这里应该用〈喝〉。不断创新指持续想出新东西，喝水要用「喝」，不能说「创新一杯水」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司正在不断创新了，产品越来越好。", "corrected_sentence": "这家公司正在不断创新，产品越来越好。", "error_description": "“正在”表示动作正在进行，“创新”后面不能再加“了”，应去掉“了”，说“正在不断创新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要不断创新了，企业就会发展。", "corrected_sentence": "只要不断创新，企业就会发展。", "error_description": "“只要……”引出的假设条件表示未发生的情况，“不断创新”后不能加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
