INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地球大气层以外的宇宙空间，非常广阔，几乎没有空气，物体处于失重状态。", "primary_collocate": null, "pronunciation": "tài kōng", "ipa": "tʰai˥˩ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "今天，在屋顶、沙漠甚至太空中，都能看到太阳能电池板。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "宇航员坐着火箭飞向太空。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空中没有空气，人必须穿特别的衣服。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国已经把很多卫星送到了太空。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在太空里，东西不会往下掉。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想成为去太空工作的人。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从太空看地球，它像一个蓝色的球。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员在太空里住了半年。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空非常广阔，我们还有很多不知道的事。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个望远镜能拍到太空中很远的星星。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太空人", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球大气层以外广阔的宇宙空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。"}, {"text": "胎孔", "is_correct": false, "explanation": "tāi kǒng 与 tài kōng 声母韵母相同，只是声调不同，意思是器物上的孔，不指宇宙空间。"}, {"text": "卖空", "is_correct": false, "explanation": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。"}, {"text": "太公", "is_correct": false, "explanation": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}], "explanations": {"太空": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。", "胎孔": "tāi kǒng 与 tài kōng 声母韵母相同，只是声调不同，意思是器物上的孔，不指宇宙空间。", "卖空": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。", "太公": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}, "sentence_index": null, "correct_answer": "太空"}, "level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球大气层以外的宇宙空间，与“屋顶”“沙漠”并列，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是室内家电，与“屋顶”的高处和“太空”的范围并列不合理，也不能看到电池板。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室在地面以下，与“屋顶”的高处并列矛盾，句意不通。"}, {"text": "幽冥", "is_correct": false, "explanation": "语域：“幽冥”是文言用语，指阴间，与现代说明文式的叙述不协调。"}], "explanations": {"太空": "“太空”指地球大气层以外的宇宙空间，与“屋顶”“沙漠”并列，符合句意。", "冰箱": "语义：冰箱是室内家电，与“屋顶”的高处和“太空”的范围并列不合理，也不能看到电池板。", "地下室": "语义：地下室在地面以下，与“屋顶”的高处并列矛盾，句意不通。", "幽冥": "语域：“幽冥”是文言用语，指阴间，与现代说明文式的叙述不协调。"}, "sentence_index": 0, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停以后，太空上的草长得特别绿。", "explanation": "这里应该用〈地面〉。草长在地面上，要靠土壤、水和空气；太空没有这些，这里的“太空”用法不对。"}, {"text": "太空下起了小雨，街上的人都撑起了伞。", "explanation": "这里应该用〈天空〉。雨从天空落下，太空没有空气，不会下雨，这里的“太空”用法不对。"}, {"text": "小鸟在太空里飞来飞去，叫个不停。", "explanation": "这里应该用〈空中〉。鸟在空中飞，太空没有空气，鸟无法在那里飞，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球外的宇宙空间，从那里才能看到整个地球的形状，符合句意。"}, {"text": "海底", "is_correct": false, "explanation": "语义：从海底看不到地球的整体形状，与“从……看地球”的视角矛盾。"}, {"text": "矿井", "is_correct": false, "explanation": "语义：矿井在地下狭窄处，视野受限，无法看到地球像一个球的样子。"}, {"text": "冥界", "is_correct": false, "explanation": "语域：“冥界”是神话或宗教用语，与这句科普式的描述不协调。"}], "explanations": {"太空": "“太空”指地球外的宇宙空间，从那里才能看到整个地球的形状，符合句意。", "海底": "语义：从海底看不到地球的整体形状，与“从……看地球”的视角矛盾。", "矿井": "语义：矿井在地下狭窄处，视野受限，无法看到地球像一个球的样子。", "冥界": "语域：“冥界”是神话或宗教用语，与这句科普式的描述不协调。"}, "sentence_index": 6, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就跑去吃太空。", "explanation": "“吃”的对象应是食物，太空是宇宙空间，不能吃，这里的“太空”用法不对。"}, {"text": "我们每天乘坐太空去上学。", "explanation": "“乘坐”的对象应是交通工具，太空不是交通工具，这里的“太空”用法不对。"}, {"text": "妈妈给我穿上一件太空，说天冷了。", "explanation": "“穿”的对象应是衣物，太空不能穿，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宇航员太空里工作了三个月。", "corrected_sentence": "宇航员在太空里工作了三个月。", "error_description": "缺少介词“在”：表示在某处做事，要说“在太空里工作”，不能直接说“太空里工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火箭终于飞了进太空。", "corrected_sentence": "火箭终于飞进了太空。", "error_description": "补语“进”和“了”的位置错了。应写作“飞进了太空”，“进”紧跟在动词“飞”后面，“了”放在补语后；“飞了进太空”的语序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
