INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "煤是古代植物在地下经过长时间变化形成的黑色固体矿物，主要用作燃料。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "未来，我们可能会用更多的清洁电力，减少对煤和石油的依赖。", "target_word": "煤", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个国家的煤很多，也卖到别的国家。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天要烧很多煤。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤是用来发电的重要燃料。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤是由古代植物慢慢形成的。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山下面有很多煤。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车把煤从山里运到城市。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烧煤会让空气变脏。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在矿里挖了一吨煤。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多地方少用煤，多用天然气。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "吨", "label": "量词"}, {"form": "煤炭", "label": "复合"}, {"form": "煤矿", "label": "复合"}, {"form": "煤气", "label": "复合"}], "register": "中性", "sense_fingerprint": "古代植物形成的黑色矿物燃料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13655, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。听到的是“煤”（méi），指古代植物形成的黑色矿物燃料。"}, {"text": "妹", "is_correct": false, "explanation": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。"}, {"text": "美", "is_correct": false, "explanation": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。"}, {"text": "门", "is_correct": false, "explanation": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}], "explanations": {"煤": "正确答案。听到的是“煤”（méi），指古代植物形成的黑色矿物燃料。", "妹": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。", "美": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。", "门": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}, "sentence_index": null, "correct_answer": "煤"}, "level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。句中是“减少对……和石油的依赖”，前面说的燃料正是“煤”。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是化石燃料，不能作为要减少依赖的能源。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是能源，与“清洁电力”和石油的语境不符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“依赖”一般搭配能源或资源，不说依赖教室。"}], "explanations": {"煤": "正确答案。句中是“减少对……和石油的依赖”，前面说的燃料正是“煤”。", "水": "语义：水不是化石燃料，不能作为要减少依赖的能源。", "食物": "语义：食物不是能源，与“清洁电力”和石油的语境不符。", "教室": "搭配：“依赖”一般搭配能源或资源，不说依赖教室。"}, "sentence_index": 0, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯煤。", "explanation": "这里应该用〈牛奶〉。煤是黑色固体燃料，不能喝。"}, {"text": "晚上天上的煤一闪一闪的。", "explanation": "这里应该用〈星星〉。煤埋在地下，不会在天上发光。"}, {"text": "吃饭前要用煤洗手。", "explanation": "这里应该用〈肥皂〉。煤是燃料，会把手弄脏，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。“运到城市”的是可以运输的货物，煤符合。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是天上的光现象，不能被火车运输。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮无法被火车从山里运到城市。"}, {"text": "意见", "is_correct": false, "explanation": "搭配：“运”搭配的是实物货物，不说运“意见”。"}], "explanations": {"煤": "正确答案。“运到城市”的是可以运输的货物，煤符合。", "彩虹": "语义：彩虹是天上的光现象，不能被火车运输。", "月亮": "语义：月亮无法被火车从山里运到城市。", "意见": "搭配：“运”搭配的是实物货物，不说运“意见”。"}, "sentence_index": 6, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，就喝了煤。", "explanation": "这里应该用〈水〉。“喝”的对象应是液体，煤是固体，不能喝。"}, {"text": "这袋煤很甜。", "explanation": "这里应该用〈糖〉这样的食物。“甜”形容食物的味道，煤不是食物，不能说甜。"}, {"text": "屋顶上的煤很白。", "explanation": "这里应该用〈雪〉这样的白色物体。煤是黑色的，不能用“白”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂里堆着几个煤。", "corrected_sentence": "工厂里堆着几块煤。", "error_description": "“煤”是块状固体，量词应用“块”，不能说“个煤”，应说“几块煤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头煤要运到城市去。", "corrected_sentence": "这些煤要运到城市去。", "error_description": "量词错误：“头”用于大牲畜，煤不能用“头”计量，应改为“这些煤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
