INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13657, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指叙述英雄传说或重大历史事件的叙事长诗。", "primary_collocate": null, "pronunciation": "shǐ shī", "ipa": "ʂɻ̩˨˩˦ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他花了三天时间，读完了一部宏大的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部史诗讲了一位英雄的故事。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们读了一段史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过一部关于战争的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首史诗有几千行。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人用史诗记住历史。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们花了几十年研究这部古老的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢读古希腊的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部史诗在民间流传了几百年。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手唱着一段古老的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "史詩", "label": "繁体"}, {"form": "英雄史诗", "label": "复合"}, {"form": "部", "label": "量词"}, {"form": "首", "label": "量词"}], "register": "书面", "sense_fingerprint": "史诗|叙事长诗|英雄与历史", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13657, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。史诗（shǐ shī）指叙述英雄传说或重大历史事件的叙事长诗。"}, {"text": "实施", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是实际执行（计划、政策等）。"}, {"text": "石狮", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。"}, {"text": "试试", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，第二音节 shi 读轻声，意思是试一下。"}, {"text": "死尸", "is_correct": false, "explanation": "sǐ 与 shǐ 的声母不同（s 与 sh），声调相同，意思是尸体。"}], "explanations": {"史诗": "正确答案。史诗（shǐ shī）指叙述英雄传说或重大历史事件的叙事长诗。", "实施": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是实际执行（计划、政策等）。", "石狮": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。", "试试": "shì（第四声）与 shǐ（第三声）声调不同，第二音节 shi 读轻声，意思是试一下。", "死尸": "sǐ 与 shǐ 的声母不同（s 与 sh），声调相同，意思是尸体。"}, "sentence_index": null, "correct_answer": "史诗"}, "level_3": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。“读完了一部宏大的……”中，“史诗”指叙事长诗，可以被读完，与“宏大”搭配自然。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是喷在身上的化妆品，不是可以读完的作品。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通设施，不能被读完。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验活动，不是可以读完的作品。"}], "explanations": {"史诗": "正确答案。“读完了一部宏大的……”中，“史诗”指叙事长诗，可以被读完，与“宏大”搭配自然。", "香水": "语义：香水是喷在身上的化妆品，不是可以读完的作品。", "地铁": "语义：地铁是交通设施，不能被读完。", "考试": "语义：考试是测验活动，不是可以读完的作品。"}, "sentence_index": 0, "correct_answer": "史诗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首史诗只有四行，几句话就读完了。", "explanation": "这里应该用〈短诗〉。史诗是长篇叙事诗，不能用来指只有四行的短诗。"}, {"text": "他读完了一只史诗。", "explanation": "量词“只”用于单个动物，不能用来计量史诗；这里应该用〈部〉或〈首〉。"}, {"text": "妈妈教我唱一首史诗，讲的是小猫在院子里玩耍。", "explanation": "这里应该用〈童谣〉。史诗叙述英雄或重大历史事件，不能用来讲小猫玩耍这类日常小事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13657, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。史诗（shǐ shī）指叙述英雄传说或重大历史事件的叙事长诗。"}, {"text": "实施", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是实际执行（计划、政策等）。"}, {"text": "石狮", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。"}, {"text": "失事", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是发生事故。"}, {"text": "史书", "is_correct": false, "explanation": "shū 与 shī 韵母不同（ū 与 ī），其余相同，意思是记载历史的书。"}], "explanations": {"史诗": "正确答案。史诗（shǐ shī）指叙述英雄传说或重大历史事件的叙事长诗。", "实施": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是实际执行（计划、政策等）。", "石狮": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。", "失事": "shī（第一声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是发生事故。", "史书": "shū 与 shī 韵母不同（ū 与 ī），其余相同，意思是记载历史的书。"}, "sentence_index": null, "correct_answer": "史诗"}, "level_3": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。“这部古老的史诗”指古代流传下来的叙事长诗，符合“研究几十年”的语境。"}, {"text": "网络小说", "is_correct": false, "explanation": "搭配：“古老”修饰历史悠久的事物，不能修饰“网络小说”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是近代才出现的物品，与“古老”矛盾。"}, {"text": "短剧", "is_correct": false, "explanation": "语义：短剧是近年兴起的影视形式，与“古老”矛盾。"}], "explanations": {"史诗": "正确答案。“这部古老的史诗”指古代流传下来的叙事长诗，符合“研究几十年”的语境。", "网络小说": "搭配：“古老”修饰历史悠久的事物，不能修饰“网络小说”。", "手机": "语义：手机是近代才出现的物品，与“古老”矛盾。", "短剧": "语义：短剧是近年兴起的影视形式，与“古老”矛盾。"}, "sentence_index": 6, "correct_answer": "史诗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写了一首史诗，描写家乡的春天。", "explanation": "这里应该用〈散文〉。史诗叙述英雄或重大历史事件，不用来写家乡景色这类抒情内容。"}, {"text": "书架上摆着一株史诗。", "explanation": "量词“株”用于植物，史诗应用〈部〉或〈首〉。"}, {"text": "奶奶用一首史诗做了一锅汤。", "explanation": "这里把“史诗”当成了食材，词义不符。史诗是叙事长诗，不能用来做汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里收藏着一个史诗。", "corrected_sentence": "图书馆里收藏着一部史诗。", "error_description": "量词错误：“史诗”是长篇作品，应用量词“部”或“首”计量，不能用“个”。正确说法是“一部史诗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人把一个史诗讲给孙子听。", "corrected_sentence": "老人把一部史诗讲给孙子听。", "error_description": "量词错误：“史诗”应用量词“部”或“首”，不能用“个”。正确说法是“一部史诗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
