INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海拔较低、地势平坦的广阔陆地。", "primary_collocate": null, "pronunciation": "píng yuán", "ipa": "pʰiŋ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这里是一片大平原。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平原上没有山。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家在平原上。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平原的夏天很热。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车在平原上跑得很快。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平原上种了很多玉米。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方有一片很大的平原。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从山上往下看，下面是一大片平原。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原上的城市比山里的多，人也多。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流过平原，给农民带来了很多水。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片平原", "label": "量词"}, {"form": "平原地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "海拔低、地势平坦的大片陆地（地理名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“这里是一片大平原”指地势平坦的广阔陆地，与“一片大”相符。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：量词“片”不用于河流，河流应说“一条”。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：量词“片”不用于公路，公路应说“一条”。"}, {"text": "书", "is_correct": false, "explanation": "语义：一本书不是广阔的陆地，“一片大书”没有意义。"}], "explanations": {"平原": "正确答案。“这里是一片大平原”指地势平坦的广阔陆地，与“一片大”相符。", "河流": "搭配：量词“片”不用于河流，河流应说“一条”。", "公路": "搭配：量词“片”不用于公路，公路应说“一条”。", "书": "语义：一本书不是广阔的陆地，“一片大书”没有意义。"}, "sentence_index": 0, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里种着一棵平原。", "explanation": "量词“棵”用于树木，平原应用〈片〉。"}, {"text": "这个平原海拔很高，空气稀薄。", "explanation": "这里应该用〈高原〉。平原海拔较低、地势平坦，“海拔很高，空气稀薄”是高原的特点。"}, {"text": "我们爬上了这片平原。", "explanation": "这里应该用〈高山〉。“爬上”指向高处，平原地势平坦，不能说爬上平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“北方有一片很大的平原”描述北方广阔平坦的陆地。"}, {"text": "热带雨林", "is_correct": false, "explanation": "语义：热带雨林分布在热带，与“北方”矛盾。"}, {"text": "南海", "is_correct": false, "explanation": "语义：南海位于南方，与“北方”矛盾。"}, {"text": "赤道", "is_correct": false, "explanation": "搭配：“很大的”多修饰面积广阔的地域，赤道是假想的纬线，不说“很大的赤道”。"}], "explanations": {"平原": "正确答案。“北方有一片很大的平原”描述北方广阔平坦的陆地。", "热带雨林": "语义：热带雨林分布在热带，与“北方”矛盾。", "南海": "语义：南海位于南方，与“北方”矛盾。", "赤道": "搭配：“很大的”多修饰面积广阔的地域，赤道是假想的纬线，不说“很大的赤道”。"}, "sentence_index": 6, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村口停着一辆平原。", "explanation": "量词“辆”用于车辆，平原应用〈片〉。"}, {"text": "海浪拍打着平原。", "explanation": "这里应该用〈海岸〉。海浪拍打的是海岸，平原是陆地，没有海浪拍打的岸。"}, {"text": "我们把平原放进了鱼缸里。", "explanation": "这里把“平原”当成了可以装进鱼缸的小物件，词义不符。平原是广阔的陆地，不能放进容器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个县城坐落在一大座平原上。", "corrected_sentence": "那个县城坐落在一大片平原上。", "error_description": "量词错误：量词“座”用于山、楼等建筑，平原应说“一片”。正确说法是“一大片平原”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐火车穿过一大座平原。", "corrected_sentence": "我们坐火车穿过一大片平原。", "error_description": "量词错误：量词“座”用于山、楼、桥等，平原应说“一片”。正确说法是“一大片平原”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迅速", "is_correct": true, "explanation": "与“缓缓”形成反义：速度很快，与速度很慢正好相反。"}, {"text": "轻轻", "is_correct": false, "explanation": "“轻轻”形容动作的轻柔，说的是力度，不是速度的快慢相反。"}, {"text": "悄悄", "is_correct": false, "explanation": "“悄悄”形容不让人察觉，与速度的快慢无关。"}, {"text": "偶尔", "is_correct": false, "explanation": "“偶尔”说的是频率，与动作速度的快慢不构成反义。"}], "correct_answer": "迅速", "explanations": {"迅速": "与“缓缓”形成反义：速度很快，与速度很慢正好相反。", "轻轻": "“轻轻”形容动作的轻柔，说的是力度，不是速度的快慢相反。", "悄悄": "“悄悄”形容不让人察觉，与速度的快慢无关。", "偶尔": "“偶尔”说的是频率，与动作速度的快慢不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迅速", "is_correct": true, "explanation": "与“缓缓”形成反义：速度很快，与速度很慢正好相反。"}, {"text": "连连", "is_correct": false, "explanation": "“连连”表示接连不断，说的是次数，与速度快慢不构成反义。"}, {"text": "默默", "is_correct": false, "explanation": "“默默”形容不声不响，与速度快慢无关。"}, {"text": "轻声", "is_correct": false, "explanation": "“轻声”说的是声音的大小，与动作速度的快慢不相对。"}], "correct_answer": "迅速", "explanations": {"迅速": "与“缓缓”形成反义：速度很快，与速度很慢正好相反。", "连连": "“连连”表示接连不断，说的是次数，与速度快慢不构成反义。", "默默": "“默默”形容不声不响，与速度快慢无关。", "轻声": "“轻声”说的是声音的大小，与动作速度的快慢不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "形容速度很慢，不急不忙的样子。", "primary_collocate": null, "pronunciation": "huǎn huǎn", "ipa": "xwan˨˩˦ xwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "火车缓缓开走。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳缓缓升起。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她缓缓地走进来。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大门缓缓打开。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水缓缓流向远方。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人缓缓站了起来。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他缓缓地说，大家都听得很清楚。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在湖上缓缓前进，没有一点声音。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机缓缓降落在机场，大家都鼓起掌来。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着一杯茶，缓缓走到窗前。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动作速度很慢、从容不迫的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "“缓缓”表示速度很慢地开走，与火车慢慢离开的情景相合。"}, {"text": "一动不动", "is_correct": false, "explanation": "语义：“一动不动”表示静止，与“开走”的动态相矛盾。"}, {"text": "红色", "is_correct": false, "explanation": "语法：“红色”是名词或形容词，不能直接修饰动词“开走”。"}, {"text": "呆呆地", "is_correct": false, "explanation": "语义：“呆呆地”描写人的神情，不能用来说明火车行进的速度。"}], "explanations": {"缓缓": "“缓缓”表示速度很慢地开走，与火车慢慢离开的情景相合。", "一动不动": "语义：“一动不动”表示静止，与“开走”的动态相矛盾。", "红色": "语法：“红色”是名词或形容词，不能直接修饰动词“开走”。", "呆呆地": "语义：“呆呆地”描写人的神情，不能用来说明火车行进的速度。"}, "sentence_index": 0, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "闪电缓缓劈下来，把天空照亮了。", "explanation": "「缓缓」表示动作慢，闪电极快，二者的速度义相互矛盾。"}, {"text": "枪声缓缓响起，大家都吓了一跳。", "explanation": "枪声是瞬间发出的，「缓缓」描写的慢速与之不合。"}, {"text": "爆炸缓缓发生，没有任何预兆。", "explanation": "爆炸是瞬间完成的，不能用「缓缓」描写其速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "正确答案。“缓缓地说”指说话速度很慢，所以大家都听得清楚，与句意相合。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：“含糊地说”与“大家都听得很清楚”矛盾。"}, {"text": "无声", "is_correct": false, "explanation": "语义：“无声地说”指不出声，与“大家都听得很清楚”矛盾。"}, {"text": "一言不发", "is_correct": false, "explanation": "语义：“一言不发”指不说话，与“他……说”的句意矛盾。"}], "explanations": {"缓缓": "正确答案。“缓缓地说”指说话速度很慢，所以大家都听得清楚，与句意相合。", "含糊": "语义：“含糊地说”与“大家都听得很清楚”矛盾。", "无声": "语义：“无声地说”指不出声，与“大家都听得很清楚”矛盾。", "一言不发": "语义：“一言不发”指不说话，与“他……说”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一下子缓缓推开了门。", "explanation": "「缓缓」表示动作慢慢进行，这里误用于瞬时完成的动作，与表示瞬时的时间义冲突。"}, {"text": "他一闪身，缓缓躲开了飞来的球。", "explanation": "「一闪身」是瞬间动作，与「缓缓」的慢速义冲突。"}, {"text": "他一瞬间缓缓跳上了车。", "explanation": "「缓缓」表示动作慢慢进行，这里误用于瞬时完成的动作，跳上车是快速完成的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人在河边缓缓得走着。", "corrected_sentence": "老人在河边缓缓地走着。", "error_description": "助词误用：状语后应用“地”，此处误用“得”；改为“缓缓地走着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师很缓缓地把门关上。", "corrected_sentence": "老师缓缓地把门关上。", "error_description": "“缓缓”是副词，本身已表示动作慢，不能再受“很”修饰；错写成“很缓缓地”，应删去“很”，为“缓缓地把门关上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "锋利", "is_correct": false, "explanation": "“锋利”形容刀刃等的尖锐程度，与光彩的明暗无关，不是反义词。"}, {"text": "平坦", "is_correct": false, "explanation": "“平坦”形容表面的平整，与光亮没有关系，不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容质地不光滑，与“光彩闪耀”不是相对的意思。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "锋利": "“锋利”形容刀刃等的尖锐程度，与光彩的明暗无关，不是反义词。", "平坦": "“平坦”形容表面的平整，与光亮没有关系，不构成反义。", "粗糙": "“粗糙”形容质地不光滑，与“光彩闪耀”不是相对的意思。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与光亮没有对立关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "沉重": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。", "柔软": "“柔软”形容质地，与光亮没有对立关系。", "迟钝": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容光彩闪耀，非常明亮。", "primary_collocate": null, "pronunciation": "yì yì shēng huī", "ipa": "i˥˩ i˥˩ ʂɤŋ˥ xweɪ˥", "syllable_count": 4, "sentences": [{"text": "从古代平原上缓缓转动的风车，到现代城市屋顶熠熠生辉的太阳能电池板，清洁能源的演进不仅映射了技术的飞跃，更深刻重塑了文明与自然的关系。", "target_word": "熠熠生辉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她的眼睛熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨后的湖面熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜空中的星星熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金色的屋顶在阳光下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圣诞树上的小灯熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把奖杯仔细擦了一遍，放在桌上，熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪山在阳光下熠熠生辉，美极了。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚，高楼上的灯光熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她戴着一条项链，在灯光下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "成语：光彩闪耀、十分明亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "修饰“太阳能电池板”，表示光彩闪耀，与句中“清洁能源”“映射技术的飞跃”的正面意象相合。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”与“现代城市屋顶”和“技术的飞跃”相矛盾，句子强调的是新技术。"}, {"text": "污浊", "is_correct": false, "explanation": "语义：“污浊”与“清洁能源”正好相反，这样说句子意思不通。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，与太阳能电池板的外观不符。"}], "explanations": {"熠熠生辉": "修饰“太阳能电池板”，表示光彩闪耀，与句中“清洁能源”“映射技术的飞跃”的正面意象相合。", "陈旧": "语义：“陈旧”与“现代城市屋顶”和“技术的飞跃”相矛盾，句子强调的是新技术。", "污浊": "语义：“污浊”与“清洁能源”正好相反，这样说句子意思不通。", "嘈杂": "语义：“嘈杂”形容声音杂乱，与太阳能电池板的外观不符。"}, "sentence_index": 0, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律熠熠生辉，听得人入迷。", "explanation": "「熠熠生辉」只形容光彩闪耀，指视觉上的光亮，不能用来形容旋律这类听觉感受。"}, {"text": "厨房里飘来熠熠生辉的香味。", "explanation": "「熠熠生辉」描写光亮，香味属于嗅觉，这个词不能用来修饰气味。"}, {"text": "这道汤的味道熠熠生辉，很鲜。", "explanation": "「熠熠生辉」只用于光亮，味道属于味觉，不能这样修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "正确答案。“仔细擦了一遍”后放在桌上，奖杯光彩闪耀，与句意相合。"}, {"text": "脏兮兮", "is_correct": false, "explanation": "语义：刚被仔细擦过的奖杯不会“脏兮兮”，与句意相反。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：刚被仔细擦过的奖杯不会“生锈”，与句意矛盾。"}, {"text": "布满灰尘", "is_correct": false, "explanation": "语义：刚被仔细擦过的奖杯不会“布满灰尘”，与句意矛盾。"}], "explanations": {"熠熠生辉": "正确答案。“仔细擦了一遍”后放在桌上，奖杯光彩闪耀，与句意相合。", "脏兮兮": "语义：刚被仔细擦过的奖杯不会“脏兮兮”，与句意相反。", "生锈": "语义：刚被仔细擦过的奖杯不会“生锈”，与句意矛盾。", "布满灰尘": "语义：刚被仔细擦过的奖杯不会“布满灰尘”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里的寂静熠熠生辉，让人睡不着。", "explanation": "「熠熠生辉」指光彩闪耀，寂静是听觉上的状态，不能用它来形容。"}, {"text": "他的呼吸熠熠生辉，很均匀。", "explanation": "「熠熠生辉」指光彩闪耀，呼吸是身体的节律，不是光彩，这里误当成形容节奏平稳的意思。"}, {"text": "这块冰的凉意熠熠生辉。", "explanation": "凉意是触觉感受，「熠熠生辉」描写光彩，二者不搭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的眼睛在灯光下的熠熠生辉。", "corrected_sentence": "她的眼睛在灯光下熠熠生辉。", "error_description": "“的”多余：「熠熠生辉」作谓语时不加“的”，加上后句子缺少谓语，应说「她的眼睛在灯光下熠熠生辉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路灯下，银器很熠熠生辉。", "corrected_sentence": "路灯下，银器熠熠生辉。", "error_description": "程度副词“很”不能修饰「熠熠生辉」这类固定四字形容语，应说「路灯下，银器熠熠生辉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
