INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "比喻事物发展迅速，进步很大。", "primary_collocate": null, "pronunciation": "fēi yuè", "ipa": "fei˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这座城市近十年飞跃发展，变化很大。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了一年汉语，水平有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā xué le yì nián Hànyǔ, shuǐpíng yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "科技飞跃发展，我们的生活越来越方便。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Kējì fēiyuè fāzhǎn, wǒmen de shēnghuó yuèlái yuè fāngbiàn.", "sentence_source": "generated"}, {"text": "公司这几年飞跃发展，已经是大企业了。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的成绩在一个学期里有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā de chéngjì zài yí ge xuéqī lǐ yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "经过改革，当地的经济飞跃发展起来。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机技术飞跃发展，大家都用上了智能手机。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Shǒujī jìshù fēiyuè fāzhǎn, dàjiā dōu yòng shàng le zhìnéng shǒujī.", "sentence_source": "generated"}, {"text": "这个小镇的教育飞跃发展，孩子们都能上好学校。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了三个月，书法有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā liàn le sān ge yuè, shūfǎ yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "中国的高铁飞跃发展，出门坐车很快。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞跃了", "label": "体标"}, {"form": "飛躍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻义：事物发展迅速、进步很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃比喻事物发展迅速、进步很大，与“近十年”和“变化很大”相符。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：停滞指不再前进，与“变化很大”的语境矛盾。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：倒退指向后退步，与“变化很大”的发展说法冲突。"}, {"text": "萎缩", "is_correct": false, "explanation": "搭配：萎缩多指规模、市场缩小，不说“萎缩发展”。"}], "explanations": {"飞跃": "飞跃比喻事物发展迅速、进步很大，与“近十年”和“变化很大”相符。", "停滞": "语义：停滞指不再前进，与“变化很大”的语境矛盾。", "倒退": "语义：倒退指向后退步，与“变化很大”的发展说法冲突。", "萎缩": "搭配：萎缩多指规模、市场缩小，不说“萎缩发展”。"}, "sentence_index": 0, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年的身高飞跃了五厘米。", "explanation": "这里应该用〈增长〉。飞跃用于发展、水平等质的进步，身高这类数量的增长要用〈增长〉。"}, {"text": "小鸟从树枝飞跃到另一棵树上。", "explanation": "这里用的是本义，指小鸟跳过去，不是比喻义的事物迅速发展、进步很大。"}, {"text": "这个月我的体重飞跃了三公斤。", "explanation": "这里应该用〈增加〉。飞跃用于发展、水平，体重这类数量的变化要用〈增加〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃比喻技术迅速发展，与“大家都用上了智能手机”的结果相符。"}, {"text": "退化", "is_correct": false, "explanation": "语义：退化指变差、衰退，与“大家都用上了智能手机”的进步结果矛盾。"}, {"text": "停顿", "is_correct": false, "explanation": "语义：停顿指暂时停止，与“飞跃发展”所表示的快速进步相反，句意矛盾。"}, {"text": "徘徊", "is_correct": false, "explanation": "搭配：徘徊指原地来回走动，不说“徘徊发展”。"}], "explanations": {"飞跃": "飞跃比喻技术迅速发展，与“大家都用上了智能手机”的结果相符。", "退化": "语义：退化指变差、衰退，与“大家都用上了智能手机”的进步结果矛盾。", "停顿": "语义：停顿指暂时停止，与“飞跃发展”所表示的快速进步相反，句意矛盾。", "徘徊": "搭配：徘徊指原地来回走动，不说“徘徊发展”。"}, "sentence_index": 6, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园的面积飞跃了一倍。", "explanation": "这里应该用〈扩大〉。飞跃用于发展、进步，面积这类范围的变化要用〈扩大〉。"}, {"text": "这个月的电费飞跃了三成。", "explanation": "这里应该用〈上涨〉。飞跃用于发展、进步，费用和价格的上升要用〈上涨〉。"}, {"text": "图书馆的藏书飞跃了三万册。", "explanation": "这里应该用〈增多〉。飞跃用于发展、进步，藏书这类数量的增加要用〈增多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，我们公司被飞跃发展，业务越来越多。", "corrected_sentence": "这几年，我们公司飞跃发展，业务越来越多。", "error_description": "错误在“被”。飞跃是不及物动词，不能用“被”构成被动句。正确说法是“公司飞跃发展”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，中国的高铁把飞跃发展，出门坐车快多了。", "corrected_sentence": "这些年，中国的高铁飞跃发展，出门坐车快多了。", "error_description": "错误在“把”。飞跃是不及物动词，不能带“把”字的处置宾语。应去掉“把”，说“高铁飞跃发展”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境压力指自然环境或社会环境中对生物或人类造成负担、影响生存或发展的各种因素。", "primary_collocate": null, "pronunciation": "huán jìng yā lì", "ipa": "xwan˧˥ tɕiŋ˥˩ ja˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "这一历程并非线性前进，而是在资源危机、环境压力与科学突破的交织推动下，不断重构能源获取的范式。", "target_word": "环境压力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "城市里的环境压力越来越大。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼受不了水温变化带来的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境压力让很多小动物慢慢减少了。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的脏水给河里的鱼带来很大的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对环境压力，植物会长出更深的根。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用新办法，减轻了庄稼面临的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变暖是动物面临的环境压力之一。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口增加会加重人类面临的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林帮我们减轻环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境壓力", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自然或社会环境中影响生存发展的负担因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指自然或社会环境对生物造成的负担，与资源危机、科学突破的宏观语境相符。"}, {"text": "心理压力", "is_correct": false, "explanation": "语义：心理压力指个人的精神负担，与资源危机、科学突破的宏观语境不符。"}, {"text": "环境压迫", "is_correct": false, "explanation": "搭配：压迫多指人对人的强制，不说“环境压迫”。"}, {"text": "人际关系", "is_correct": false, "explanation": "语义：人际关系不是推动能源变革的力量，与“交织推动”的语境不符。"}], "explanations": {"环境压力": "环境压力指自然或社会环境对生物造成的负担，与资源危机、科学突破的宏观语境相符。", "心理压力": "语义：心理压力指个人的精神负担，与资源危机、科学突破的宏观语境不符。", "环境压迫": "搭配：压迫多指人对人的强制，不说“环境压迫”。", "人际关系": "语义：人际关系不是推动能源变革的力量，与“交织推动”的语境不符。"}, "sentence_index": 0, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头对地面的环境压力有一百公斤。", "explanation": "这里应该用〈重量〉。环境压力指环境对生物或人类造成的负担，不能用来说石头对地面的重量。"}, {"text": "小鸟在森林里唱歌，环境压力让它们很开心。", "explanation": "这里应该用〈环境舒适〉。环境压力指对生物造成负担、影响生存的因素，不会让小鸟开心。"}, {"text": "树上的苹果很甜，环境压力让它们长得很大。", "explanation": "这里应该用〈养分〉。环境压力指造成负担的因素，不能促进苹果生长；促进生长的是〈养分〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指环境对庄稼造成的负担，与“减轻了庄稼面临的”这一搭配相符。"}, {"text": "生活成本", "is_correct": false, "explanation": "语义：生活成本指日常开销，不能说“庄稼面临的生活成本”，句子语义不通。"}, {"text": "个人情绪", "is_correct": false, "explanation": "语义：个人情绪是心理状态，不是庄稼面临的环境负担，句子语义不通。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：利润是经营的结果，不说“庄稼面临的利润”。"}], "explanations": {"环境压力": "环境压力指环境对庄稼造成的负担，与“减轻了庄稼面临的”这一搭配相符。", "生活成本": "语义：生活成本指日常开销，不能说“庄稼面临的生活成本”，句子语义不通。", "个人情绪": "语义：个人情绪是心理状态，不是庄稼面临的环境负担，句子语义不通。", "利润": "搭配：利润是经营的结果，不说“庄稼面临的利润”。"}, "sentence_index": 6, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的环境压力很有名，很多人都来吃饭。", "explanation": "这里应该用〈名气〉。环境压力指造成负担的因素，不能用“有名”来形容餐厅；餐厅有名要用〈名气〉。"}, {"text": "湖水清澈见底，环境压力让鱼儿游得很欢快。", "explanation": "这里应该用〈环境优美〉。环境压力指造成负担、影响生存的因素，不会让鱼儿欢快。"}, {"text": "这首歌的环境压力很动听，大家都喜欢听。", "explanation": "这里应该用〈旋律〉。环境压力指造成负担的因素，不能用来形容歌曲动听；说歌曲动听要用〈旋律〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城市里有一座环境压力，让动物们不安。", "corrected_sentence": "城市里有一种环境压力，让动物们不安。", "error_description": "量词错误。“环境压力”不用量词“座”，应说“一种环境压力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农田里有一条环境压力，影响着庄稼。", "corrected_sentence": "农田里有一种环境压力，影响着庄稼。", "error_description": "量词错误。“环境压力”不用量词“条”，应说“一种环境压力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指不同的东西互相穿插、结合在一起。", "primary_collocate": null, "pronunciation": "jiāo zhī", "ipa": "tɕjɑʊ˥˥ ʈʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "这一历程并非线性前进，而是在资源危机、环境压力与科学突破的交织推动下，不断重构能源获取的范式。", "target_word": "交织", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "归根结底，蜜蜂的命运与人类的粮食安全紧密交织。", "target_word": "交织", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "她的脸上交织着高兴和紧张。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里，高楼和老街交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流在平原上交织成一张大网。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话声和说话声交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的雨声和风声交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里，历史和故事交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首音乐里，欢乐和悲伤交织。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田野里，小路和小河交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交织着", "label": "体标"}, {"form": "交织了", "label": "体标"}, {"form": "交织过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不同的事物互相穿插、结合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。"}, {"text": "脚趾", "is_correct": false, "explanation": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。"}, {"text": "角质", "is_correct": false, "explanation": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。"}, {"text": "校址", "is_correct": false, "explanation": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。"}, {"text": "姜汁", "is_correct": false, "explanation": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。", "脚趾": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。", "角质": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。", "校址": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。", "姜汁": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织”指多股力量互相穿插、共同作用，与“资源危机、环境压力与科学突破”并列作用的语境相符。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：“雪花”不是推动历程的力量，不能用于此处。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“推动”的动力应是力量或事件，“沉默”不能推动历程。"}, {"text": "闲聊", "is_correct": false, "explanation": "语域：“闲聊”是口语化的日常交谈，与这段书面、学术的论述语体不符。"}], "explanations": {"交织": "正确：“交织”指多股力量互相穿插、共同作用，与“资源危机、环境压力与科学突破”并列作用的语境相符。", "雪花": "语义：“雪花”不是推动历程的力量，不能用于此处。", "沉默": "搭配：“推动”的动力应是力量或事件，“沉默”不能推动历程。", "闲聊": "语域：“闲聊”是口语化的日常交谈，与这段书面、学术的论述语体不符。"}, "sentence_index": 0, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业交织给老师。", "explanation": "这里应该用〈交给〉。交织指事物互相穿插、结合；把东西转给别人要用交给。"}, {"text": "汤里交织着几粒沙子。", "explanation": "这里应该用〈夹杂〉。交织强调几股事物相互穿插、结合，外来的杂物混在汤里要用夹杂。"}, {"text": "几位同学交织着值日。", "explanation": "这里应该用〈轮换〉。交织不表示轮流承担，轮流值日要用轮换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。"}, {"text": "娇妻", "is_correct": false, "explanation": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。"}, {"text": "胶质", "is_correct": false, "explanation": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。"}, {"text": "教职", "is_correct": false, "explanation": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。"}, {"text": "胶纸", "is_correct": false, "explanation": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。", "娇妻": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。", "胶质": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。", "教职": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。", "胶纸": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织着”表示雨声和风声相互穿插、混在一起，与“着”搭配自然。"}, {"text": "聚集", "is_correct": false, "explanation": "搭配：“聚集”多用于人群或物体汇集，声音不说“聚集”。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“雨声和风声”的流动、声响相矛盾。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”指建筑或物体崩坏，不能用于声音。"}], "explanations": {"交织": "正确：“交织着”表示雨声和风声相互穿插、混在一起，与“着”搭配自然。", "聚集": "搭配：“聚集”多用于人群或物体汇集，声音不说“聚集”。", "静止": "语义：“静止”与“雨声和风声”的流动、声响相矛盾。", "倒塌": "搭配：“倒塌”指建筑或物体崩坏，不能用于声音。"}, "sentence_index": 6, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把信交织进了信封。", "explanation": "这里应该用〈装〉。交织指事物互相穿插、结合；把信放进信封要用装。"}, {"text": "两班人在门口交织工作。", "explanation": "这里应该用〈交接〉。交织不表示先后转交；两班人依次转交工作要用交接。"}, {"text": "老师把试卷交织给我们。", "explanation": "这里应该用〈发〉。交织指互相穿插、结合；把试卷分给学生要用发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山路在林子里交织一张网。", "corrected_sentence": "山路在林子里交织成一张网。", "error_description": "错误形式：“交织一张网”。正确形式：“交织成一张网”。“交织”后面要用“成”引出结果，再接宾语“一张网”，不能直接带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨丝和阳光交织窗前。", "corrected_sentence": "雨丝和阳光交织在窗前。", "error_description": "错误形式：“交织窗前”。正确形式：“交织在窗前”。表示处所时要用“在”引出，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
