INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然力指自然界中固有的、非人为的力量或能量，如风力、水力、太阳能等。", "primary_collocate": null, "pronunciation": "zì rán lì", "ipa": "tsɨ˥˩ ʐan˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "早期文明对可再生能源的利用，体现为对自然力的直接转化。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风力和水力都是自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人靠自然力推动水车磨米。", "target_word": "自然力", "complexity_tier": "T3", "furigana": "gǔ rén kào zìrànlì tuīdòng shuǐchē mó mǐ", "sentence_source": "generated"}, {"text": "人们用自然力发电，不用烧煤。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力有时很大，人很难挡住。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帆船靠自然力在海上前进。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能也是一种自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民很早就懂得利用自然力种地。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水冲走了桥，这就是自然力的作用。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代工厂尽量利用自然力，以减少污染。", "target_word": "自然力", "complexity_tier": "T3", "furigana": "xiàndài gōngchǎng jǐnliàng lìyòng zìrànlì, yǐ jiǎnshǎo wūrǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自然界固有的非人为力量或能量，如风力、水力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指自然界固有的非人为力量，与“可再生能源转化”的语境相符，是唯一能填入空格的词。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“转化”的对象须是能量或物质，时间不能被直接转化为能源，句子语义不通。"}, {"text": "文字", "is_correct": false, "explanation": "搭配：“转化”一般搭配能量、物质，“文字”不能被直接转化为能源，搭配不当。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩很重，与这句书面语的说明语气不协调。"}], "explanations": {"自然力": "自然力指自然界固有的非人为力量，与“可再生能源转化”的语境相符，是唯一能填入空格的词。", "时间": "语义：“转化”的对象须是能量或物质，时间不能被直接转化为能源，句子语义不通。", "文字": "搭配：“转化”一般搭配能量、物质，“文字”不能被直接转化为能源，搭配不当。", "玩意儿": "语域：“玩意儿”口语色彩很重，与这句书面语的说明语气不协调。"}, "sentence_index": 0, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂排放的废气污染了自然力。", "explanation": "这里应该用〈自然环境〉。“污染”的对象是环境，自然力指力量，不能被污染。"}, {"text": "这幅画用了很多鲜艳的自然力。", "explanation": "这里应该用〈颜色〉。自然力指自然界的力量或能量，不能用来画画。"}, {"text": "他跑完马拉松，只剩下一点自然力了。", "explanation": "这里应该用〈体力〉。自然力指自然界的力量，不指人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指自然界的力量，太阳能正属于此类，是唯一能填入的词。"}, {"text": "手机", "is_correct": false, "explanation": "语义：太阳能不是手机，“太阳能也是一种手机”语义不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是心理状态，不是自然界的力量，“太阳能也是一种心情”语义不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，不能说太阳能是一种体重，句子语义不通。"}], "explanations": {"自然力": "自然力指自然界的力量，太阳能正属于此类，是唯一能填入的词。", "手机": "语义：太阳能不是手机，“太阳能也是一种手机”语义不通。", "心情": "语义：心情是心理状态，不是自然界的力量，“太阳能也是一种心情”语义不通。", "体重": "语义：“体重”指人或物的重量，不能说太阳能是一种体重，句子语义不通。"}, "sentence_index": 6, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代工厂尽量节约自然力，以减少污染。", "explanation": "这里应该用〈能源〉。“节约”的对象是能源这类可消耗的资源，自然力是力量本身，不能说节约。"}, {"text": "他凭着好自然力跑完了全程马拉松。", "explanation": "这里应该用〈体能〉。跑完马拉松靠的是人的体能；自然力指自然界的力量，不指人的体能。"}, {"text": "他靠自然力考上了大学。", "explanation": "这里应该用〈天赋〉。自然力指自然界的力量，不指人的天赋或才能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台老水车靠一台自然力转动，不用电。", "corrected_sentence": "这台老水车靠一股自然力转动，不用电。", "error_description": "量词错误：“自然力”是抽象的力量，应用量词“股”；“台”用于机器，不能用来数自然力，这里应改为“股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一台自然力推动着帆船。", "corrected_sentence": "一股自然力推动着帆船。", "error_description": "量词错误：“自然力”是抽象的力量，应说“一股自然力”；“台”用于机器，不能用来数自然力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
