INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装置指为特定功能而组装、安装的器械、设备或系统。", "primary_collocate": null, "pronunciation": "zhuāng zhì", "ipa": "ʈʂwaŋ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "装置", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂里新装了一套净水装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套装置能把太阳能变成电。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一个很复杂的实验装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查报警装置有没有问题。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为病人准备了一套供氧装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥上安装着自动监测装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个装置很简单，学生自己就能做。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一个小装置给我们演示了电的原理。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车有一个安全装置，能保护司机。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "裝置", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为实现某种功能而组装安装的成套设备或系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为某种功能而组装的器械或设备，是所听到的词。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。"}, {"text": "专制", "is_correct": false, "explanation": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰（zhuāng shì）与装置（zhuāng zhì）第二音节声母不同（sh/zh），意思是打扮、点缀。"}], "explanations": {"装置": "装置指为某种功能而组装的器械或设备，是所听到的词。", "壮志": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。", "专制": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。", "装饰": "装饰（zhuāng shì）与装置（zhuāng zhì）第二音节声母不同（sh/zh），意思是打扮、点缀。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的设备，“发电装置”迁移到大陆架区域，语义通顺，是唯一能填入的词。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是心理状态，不能被“发电”，也不能被迁移到大陆架区域，句子语义不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是发电的设备，“发电书包”迁移至大陆架，语义不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能发电，也不能被迁移到大陆架，句子语义不通。"}], "explanations": {"装置": "装置指为特定功能而组装的设备，“发电装置”迁移到大陆架区域，语义通顺，是唯一能填入的词。", "心情": "语义：心情是心理状态，不能被“发电”，也不能被迁移到大陆架区域，句子语义不通。", "书包": "语义：书包不是发电的设备，“发电书包”迁移至大陆架，语义不通。", "歌曲": "语义：歌曲不能发电，也不能被迁移到大陆架，句子语义不通。"}, "sentence_index": 0, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们穿着全套装置，准备出发。", "explanation": "这里应该用〈装备〉。装备指人员随身使用的器材，可以穿戴；装置指安装好的设备，不能穿在身上。"}, {"text": "妈妈把洗好的衣服放进了装置里。", "explanation": "这里应该用〈衣柜〉。装置指为特定功能安装的器械设备，不是放衣服的家具。"}, {"text": "这位同学会弹一种装置。", "explanation": "这里应该用〈乐器〉。装置指安装好的器械设备，不是可以演奏的乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的器械或设备，是所听到的词。"}, {"text": "专职", "is_correct": false, "explanation": "专职（zhuān zhí）与装置（zhuāng zhì）韵母不同（an/ang），第二音节声调也不同，意思是专门担任某项工作。"}, {"text": "庄子", "is_correct": false, "explanation": "庄子（zhuāng zi）与装置（zhuāng zhì）第一音节相同，第二音节 zi/zhì 不同，指古代思想家庄周或其著作。"}, {"text": "状子", "is_correct": false, "explanation": "状子（zhuàng zi）与装置（zhuāng zhì）第一音节声调不同，第二音节 zi/zhì 不同，意思是诉状。"}], "explanations": {"装置": "装置指为特定功能而组装的器械或设备，是所听到的词。", "专职": "专职（zhuān zhí）与装置（zhuāng zhì）韵母不同（an/ang），第二音节声调也不同，意思是专门担任某项工作。", "庄子": "庄子（zhuāng zi）与装置（zhuāng zhì）第一音节相同，第二音节 zi/zhì 不同，指古代思想家庄周或其著作。", "状子": "状子（zhuàng zi）与装置（zhuāng zhì）第一音节声调不同，第二音节 zi/zhì 不同，意思是诉状。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的设备，“自动监测装置”安装在桥上，语义通顺，是唯一能填入的词。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是监测设备，“自动监测厨房”语义不通。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“监测”一般搭配设备、数据、信号，“饮料”不能被自动监测，搭配不当。"}, {"text": "书本", "is_correct": false, "explanation": "语义：桥上安装的设备不能去监测书本，“自动监测书本”语义不通。"}], "explanations": {"装置": "装置指为特定功能而组装的设备，“自动监测装置”安装在桥上，语义通顺，是唯一能填入的词。", "厨房": "语义：厨房不是监测设备，“自动监测厨房”语义不通。", "饮料": "搭配：“监测”一般搭配设备、数据、信号，“饮料”不能被自动监测，搭配不当。", "书本": "语义：桥上安装的设备不能去监测书本，“自动监测书本”语义不通。"}, "sentence_index": 6, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在玩具店挑选了一个新装置。", "explanation": "这里应该用〈玩具〉。装置指器械设备，不是供孩子玩的东西。"}, {"text": "这家餐厅的菜单上有一道新装置。", "explanation": "这里应该用〈菜〉。装置不是食物，不能出现在菜单的菜品中。"}, {"text": "他用装置唱了一首歌。", "explanation": "这里应该用〈嗓子〉。唱歌要用嗓子，装置是器械设备，不能用来唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人仔细检查了一条报警装置。", "corrected_sentence": "工人仔细检查了一套报警装置。", "error_description": "量词错误：装置是成套的设备，应说“一套”；“条”用于细长的东西，不能用于装置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间里多了一把自动装置。", "corrected_sentence": "车间里多了一套自动装置。", "error_description": "量词错误：装置是成套的设备，应说“一套”；“把”用于有柄的器具，不能用于装置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体由于机械运动而具有的能量。", "primary_collocate": null, "pronunciation": "dòng néng", "ipa": "tʊŋ˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "动能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "球滚得越快，动能就越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车的速度快，动能也大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水从高处流下来，位能变成了动能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理课上，老师讲了动能和位能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风的动能可以用来发电。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "质量越大，物体的动能越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停下来以后，它的动能就没有了。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把石头扔出去，石头获得了很大的动能。", "target_word": "动能", "complexity_tier": "T3", "furigana": "tā bǎ shítou rēng chūqù, shítou huòdé le hěn dà de dòngnéng.", "sentence_source": "generated"}, {"text": "运动员跑得快，身体的动能很大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物理学中物体因机械运动而具有的能量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。叶片捕捉的是气流的运动能量，用来驱动磨坊。"}, {"text": "电能", "is_correct": false, "explanation": "语义：气流本身不含电能，叶片捕捉的是气流的运动能量，而不是电。"}, {"text": "阻力", "is_correct": false, "explanation": "搭配：“捕捉”的对象是能量，不能说捕捉“阻力”，而且驱动磨坊需要能量。"}, {"text": "水分", "is_correct": false, "explanation": "语义：气流不能提供水分来驱动磨坊，“捕捉气流水分”的说法与前后语境不相符。"}], "explanations": {"动能": "正确。叶片捕捉的是气流的运动能量，用来驱动磨坊。", "电能": "语义：气流本身不含电能，叶片捕捉的是气流的运动能量，而不是电。", "阻力": "搭配：“捕捉”的对象是能量，不能说捕捉“阻力”，而且驱动磨坊需要能量。", "水分": "语义：气流不能提供水分来驱动磨坊，“捕捉气流水分”的说法与前后语境不相符。"}, "sentence_index": 0, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的动能很强，车跑得很快。", "explanation": "这里应该用〈动力〉。动能指运动物体本身所具有的能量，说发动机推动车辆的能力要用动力。"}, {"text": "这块电池储存了很多动能。", "explanation": "这里应该用〈能量〉。电池储存的是化学能，不是运动物体的动能，应说储存了很多能量。"}, {"text": "这块石头放在山顶上，它的动能很大。", "explanation": "这里应该用〈势能〉。石头静止在山顶，具有的是重力势能，动能指运动物体的能量，静止的石头没有动能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。句子说的是质量与物体动能之间的关系。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“越大”说的是大小或程度，颜色不能这样描述，而且颜色与质量无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有大小可言，也不会随质量变化，“物体的名字越大”说不通。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：形状不用“越大”来描述，这里的“越大”说的是大小或程度。"}], "explanations": {"动能": "正确。句子说的是质量与物体动能之间的关系。", "颜色": "搭配：“越大”说的是大小或程度，颜色不能这样描述，而且颜色与质量无关。", "名字": "语义：名字没有大小可言，也不会随质量变化，“物体的名字越大”说不通。", "形状": "搭配：形状不用“越大”来描述，这里的“越大”说的是大小或程度。"}, "sentence_index": 6, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的动能很大，能一口气举起两百公斤的杠铃。", "explanation": "这里应该用〈力气〉。动能指运动物体的能量，人能举起重物靠的是力气，不能说动能。"}, {"text": "这辆车的动能很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。动能是能量的大小，只能说大或小，描述快慢要用速度。"}, {"text": "这个学生的动能很大，什么难题都能解决。", "explanation": "这里应该用〈能力〉。动能指运动物体的能量，说一个人的本领要用能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗子弹具有很快的动能。", "corrected_sentence": "这颗子弹具有很大的动能。", "error_description": "搭配错误：动能是能量，只能说大小，不能说“快”。应把“很快”改为“很大”，说“很大的动能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一脚把球踢出去，球就获得了一只动能。", "corrected_sentence": "他一脚把球踢出去，球就获得了一点动能。", "error_description": "量词错误：“动能”是抽象的量，数量常用“点”来计量；“只”用于动物或成对、成套的器物，不能用来数动能。错误在于量词“只”，应为“一点动能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "磨坊是加工谷物，把小麦等磨成面粉的作坊。", "primary_collocate": null, "pronunciation": "mò fáng", "ipa": "mwo˥˩ faŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物。", "target_word": "磨坊", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "村口有一座老磨坊，农民常把小麦送到那里磨面。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里的水车一直转着，面粉越磨越多。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲在磨坊工作了三十年。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座磨坊靠风力推动石磨。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常去外婆家旁边的磨坊玩。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊的主人每天早上都要检查石磨。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里到处是白白的面粉。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的磨坊现在成了一家小博物馆。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个磨坊需要很多水才能带动水车。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "作坊：把小麦等谷物磨成面粉的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：靠风力或水力推动石磨、加工谷物的作坊，与句中“碾磨谷物”相符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不能碾磨谷物，“驱动船碾磨谷物”说不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“驱动”后接的应是能碾磨谷物的装置，水泥不能用来碾磨谷物。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是读书的地方，不能碾磨谷物。"}], "explanations": {"磨坊": "磨坊：靠风力或水力推动石磨、加工谷物的作坊，与句中“碾磨谷物”相符。", "船": "语义：船不能碾磨谷物，“驱动船碾磨谷物”说不通。", "水泥": "搭配：“驱动”后接的应是能碾磨谷物的装置，水泥不能用来碾磨谷物。", "书房": "语义：书房是读书的地方，不能碾磨谷物。"}, "sentence_index": 0, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家磨坊每天修好几十辆自行车。", "explanation": "这里应该用〈修车铺〉。磨坊是把谷物磨成面粉的作坊，修自行车的地方要说〈修车铺〉。"}, {"text": "这家磨坊每天织出几百米布。", "explanation": "这里应该用〈织布厂〉。磨坊加工谷物，织布的地方要说〈织布厂〉。"}, {"text": "这家磨坊每天做很多桌椅。", "explanation": "这里应该用〈家具厂〉。磨坊是磨面粉的作坊，做桌椅的地方要说〈家具厂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：加工谷物的作坊，主人要检查石磨，与句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行没有石磨，“银行的主人检查石磨”说不通。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆与石磨无关，“体育馆的主人检查石磨”说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“检查石磨”说明主体是磨坊或作坊之类的场所，钢琴不搭配。"}], "explanations": {"磨坊": "磨坊：加工谷物的作坊，主人要检查石磨，与句意相符。", "银行": "语义：银行没有石磨，“银行的主人检查石磨”说不通。", "体育馆": "语义：体育馆与石磨无关，“体育馆的主人检查石磨”说不通。", "钢琴": "搭配：“检查石磨”说明主体是磨坊或作坊之类的场所，钢琴不搭配。"}, "sentence_index": 6, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家磨坊每天烤出几百个面包，香味飘满了街道。", "explanation": "这里应该用〈面包房〉。磨坊只磨面粉，烤面包要用〈面包房〉。"}, {"text": "这家磨坊每天熬出几百斤白糖。", "explanation": "这里应该用〈糖坊〉。磨坊加工谷物，熬制白糖要用〈糖坊〉。"}, {"text": "这家磨坊每天酿出几百斤白酒。", "explanation": "这里应该用〈酒坊〉。磨坊不酿酒，酿白酒要说〈酒坊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村东头有一只磨坊，很多年没人用了。", "corrected_sentence": "村东头有一座磨坊，很多年没人用了。", "error_description": "量词错误：磨坊前应用“座”，不能用“只”（“只”多用于动物或成对的物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山脚下有一头老磨坊，已经三百多年了。", "corrected_sentence": "山脚下有一座老磨坊，已经三百多年了。", "error_description": "量词错误：磨坊前应用“座”，不能用“头”（“头”用于牛、猪等动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具把东西压碎或磨成粉末。", "primary_collocate": null, "pronunciation": "niǎn mó", "ipa": "njɛn˨˩˦ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "农民用石磨碾磨小麦，做成面粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用石磨碾磨玉米，准备做饼。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能把豆子碾磨成粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人用大石头碾磨粮食。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水车的力量带动石磨碾磨麦子。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把药材碾磨了很久，终于变成细粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里有人碾磨着新收的稻谷。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆要先碾磨，再用热水冲泡。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在碾磨石灰石，准备做水泥。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碾磨了", "label": "完成体"}, {"form": "碾磨着", "label": "持续体"}, {"form": "碾磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用石磨、机器等工具把谷物、药材等压碎磨成粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45c25686-c5ad-4d03-8fbd-51e08612bbaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "语义：收割是在田里割取作物，磨坊不进行收割，句中指的是加工环节。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：用磨具把谷物压碎磨成粉，与磨坊的加工作用相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”一般只与液体或饮品搭配，不能与固体谷物搭配。"}, {"text": "生长", "is_correct": false, "explanation": "配价：生长是不及物动词，不能带宾语“谷物”。"}], "explanations": {"收割": "语义：收割是在田里割取作物，磨坊不进行收割，句中指的是加工环节。", "碾磨": "碾磨：用磨具把谷物压碎磨成粉，与磨坊的加工作用相符。", "喝": "搭配：“喝”一般只与液体或饮品搭配，不能与固体谷物搭配。", "生长": "配价：生长是不及物动词，不能带宾语“谷物”。"}, "sentence_index": 0, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把刀碾磨得很锋利。", "explanation": "这里应该用〈磨〉。磨刀是使刀口变锋利，碾磨是把东西压碎成粉末，不能用于刀具。"}, {"text": "这台压路机能把路面碾磨平整。", "explanation": "这里应该用〈碾压〉。碾压指用重物滚压使表面平整，碾磨指压成粉末，路面不会变成粉末。"}, {"text": "奶奶用擀面杖把面团碾磨成薄饼。", "explanation": "这里应该用〈擀〉。擀是用擀面杖把面团压成薄饼，碾磨是把东西磨成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：煮只能使药材变软、出味，不能把药材磨成细粉。"}, {"text": "站", "is_correct": false, "explanation": "配价：站是不及物动词，不能带宾语“药材”，也不能用于“把”字句。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：压碎磨成粉，与“终于变成细粉”的结果相呼应。"}, {"text": "浸泡", "is_correct": false, "explanation": "语义：浸泡是让药材泡在水里，不会使药材变成细粉。"}], "explanations": {"煮": "语义：煮只能使药材变软、出味，不能把药材磨成细粉。", "站": "配价：站是不及物动词，不能带宾语“药材”，也不能用于“把”字句。", "碾磨": "碾磨：压碎磨成粉，与“终于变成细粉”的结果相呼应。", "浸泡": "语义：浸泡是让药材泡在水里，不会使药材变成细粉。"}, "sentence_index": 6, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想这个问题碾磨了很久，还是没有结论。", "explanation": "这里应该用〈琢磨〉。琢磨指反复思考问题，碾磨只用于把实物压碎磨成粉末，不能与抽象问题搭配。"}, {"text": "他把牛奶碾磨了一遍，然后喝掉了。", "explanation": "这里应该用〈搅〉。碾磨只能把固体压成粉末，牛奶是液体，不能碾磨。"}, {"text": "工人用砂纸把铁器碾磨得很光亮。", "explanation": "这里应该用〈抛光〉。抛光是使表面光滑发亮，碾磨是把东西压成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把黄豆碾磨很细。", "corrected_sentence": "妈妈把黄豆碾磨得很细。", "error_description": "“碾磨很细”缺少“得”。动词带程度补语时，动词与补语之间要用“得”，正确形式为“碾磨得很细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器昨天把玉米碾磨了成粗粉。", "corrected_sentence": "这台机器昨天把玉米碾磨成了粗粉。", "error_description": "“了”位置错误。完成标记“了”应放在补语“成”之后，正确形式为“碾磨成了粗粉”，不能放在动词与补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
