INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地表长期积水、生长湿生植物的低洼地带。", "primary_collocate": null, "pronunciation": "zhǎo zé", "ipa": "tʂɑʊ˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "沼泽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片沼泽很大，人走进去会陷住。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沼泽里长着很多草，还有小鸟。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林旁边有一大片沼泽。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，这里变成了沼泽，车开不过去。", "target_word": "沼泽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们小心地走过沼泽，因为一不小心就会陷进去。", "target_word": "沼泽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家公园里有一片沼泽，是很多鸟的家。", "target_word": "沼泽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沼泽地很软，我们不能骑车进去。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，千万别在沼泽边玩。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，沼泽里的水多了，青蛙开始叫。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片沼泽", "label": "量词"}, {"form": "沼泽地", "label": "复合"}, {"form": "沼澤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长期积水、长着湿生植物的低洼地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45c25686-c5ad-4d03-8fbd-51e08612bbaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沼泽", "is_correct": true, "explanation": "正确：沼泽是地表长期积水、长着湿生植物的低洼地带，可以说“抽排沼泽积水”。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干燥，没有积水可以抽排。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“积水”指低洼处的积水，不能说“海洋积水”。"}, {"text": "山峰", "is_correct": false, "explanation": "搭配：山峰地势高，不会积水，不能说“山峰积水”。"}], "explanations": {"沼泽": "正确：沼泽是地表长期积水、长着湿生植物的低洼地带，可以说“抽排沼泽积水”。", "沙漠": "语义：沙漠干燥，没有积水可以抽排。", "海洋": "搭配：“积水”指低洼处的积水，不能说“海洋积水”。", "山峰": "搭配：山峰地势高，不会积水，不能说“山峰积水”。"}, "sentence_index": 0, "correct_answer": "沼泽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口有一座沼泽，夏天蚊子很多。", "explanation": "这里量词应该用〈片〉。〈座〉用于山、楼房等，沼泽是一片低洼的地，不能用“座”。"}, {"text": "妈妈在沼泽里煮了一锅汤。", "explanation": "这里应该用〈厨房〉。沼泽是低洼湿地，无法在里面做饭。"}, {"text": "他把沼泽倒进杯子里，喝了一口。", "explanation": "这里应该用〈水〉。沼泽是一片地，不是液体，不能倒进杯子里喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沼泽", "is_correct": true, "explanation": "正确：沼泽是鸟类栖息的湿地，与“很多鸟的家”相符。"}, {"text": "戈壁", "is_correct": false, "explanation": "语义：戈壁干旱少水，与“很多鸟的家”不符。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川是冰雪覆盖的地方，很少有鸟在那里安家。"}, {"text": "沙丘", "is_correct": false, "explanation": "搭配：沙丘少有水源和植被，“很多鸟的家”与沙丘搭配不当。"}], "explanations": {"沼泽": "正确：沼泽是鸟类栖息的湿地，与“很多鸟的家”相符。", "戈壁": "语义：戈壁干旱少水，与“很多鸟的家”不符。", "冰川": "语义：冰川是冰雪覆盖的地方，很少有鸟在那里安家。", "沙丘": "搭配：沙丘少有水源和植被，“很多鸟的家”与沙丘搭配不当。"}, "sentence_index": 6, "correct_answer": "沼泽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把沼泽折成了一只纸鹤。", "explanation": "这里应该用〈纸〉。沼泽是低洼的地，不是可以折叠的材料，不能折成纸鹤。"}, {"text": "我们在一间沼泽旁边搭了帐篷。", "explanation": "这里量词应该用〈片〉。〈间〉用于房屋，沼泽是一片地，不能用“间”。"}, {"text": "他爬上了沼泽的顶上，看到了远处的村子。", "explanation": "这里应该用〈山〉。沼泽是低洼的湿地，没有“顶”，不能爬上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面有一只沼泽，大家别过去。", "corrected_sentence": "前面有一片沼泽，大家别过去。", "error_description": "“沼泽”是一片地，量词应用“片”，不用“只”；“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗跑进了沼泽上。", "corrected_sentence": "小狗跑进了沼泽里。", "error_description": "“跑进”后面要用“里”表示进入的范围，“沼泽上”指表面，不能说“跑进沼泽上”，应说“跑进沼泽里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
