INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指积聚在地面或低洼处的水。", "primary_collocate": null, "pronunciation": "jī shuǐ", "ipa": "tɕi˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "雨太大了，工人整夜都在排走路口的积水。", "target_word": "积水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨以后，路上有很多积水。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在清理地下室的积水。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，那里有积水，别踩进去。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "积水太深，汽车开不过去。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，院子里的积水慢慢变少。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，积水里容易生蚊子。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用水泵把积水抽走了。", "target_word": "积水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的积水很脏，孩子不要玩。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶有洞，房间里到处是积水。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一摊积水", "label": "量词"}, {"form": "一片积水", "label": "量词"}, {"form": "積水", "label": "繁体"}], "register": "中性", "sense_fingerprint": "积聚在地面或低洼处的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45c25686-c5ad-4d03-8fbd-51e08612bbaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "积水", "is_correct": true, "explanation": "正确。积水是积在地面的水，大雨后路口的积水需要排走。"}, {"text": "电力", "is_correct": false, "explanation": "语义：电力不是水，不能被抽排。"}, {"text": "木料", "is_correct": false, "explanation": "语义：木料是固体，不能被抽排。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：大雨后路口不会有粮食需要排走，“排走”用于水等液体。"}], "explanations": {"积水": "正确。积水是积在地面的水，大雨后路口的积水需要排走。", "电力": "语义：电力不是水，不能被抽排。", "木料": "语义：木料是固体，不能被抽排。", "粮食": "语义：大雨后路口不会有粮食需要排走，“排走”用于水等液体。"}, "sentence_index": 0, "correct_answer": "积水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的积水很厚，我们花了一上午才扫完。", "explanation": "这里应该用〈积雪〉。积雪可以堆得很厚；积水是地上积聚的水，应说“深”，不说“厚”。"}, {"text": "积水冲毁了桥。", "explanation": "这里应该用〈洪水〉。洪水是奔流的大水，能冲毁东西；积水静止不流，不能说“冲毁”。"}, {"text": "妈妈用积水煮了一锅粥。", "explanation": "这里应该用〈清水〉。积水是积在地面的水，不干净，不能用来煮粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "积水", "is_correct": true, "explanation": "正确。蚊子要在水里产卵，夏天的积水里容易生蚊子。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：蚊子要在水中繁殖，冰块里不会生蚊子。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：蚊子要在水中产卵，干沙子里不会生蚊子。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是干的粉末，蚊子不在面粉里繁殖。"}], "explanations": {"积水": "正确。蚊子要在水里产卵，夏天的积水里容易生蚊子。", "冰块": "语义：蚊子要在水中繁殖，冰块里不会生蚊子。", "沙子": "语义：蚊子要在水中产卵，干沙子里不会生蚊子。", "面粉": "语义：面粉是干的粉末，蚊子不在面粉里繁殖。"}, "sentence_index": 6, "correct_answer": "积水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动以后，他的额头上全是积水。", "explanation": "这里应该用〈汗水〉。积水是积在地面的水，不会从身体上流出来。"}, {"text": "这摊积水很甜，孩子们都抢着喝。", "explanation": "这里应该用〈泉水〉。泉水是从地下涌出的清水，可以直接喝；积水积在地面，不能喝，也不能说“甜”。"}, {"text": "她哭得满脸都是积水。", "explanation": "这里应该用〈泪水〉。泪水是眼睛流出的水，积水不能说“满脸都是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口的路面上有两只积水。", "corrected_sentence": "门口的路面上有两摊积水。", "error_description": "量词错误：「两只积水」应为「两摊积水」。“只”用于动物或成对的东西，积水要用“摊”或“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把地下室的积水排了走。", "corrected_sentence": "工人把地下室的积水排走了。", "error_description": "了的位置错误：「排了走」应为「排走了」。结果补语“走”要紧跟动词，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
