INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "化石是古代生物的遗骸或遗迹，经过长时间的地质作用形成的石头状物体。", "primary_collocate": null, "pronunciation": "huà shí", "ipa": "xwa˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这种鱼的化石在岩层里保存得很好。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命后，化石能源的暴发性使用掩盖了可再生能源的发展轨迹。", "target_word": "化石", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "山上发现了一块恐龙化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多古代鱼的化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块化石已经有一亿年的历史了。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在海边找到了一块贝壳化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化石能告诉我们很久以前的生活。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那块小化石放在桌子上。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在石头里发现了一片叶子化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这些化石中，专家知道那种动物吃草。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "古代生物遗骸或遗迹经地质作用形成的石质物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确答案：化石，指古代生物的遗骸或遗迹经地质作用形成的石头状物体。"}, {"text": "画室", "is_correct": false, "explanation": "声调：画室 huàshì 与化石 huà shí 只有第二个音节不同（第四声与第二声），画室指画画的房间。"}, {"text": "画师", "is_correct": false, "explanation": "声调：画师 huàshī 与化石 huà shí 只有第二个音节不同（第一声与第二声），画师指画家。"}, {"text": "滑石", "is_correct": false, "explanation": "声调：滑石 huáshí 与化石 huà shí 只有第一个音节不同（第二声与第四声），滑石是一种矿物。"}], "explanations": {"化石": "正确答案：化石，指古代生物的遗骸或遗迹经地质作用形成的石头状物体。", "画室": "声调：画室 huàshì 与化石 huà shí 只有第二个音节不同（第四声与第二声），画室指画画的房间。", "画师": "声调：画师 huàshī 与化石 huà shí 只有第二个音节不同（第一声与第二声），画师指画家。", "滑石": "声调：滑石 huáshí 与化石 huà shí 只有第一个音节不同（第二声与第四声），滑石是一种矿物。"}, "sentence_index": null, "correct_answer": "化石"}, "level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确：化石指古代生物的遗骸或遗迹经地质作用形成的石头，“这种鱼的化石”与句意相符。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：恐龙是另一类已灭绝的动物，“这种鱼的恐龙”不成立，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能在岩层里保存，“这种鱼的声音在岩层里保存得很好”句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是鱼的遗留物，“这种鱼的太阳”不成词，句意不通。"}], "explanations": {"化石": "正确：化石指古代生物的遗骸或遗迹经地质作用形成的石头，“这种鱼的化石”与句意相符。", "恐龙": "语义：恐龙是另一类已灭绝的动物，“这种鱼的恐龙”不成立，句意不通。", "声音": "语义：声音不能在岩层里保存，“这种鱼的声音在岩层里保存得很好”句意不通。", "太阳": "语义：太阳不是鱼的遗留物，“这种鱼的太阳”不成词，句意不通。"}, "sentence_index": 0, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用化石刷牙。", "explanation": "这里应该用〈牙刷〉。化石是古代生物遗骸形成的石头，不是刷牙的工具。"}, {"text": "这座古城的化石已经有几千年了。", "explanation": "这里应该用〈遗迹〉。化石指古代生物的遗骸，城墙、宫殿等人类建筑的遗迹不能称为化石。"}, {"text": "这座博物馆收藏着很多唐代的化石。", "explanation": "这里应该用〈文物〉。化石是古代生物留下的，唐代的器物属于文物，不能称为化石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确答案：化石，指古代生物的遗骸或遗迹经地质作用形成的石头状物体。"}, {"text": "花市", "is_correct": false, "explanation": "声调：花市 huāshì 与化石 huà shí 两个音节的声调都不同，花市指卖花的市场。"}, {"text": "华氏", "is_correct": false, "explanation": "声调：华氏 huáshì 与化石 huà shí 两个音节的声调都不同，华氏是温度单位。"}, {"text": "花饰", "is_correct": false, "explanation": "声调：花饰 huāshì 与化石 huà shí 两个音节的声调都不同，花饰指花纹装饰。"}], "explanations": {"化石": "正确答案：化石，指古代生物的遗骸或遗迹经地质作用形成的石头状物体。", "花市": "声调：花市 huāshì 与化石 huà shí 两个音节的声调都不同，花市指卖花的市场。", "华氏": "声调：华氏 huáshì 与化石 huà shí 两个音节的声调都不同，华氏是温度单位。", "花饰": "声调：花饰 huāshì 与化石 huà shí 两个音节的声调都不同，花饰指花纹装饰。"}, "sentence_index": null, "correct_answer": "化石"}, "level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确：化石是古代生物的遗迹，能够告诉人们很久以前的生活。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能告诉人们过去的生活，句子不通。"}, {"text": "手套", "is_correct": false, "explanation": "配价：“告诉”要求能传递信息的主语，手套不符合这一要求。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是能提供历史信息的事物，与“告诉我们很久以前的生活”不相容。"}], "explanations": {"化石": "正确：化石是古代生物的遗迹，能够告诉人们很久以前的生活。", "冰箱": "语义：冰箱不能告诉人们过去的生活，句子不通。", "手套": "配价：“告诉”要求能传递信息的主语，手套不符合这一要求。", "椅子": "语义：椅子不是能提供历史信息的事物，与“告诉我们很久以前的生活”不相容。"}, "sentence_index": 6, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架飞机的化石被找到了。", "explanation": "这里应该用〈残骸〉。化石是古代生物的遗骸形成的石头，飞机的残骸不是化石。"}, {"text": "妈妈用化石煮了一锅汤，大家都说好吃。", "explanation": "这里应该用〈食物〉。化石是古代生物遗骸形成的石头，不能煮来吃。"}, {"text": "这台化石坏了，需要修理。", "explanation": "这里应该用〈电器〉。化石是古代生物遗骸形成的石头，不能指需要修理的机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在河边找到了一只化石。", "corrected_sentence": "他在河边找到了一块化石。", "error_description": "量词错误：化石应用量词“块”，“只”用于动物，这里应改为“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物馆把一只化石放进了展柜。", "corrected_sentence": "博物馆把一块化石放进了展柜。", "error_description": "量词错误：化石应用量词“块”，“只”用于动物，这里应改为“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
