INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13680, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示在某处可以看到或出现。", "primary_collocate": null, "pronunciation": "jiàn yú", "ipa": "tɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "与此同时，被动式太阳能设计已见于古代建筑——厚重大理石墙体吸收日间热量，夜间缓慢释放，形成天然温控系统。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种花只见于南方的山区。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事见于很多古书。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类似的说法也见于报纸。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟多见于湖边。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字见于这本书的第一页。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种习惯常见于老年人。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的画只见于古代的寺庙。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词多见于书面语。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类错误常见于新手。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "在某处（书、地方、人群）可以看到或出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。见于（jiàn yú）：表示在某处可以看到或出现。"}, {"text": "限于", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是局限在。"}, {"text": "间于", "is_correct": false, "explanation": "jiān 与 jiàn 声调不同（一声与四声），意思是处在两者之间。"}, {"text": "先于", "is_correct": false, "explanation": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是在……之前。"}], "explanations": {"见于": "正确答案。见于（jiàn yú）：表示在某处可以看到或出现。", "限于": "xiàn 与 jiàn 声母不同（x 与 j），意思是局限在。", "间于": "jiān 与 jiàn 声调不同（一声与四声），意思是处在两者之间。", "先于": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是在……之前。"}, "sentence_index": null, "correct_answer": "见于"}, "level_3": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。“见于”表示在某处出现，与“古代建筑”搭配，句意通顺。"}, {"text": "出生于", "is_correct": false, "explanation": "语义：出生于要求人或动物作主语，设计方案不能出生。"}, {"text": "毕业于", "is_correct": false, "explanation": "语义：毕业于指完成学校学业，与“设计”“古代建筑”无关。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：位于指事物处于某个地理位置，抽象的设计不能说位于建筑。"}], "explanations": {"见于": "正确答案。“见于”表示在某处出现，与“古代建筑”搭配，句意通顺。", "出生于": "语义：出生于要求人或动物作主语，设计方案不能出生。", "毕业于": "语义：毕业于指完成学校学业，与“设计”“古代建筑”无关。", "位于": "搭配：位于指事物处于某个地理位置，抽象的设计不能说位于建筑。"}, "sentence_index": 0, "correct_answer": "见于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在窗前见于远处的山。", "explanation": "这里应该用〈看到〉。见于表示事物出现在某处（书刊、地方），不表示用眼睛看见。"}, {"text": "这所学校见于城东，离地铁站很近。", "explanation": "这里应该用〈位于〉。见于表示事物在某处出现或被看到，说地点的位置要用“位于”。"}, {"text": "我昨天在街上见于很多人。", "explanation": "这里应该用〈看见〉。见于不能带人作宾语来表示看见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13680, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。见于（jiàn yú）：表示在某处可以看到或出现。"}, {"text": "便于", "is_correct": false, "explanation": "biàn 与 jiàn 韵母、声调相同，声母不同（b 与 j），意思是方便做某事。"}, {"text": "免于", "is_correct": false, "explanation": "miǎn 与 jiàn 声母不同（m 与 j）且声调不同（三声与四声），意思是避免遭受。"}, {"text": "陷于", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是落入（困境）。"}], "explanations": {"见于": "正确答案。见于（jiàn yú）：表示在某处可以看到或出现。", "便于": "biàn 与 jiàn 韵母、声调相同，声母不同（b 与 j），意思是方便做某事。", "免于": "miǎn 与 jiàn 声母不同（m 与 j）且声调不同（三声与四声），意思是避免遭受。", "陷于": "xiàn 与 jiàn 声母不同（x 与 j），意思是落入（困境）。"}, "sentence_index": null, "correct_answer": "见于"}, "level_3": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。“见于”表示在某处出现，与“常”和“老年人”搭配，句意通顺。"}, {"text": "居住于", "is_correct": false, "explanation": "语义：居住于要求有生命的主体，习惯不能居住。"}, {"text": "生活于", "is_correct": false, "explanation": "语义：生活于指人或动物的活动，习惯不是生命体。"}, {"text": "出没于", "is_correct": false, "explanation": "搭配：出没于常用于人或动物在某地活动，不能用于习惯。"}], "explanations": {"见于": "正确答案。“见于”表示在某处出现，与“常”和“老年人”搭配，句意通顺。", "居住于": "语义：居住于要求有生命的主体，习惯不能居住。", "生活于": "语义：生活于指人或动物的活动，习惯不是生命体。", "出没于": "搭配：出没于常用于人或动物在某地活动，不能用于习惯。"}, "sentence_index": 6, "correct_answer": "见于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都见于跑步。", "explanation": "这里应该用〈进行〉或〈在……跑步〉。见于是表示出现在某处的动词，后面不能接动作。"}, {"text": "明天的会议见于下午三点。", "explanation": "这里应该用〈定于〉。见于不用于安排时间，表示时间安排要用“定于”或“在”。"}, {"text": "他1990年见于北京。", "explanation": "这里应该用〈生于〉。见于表示事物在某处出现或被看到，不表示人在某地出生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个说法见于了《史记》。", "corrected_sentence": "这个说法见于《史记》。", "error_description": "错误形式：见于了。正确形式：见于。“见于”本身表示出现在某处，后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个字很见于唐代的文献。", "corrected_sentence": "这个字见于唐代的文献。", "error_description": "错误：“很见于”。正确：“见于”。“很”是程度副词，修饰形容词或部分心理动词，不能修饰表示出现的动词“见于”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
