INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种天然石材，主要成分是方解石，质地坚硬，表面常有花纹，常用于建筑和装饰材料。", "primary_collocate": null, "pronunciation": "dà lǐ shí", "ipa": "ta˥˩ li˨˩˦ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "与此同时，被动式太阳能设计已见于古代建筑——厚重大理石墙体吸收日间热量，夜间缓慢释放，形成天然温控系统。", "target_word": "大理石", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个厨房的桌面是用大理石做的。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆的地面铺着白色大理石。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块大理石放在客厅里。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大理石很硬，也很漂亮，所以价格不便宜。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大理石雕像已经有两百年了。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大理石的地板冬天踩上去很凉。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在把大理石搬进新房子。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南大理出产的大理石很有名。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，大理石地面很滑，要小心。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "大理石桌面", "label": "复合"}, {"form": "大理石地板", "label": "复合"}], "register": "中性", "sense_fingerprint": "有花纹的坚硬天然石材，用于建筑装饰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大理石", "is_correct": true, "explanation": "大理石：厚重的天然石材，能吸收并缓慢释放热量，符合句意。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫很轻，与“厚重”矛盾，也不能蓄存热量。"}, {"text": "纸板", "is_correct": false, "explanation": "语义：纸板很薄，无法像墙体那样吸收并释放热量。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：冰会融化，不能“吸收热量后缓慢释放”，建筑墙体也不用冰来砌。"}], "explanations": {"大理石": "大理石：厚重的天然石材，能吸收并缓慢释放热量，符合句意。", "泡沫": "语义：泡沫很轻，与“厚重”矛盾，也不能蓄存热量。", "纸板": "语义：纸板很薄，无法像墙体那样吸收并释放热量。", "冰": "搭配：冰会融化，不能“吸收热量后缓慢释放”，建筑墙体也不用冰来砌。"}, "sentence_index": 0, "correct_answer": "大理石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只大理石放在客厅里。", "explanation": "这里应该用〈块〉。大理石是块状石材，要用“块”计量，“只”多用于动物或成对物品中的单个。"}, {"text": "他去年去了大理石旅游。", "explanation": "这里应该用〈大理〉。大理是云南的地名，大理石是石材，不能用来指地方。"}, {"text": "这面墙是用大理石抹平的。", "explanation": "这里应该用〈石膏〉。“抹平”用于石膏、水泥这类可以涂抹的材料，大理石是整块石材，不能抹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大理石", "is_correct": true, "explanation": "大理石：石材，冬天踩上去很凉，符合句意。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：地毯是铺在地板上的东西，不能说“地毯的地板”。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：纸不能用来做地板。"}, {"text": "海绵", "is_correct": false, "explanation": "语义：海绵柔软，踩上去不会“很凉”，与句意矛盾。"}], "explanations": {"大理石": "大理石：石材，冬天踩上去很凉，符合句意。", "地毯": "搭配：地毯是铺在地板上的东西，不能说“地毯的地板”。", "纸": "搭配：纸不能用来做地板。", "海绵": "语义：海绵柔软，踩上去不会“很凉”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "大理石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用大理石刷了一面墙。", "explanation": "这里应该用〈油漆〉。“刷”用于油漆、涂料这类液体或膏状物，大理石是固体石材，不能用来刷墙。"}, {"text": "她用大理石编了一条围巾。", "explanation": "这里应该用〈毛线〉。“编”需要线状材料，大理石是硬块，不能用来编织。"}, {"text": "妈妈用大理石剪了一块布。", "explanation": "这里应该用〈剪刀〉。“剪”需要剪刀之类的工具，大理石不能用来剪布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家的桌子是用一只大理石做的。", "corrected_sentence": "他家的桌子是用一块大理石做的。", "error_description": "量词错误：“大理石”是块状石材，应用“块”计量，不能用“只”。应说“一块大理石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口放着一条大理石。", "corrected_sentence": "门口放着一块大理石。", "error_description": "量词错误：“大理石”是块状石材，应用“块”计量，不能用“条”。应说“一块大理石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
