INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一套系统化的、相互关联的概念和命题，用于解释或描述某一领域的现象或问题。", "primary_collocate": null, "pronunciation": "lǐ lùn tǐ xì", "ipa": "li˨˩ lwən˥˩ tʰi˨˩ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "这些实践虽未形成理论体系，却为后世埋下创新的种子。", "target_word": "理论体系", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这位教授建立了完整的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了十年，才形成自己的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了一个新的经济理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学一门科学，要先了解它的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中医有自己独特的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个理论体系很复杂，一年学不完。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们正在完善这个理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项发现改变了原有的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把几十年的研究写成了一套理论体系。", "target_word": "理论体系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "系统化且相互关联的概念与命题，用来解释某一领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理论体系", "is_correct": true, "explanation": "理论体系：一套系统化的概念和命题，与「形成」搭配，符合「后世」的语境。"}, {"text": "房屋", "is_correct": false, "explanation": "搭配：「形成」用于抽象事物，不说「形成房屋」，房屋要说「建造」。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，与「形成」和「埋下创新的种子」的抽象语境不合。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：「形成」不用于具体器物，汽车要说「制造」。"}], "explanations": {"理论体系": "理论体系：一套系统化的概念和命题，与「形成」搭配，符合「后世」的语境。", "房屋": "搭配：「形成」用于抽象事物，不说「形成房屋」，房屋要说「建造」。", "早餐": "语义：早餐是一顿饭，与「形成」和「埋下创新的种子」的抽象语境不合。", "汽车": "搭配：「形成」不用于具体器物，汽车要说「制造」。"}, "sentence_index": 0, "correct_answer": "理论体系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套地铁理论体系很方便。", "explanation": "「理论体系」指学科里的概念和命题，不能指地铁这样的实体；这里是把它当成了实体的「系统」来用。"}, {"text": "他提出了一棵理论体系。", "explanation": "「棵」用于植物，理论体系是抽象的，应用「套」。"}, {"text": "他是一个理论体系。", "explanation": "理论体系是概念和命题的集合，不指人，应说「理论家」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理论体系", "is_correct": true, "explanation": "理论体系：可以很复杂、需要花时间学习，符合「一年学不完」的语境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能说「很复杂」，也谈不上「学不完」。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：「复杂」多形容体系、结构，房间不说「很复杂，一年学不完」。"}, {"text": "外套", "is_correct": false, "explanation": "语义：外套是衣物，不需要「学」，与「一年学不完」不合。"}], "explanations": {"理论体系": "理论体系：可以很复杂、需要花时间学习，符合「一年学不完」的语境。", "面包": "语义：面包是食物，不能说「很复杂」，也谈不上「学不完」。", "房间": "搭配：「复杂」多形容体系、结构，房间不说「很复杂，一年学不完」。", "外套": "语义：外套是衣物，不需要「学」，与「一年学不完」不合。"}, "sentence_index": 6, "correct_answer": "理论体系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份理论体系很详细，每天都有安排。", "explanation": "这里应该用〈计划〉。理论体系讲概念和命题，不用来安排每天的事。"}, {"text": "他端来一碗理论体系。", "explanation": "理论体系是抽象的概念和命题，不能用「碗」计量，也不能「端」；这里应该用〈汤〉之类的食物。"}, {"text": "这部理论体系能查到很多词。", "explanation": "这里应该用〈词典〉。理论体系讲概念和命题，不用来查词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学者提出了一把理论体系来解释这个现象。", "corrected_sentence": "学者提出了一套理论体系来解释这个现象。", "error_description": "量词错误：「理论体系」应配「套」，「把」用于有柄的器具，不能用于理论体系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几十年来，他一直在喝一套理论体系。", "corrected_sentence": "几十年来，他一直在建立一套理论体系。", "error_description": "动词搭配错误：「理论体系」应搭配「建立」，不能说「喝」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
