INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13687, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "为将来的发展或结果打下基础或创造条件", "primary_collocate": null, "pronunciation": "mái", "ipa": "mai˧˥", "syllable_count": 1, "sentences": [{"text": "这些实践虽未形成理论体系，却为后世埋下创新的种子。", "target_word": "埋", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师的一句话，在他心里埋下了希望。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小错误给以后的事故埋下了隐患。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在故事的开头就埋下了一个伏笔。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的那次旅行，为我的梦想埋下了种子。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就为今天的矛盾埋下了祸根。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不注意安全，会给以后埋下很大的隐患。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的第一幕就埋下了不少伏笔。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次误会为他们后来的分开埋下了祸根。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会在学生心里埋下爱读书的种子。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "埋了", "label": "体标（了）"}, {"form": "埋着", "label": "体标（着）"}, {"form": "埋过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "埋-比喻为将来埋下伏笔、隐患、种子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13687, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：为将来的发展或结果打下基础或创造条件。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mái（第二声）声调不同，意思是买。"}, {"text": "麦", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是麦子。"}, {"text": "煤", "is_correct": false, "explanation": "méi 与 mái 韵母不同（ei 与 ai），意思是煤炭。"}, {"text": "没", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是没有。"}, {"text": "迈", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是迈步。"}], "explanations": {"埋": "埋：为将来的发展或结果打下基础或创造条件。", "买": "mǎi（第三声）与 mái（第二声）声调不同，意思是买。", "麦": "mài（第四声）与 mái（第二声）声调不同，意思是麦子。", "煤": "méi 与 mái 韵母不同（ei 与 ai），意思是煤炭。", "没": "méi 与 mái 韵母不同，意思是没有。", "迈": "mài（第四声）与 mái（第二声）声调不同，意思是迈步。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：为后世打下基础，与「下」和「创新的种子」搭配，符合句意。"}, {"text": "挖", "is_correct": false, "explanation": "语义：挖是挖掘土地的动作，与比喻性的「创新的种子」不合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是饮食动作，与「创新的种子」不合。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：撕用于纸张、布料等，不能说「撕下创新的种子」。"}], "explanations": {"埋": "埋：为后世打下基础，与「下」和「创新的种子」搭配，符合句意。", "挖": "语义：挖是挖掘土地的动作，与比喻性的「创新的种子」不合。", "吃": "语义：吃是饮食动作，与「创新的种子」不合。", "撕": "搭配：撕用于纸张、布料等，不能说「撕下创新的种子」。"}, "sentence_index": 0, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天，农民在地里埋下了种子。", "explanation": "这是「埋进土里、种下种子」的字面意思，与本词「为将来打下基础」不同。"}, {"text": "他在花园里埋了一个宝盒。", "explanation": "这是「用东西盖住」的意思，与本词「为将来打下基础」不同。"}, {"text": "他把这件事埋在心里，二十年都没说出口。", "explanation": "这是「藏在心里、不让人知道」的引申义，与本词「为将来打下基础」无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13687, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：为将来的发展或结果打下基础或创造条件。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是卖。"}, {"text": "梅", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是梅花。"}, {"text": "媒", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是媒介。"}, {"text": "脉", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是血管、脉络。"}], "explanations": {"埋": "埋：为将来的发展或结果打下基础或创造条件。", "卖": "mài（第四声）与 mái（第二声）声调不同，意思是卖。", "梅": "méi 与 mái 韵母不同，意思是梅花。", "媒": "méi 与 mái 韵母不同，意思是媒介。", "脉": "mài（第四声）与 mái（第二声）声调不同，意思是血管、脉络。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：为将来打下隐患的基础，与「下很大的隐患」搭配，符合句意。"}, {"text": "摘", "is_correct": false, "explanation": "语义：摘是采摘果实的动作，不能说「摘下隐患」。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是割开的动作，与「隐患」不合。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：剪用于纸、布、头发等，「剪下隐患」不搭配。"}], "explanations": {"埋": "埋：为将来打下隐患的基础，与「下很大的隐患」搭配，符合句意。", "摘": "语义：摘是采摘果实的动作，不能说「摘下隐患」。", "切": "语义：切是割开的动作，与「隐患」不合。", "剪": "搭配：剪用于纸、布、头发等，「剪下隐患」不搭配。"}, "sentence_index": 6, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "园丁在温室里埋下了一批新品种。", "explanation": "这里应该用〈培育〉。埋下用于抽象的伏笔、隐患、种子，培育品种要说「培育」。"}, {"text": "老师把学生埋进了书堆里。", "explanation": "这是「用东西盖住」的意思，与「为将来打下基础」不同。"}, {"text": "好老师会在学生心里埋下一片云。", "explanation": "「埋下」的对象应是伏笔、种子等，云不能被「埋下」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在文章里埋了过一个伏笔。", "corrected_sentence": "他在文章里埋下过一个伏笔。", "error_description": "体标错误：「埋」后不能同时用「了」和「过」，应说「埋下过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次挫折为他日后的成功埋了下伏笔。", "corrected_sentence": "这次挫折为他日后的成功埋下了伏笔。", "error_description": "补语语序错误：「下」应紧跟「埋」，应说「埋下了伏笔」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
