INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13689, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工业革命是指18世纪至19世纪，以机器生产取代手工劳动、工厂制度兴起为标志的生产方式重大变革。", "primary_collocate": null, "pronunciation": "gōng yè gé mìng", "ipa": "kʊŋ˥ jɛ˥˩ kɤ˧˥ miŋ˥˩", "syllable_count": 4, "sentences": [{"text": "工业革命后，化石能源的暴发性使用掩盖了可再生能源的发展轨迹。", "target_word": "工业革命", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "工业革命让很多人从农村搬到了城市。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命以前，大部分东西是用手做的。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国是第一个发生工业革命的国家。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命带来了新的机器和新的工作。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲过工业革命的历史。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命使工厂里的产量大大提高。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在读一本关于工业革命的书。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命改变了人们的生活方式。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒸汽机是工业革命的重要标志。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工業革命", "label": "繁体"}], "register": "书面", "sense_fingerprint": "18至19世纪以机器生产取代手工劳动的历史变革", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业革命", "is_correct": true, "explanation": "正确：工业革命是化石能源大规模使用的起点，指18至19世纪的生产方式变革，所以它之后才有“化石能源的暴发性使用”。"}, {"text": "计算机", "is_correct": false, "explanation": "时间：计算机出现于20世纪，晚于化石能源大规模使用的开端，与“后”的时间关系不符。"}, {"text": "互联网", "is_correct": false, "explanation": "时间：互联网兴起于20世纪后期，晚于化石能源大规模使用的开端，与“后”的时间关系不符。"}, {"text": "电视机", "is_correct": false, "explanation": "时间：电视机普及于20世纪中叶，晚于化石能源大规模使用的开端，与“后”的时间关系不符。"}], "explanations": {"工业革命": "正确：工业革命是化石能源大规模使用的起点，指18至19世纪的生产方式变革，所以它之后才有“化石能源的暴发性使用”。", "计算机": "时间：计算机出现于20世纪，晚于化石能源大规模使用的开端，与“后”的时间关系不符。", "互联网": "时间：互联网兴起于20世纪后期，晚于化石能源大规模使用的开端，与“后”的时间关系不符。", "电视机": "时间：电视机普及于20世纪中叶，晚于化石能源大规模使用的开端，与“后”的时间关系不符。"}, "sentence_index": 0, "correct_answer": "工业革命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只工业革命带动了城市的发展。", "explanation": "这里量词用错。〈只〉用于动物或小件物品，工业革命是历史变革，应该用〈场〉，说“这场工业革命”。"}, {"text": "我昨天买了一个工业革命，放在桌子上。", "explanation": "这里应该用〈机器〉。工业革命是历史变革，不是可以买来摆放的东西。"}, {"text": "妈妈做的工业革命很好吃。", "explanation": "这里应该用〈菜〉。工业革命指生产方式的历史变革，不是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业革命", "is_correct": true, "explanation": "正确：工业革命是一次历史性的生产变革，能够使工厂里的产量大大提高。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能使工厂里的产量大大提高。"}, {"text": "台风", "is_correct": false, "explanation": "语义：台风是自然灾害，只会破坏生产，不会使产量大大提高。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：“字典”不能作“使”字句的施事，与“使工厂里的产量大大提高”无法搭配。"}], "explanations": {"工业革命": "正确：工业革命是一次历史性的生产变革，能够使工厂里的产量大大提高。", "春天": "语义：春天是季节，不能使工厂里的产量大大提高。", "台风": "语义：台风是自然灾害，只会破坏生产，不会使产量大大提高。", "字典": "搭配：“字典”不能作“使”字句的施事，与“使工厂里的产量大大提高”无法搭配。"}, "sentence_index": 6, "correct_answer": "工业革命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工业革命让老师很满意。", "explanation": "这里应该用〈表现〉。工业革命指历史性的大变革，不用来评价个人的行为，评价个人用“表现”。"}, {"text": "这个国家的科技取得了很大的工业革命。", "explanation": "这里应该用〈进步〉。“取得很大的”用于成绩或程度，工业革命是一次性的历史事件，不能说“取得很大的工业革命”。"}, {"text": "他们计划搞一场工业革命，推翻政府。", "explanation": "这里误用了推翻政权的意思（〈政变〉）。工业革命指生产方式的变革，不指推翻政府。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只工业革命让城市的人口增加了很多。", "corrected_sentence": "这场工业革命让城市的人口增加了很多。", "error_description": "量词错误：〈只〉用于动物，工业革命是一场大规模的历史变革，应说“这场工业革命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学习了工业革命影响。", "corrected_sentence": "我们学习了工业革命的影响。", "error_description": "定语标记错误：“工业革命”修饰“影响”时需要用“的”，应说“工业革命的影响”，不能省略“的”直接说“工业革命影响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
