INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指疾病或事件突然、猛烈地发生。", "primary_collocate": null, "pronunciation": "bào fā xìng", "ipa": "pau˥˩ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "工业革命后，化石能源的暴发性使用掩盖了可再生能源的发展轨迹。", "target_word": "暴发性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这种病的暴发性很强。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这次疫情具有暴发性。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴发性疾病需要马上治疗。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水的暴发性让村民来不及准备。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疾病的暴发性让医院很忙。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在研究这种病毒的暴发性。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为这种病的暴发性很强，病人一天内就增加了很多。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洪具有暴发性，所以我们要小心。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾的暴发性出乎大家的意料。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴發性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "疾病或事件突然猛烈发生的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴发性", "is_correct": true, "explanation": "正确：暴发性指突然、猛烈的特点，可以修饰化石能源的使用，表示其急剧增长的特征。"}, {"text": "可逆性", "is_correct": false, "explanation": "语义：可逆性指过程能否还原，与“使用”的规模或时间特征不符，不能描述化石能源使用的特点。"}, {"text": "腐蚀性", "is_correct": false, "explanation": "搭配：腐蚀性修饰的是物质的性质，不修饰使用行为，“腐蚀性使用”搭配不当。"}, {"text": "透明性", "is_correct": false, "explanation": "语义：透明性指是否可见，与“掩盖了可再生能源的发展轨迹”的含义不符。"}], "explanations": {"暴发性": "正确：暴发性指突然、猛烈的特点，可以修饰化石能源的使用，表示其急剧增长的特征。", "可逆性": "语义：可逆性指过程能否还原，与“使用”的规模或时间特征不符，不能描述化石能源使用的特点。", "腐蚀性": "搭配：腐蚀性修饰的是物质的性质，不修饰使用行为，“腐蚀性使用”搭配不当。", "透明性": "语义：透明性指是否可见，与“掩盖了可再生能源的发展轨迹”的含义不符。"}, "sentence_index": 0, "correct_answer": "暴发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大雨的暴发性持续了整整一个星期。", "explanation": "这里混淆了〈持久〉的意思。暴发性指突然猛烈地发生，不指长时间保持某种状态。"}, {"text": "这位老师的暴发性很温和。", "explanation": "用法错误：暴发性只描述疾病或事件突然猛烈的特点，不能用来形容人的性格，也与“温和”矛盾。"}, {"text": "我每天早上暴发性地锻炼身体。", "explanation": "这里混淆了〈规律〉的意思。暴发性指突然猛烈地发生，不能用来描述每天有规律的锻炼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴发性", "is_correct": true, "explanation": "正确：专家研究的是病毒突然、猛烈地爆发的特点，“暴发性”符合研究对象。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是病毒的研究对象，与病毒学的研究内容不相关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：病毒没有可以品尝的味道，“研究这种病毒的味道”语义不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是人类的社会活动，不是病毒的属性，“研究这种病毒的节日”语义不通。"}], "explanations": {"暴发性": "正确：专家研究的是病毒突然、猛烈地爆发的特点，“暴发性”符合研究对象。", "价格": "语义：价格不是病毒的研究对象，与病毒学的研究内容不相关。", "味道": "语义：病毒没有可以品尝的味道，“研究这种病毒的味道”语义不通。", "节日": "语义：节日是人类的社会活动，不是病毒的属性，“研究这种病毒的节日”语义不通。"}, "sentence_index": 6, "correct_answer": "暴发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的暴发性写得很慢。", "explanation": "这里混淆了〈速度〉的意思。暴发性指疾病或事件突然猛烈地发生，不能描述书的写作快慢。"}, {"text": "我们班的暴发性很强，同学们很喜欢。", "explanation": "用法错误：暴发性用于疾病或事件，不用于班级，这里应该说“班级气氛很好”之类的说法。"}, {"text": "这场比赛的暴发性很平静。", "explanation": "这里混淆了〈强度〉的意思。暴发性指突然猛烈地发生，不能用来形容比赛平稳的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种病毒暴发性让人措手不及。", "corrected_sentence": "这种病毒的暴发性让人措手不及。", "error_description": "漏用“的”：“这种病毒”修饰“暴发性”时需要用“的”，应说“这种病毒的暴发性”，不能省略“的”直接说“这种病毒暴发性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场地震暴发性让大家吃惊。", "corrected_sentence": "这场地震的暴发性让大家吃惊。", "error_description": "漏用“的”：“这场地震”修饰“暴发性”时需要用“的”，应说“这场地震的暴发性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "正确：“暴露”指显露出来，与“掩盖”（隐瞒错误）相反。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指移动物体，与“掩盖”的遮盖、隐瞒之义无关。"}, {"text": "锻炼", "is_correct": false, "explanation": "“锻炼”指身体或能力的训练，与“掩盖”的任何义项都无关。"}, {"text": "洗涤", "is_correct": false, "explanation": "“洗涤”指用水清洗，与“掩盖”的遮盖、隐瞒之义无关。"}], "correct_answer": "暴露", "explanations": {"暴露": "正确：“暴露”指显露出来，与“掩盖”（隐瞒错误）相反。", "搬运": "“搬运”指移动物体，与“掩盖”的遮盖、隐瞒之义无关。", "锻炼": "“锻炼”指身体或能力的训练，与“掩盖”的任何义项都无关。", "洗涤": "“洗涤”指用水清洗，与“掩盖”的遮盖、隐瞒之义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "揭露", "is_correct": true, "explanation": "正确：“揭露”指揭开并公开，与“掩盖”（隐瞒事实）相反。"}, {"text": "烧制", "is_correct": false, "explanation": "“烧制”指用火加热制作器物，与“掩盖”的任何义项都无关。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指把树木砍倒，与“掩盖”的遮盖、隐瞒之义无关。"}, {"text": "织布", "is_correct": false, "explanation": "“织布”指用线织成布料，与“掩盖”的任何义项都无关。"}], "correct_answer": "揭露", "explanations": {"揭露": "正确：“揭露”指揭开并公开，与“掩盖”（隐瞒事实）相反。", "烧制": "“烧制”指用火加热制作器物，与“掩盖”的任何义项都无关。", "砍伐": "“砍伐”指把树木砍倒，与“掩盖”的遮盖、隐瞒之义无关。", "织布": "“织布”指用线织成布料，与“掩盖”的任何义项都无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遮盖；隐瞒。", "primary_collocate": null, "pronunciation": "yǎn gài", "ipa": "jɛn˨˩ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "工业革命后，化石能源的暴发性使用掩盖了可再生能源的发展轨迹。", "target_word": "掩盖", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他想用笑容掩盖心里的难过。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪掩盖了山上的小路。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能掩盖自己的错误。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把问题掩盖起来。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓雾掩盖着整个城市。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂草掩盖了墓碑上的字。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用头发掩盖过脸上的伤。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好成绩不能掩盖他的缺点。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者发现公司一直在掩盖事实。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掩盖了", "label": "体标"}, {"form": "掩盖着", "label": "体标"}, {"form": "掩盖过", "label": "体标"}, {"form": "掩蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遮住或隐瞒真相、情绪、事实等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掩盖", "is_correct": true, "explanation": "正确：“掩盖”表示遮住或隐瞒，能与“发展轨迹”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调食物，不能用于可再生能源的发展轨迹。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能说“增加了发展轨迹”。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”要求有人作对象，“发展轨迹”不能被批评。"}], "explanations": {"掩盖": "正确：“掩盖”表示遮住或隐瞒，能与“发展轨迹”搭配，符合句意。", "煮": "语义：“煮”指烹调食物，不能用于可再生能源的发展轨迹。", "增加": "搭配：“增加”说数量，不能说“增加了发展轨迹”。", "批评": "配价：“批评”要求有人作对象，“发展轨迹”不能被批评。"}, "sentence_index": 0, "correct_answer": "掩盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场会议掩盖了整个下午。", "explanation": "这里应该用〈占据〉。掩盖表示盖住东西或隐瞒事实，不能指一段时间被会议占去；会议占去时间要说“占据”。"}, {"text": "他掩盖了妹妹，不让她跟朋友出去。", "explanation": "这里应该用〈拦住〉。掩盖的对象是东西或事实，不能用来指把人拦在家里。"}, {"text": "我把钥匙掩盖在抽屉里。", "explanation": "这里应该用〈藏〉。掩盖强调盖住使人看不见，把东西收进隐蔽处应说“藏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掩盖", "is_correct": true, "explanation": "正确：“掩盖”表示遮住，能说“杂草掩盖了字”，符合句意。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化，不能用来描述杂草与字迹的关系。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”需要有动作者把表面的东西擦去，杂草不能“擦”字。"}, {"text": "修饰", "is_correct": false, "explanation": "语义：“修饰”指润色或打扮，与杂草覆盖墓碑上字迹的意思不符。"}], "explanations": {"掩盖": "正确：“掩盖”表示遮住，能说“杂草掩盖了字”，符合句意。", "装饰": "语义：“装饰”指美化，不能用来描述杂草与字迹的关系。", "擦": "配价：“擦”需要有动作者把表面的东西擦去，杂草不能“擦”字。", "修饰": "语义：“修饰”指润色或打扮，与杂草覆盖墓碑上字迹的意思不符。"}, "sentence_index": 6, "correct_answer": "掩盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上掩盖一杯牛奶当早饭。", "explanation": "这里应该用〈喝〉。掩盖表示遮住或隐瞒，不能表示饮用。"}, {"text": "老板掩盖了三天的工作。", "explanation": "这里应该用〈完成〉。掩盖不能作用于一段工作时间，工作应说“完成”。"}, {"text": "这首歌掩盖了整整一个星期。", "explanation": "这里应该用〈流行〉。掩盖不能表示一段时间内的状态，描述歌曲在一段时间内受欢迎应说“流行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想把这件事掩盖出来。", "corrected_sentence": "他想把这件事掩盖起来。", "error_description": "“掩盖”后应接补语“起来”，表示盖住、藏住；“出来”表示从里向外显露，与句意相反。应说“掩盖起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把那件坏事掩盖。", "corrected_sentence": "他们把那件坏事掩盖了。", "error_description": "“把”字句中动词后要带补语或“了”等成分，“掩盖”后缺少“了”，句子不完整。应说“把那件坏事掩盖了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
