INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指公元1900年至1999年之间的时期。", "primary_collocate": null, "pronunciation": "èr shí shì jì", "ipa": "ɚ˥˩ ʂɨ˧˥ ʂɨ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "二十世纪的石油危机爆发后，能源安全议题迫使各国重新审视技术路径。", "target_word": "二十世纪", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "二十世纪是一个科学快速发展的时代。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥建于二十世纪，已经很旧了。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是在二十世纪出生的。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪的战争给许多国家带来了痛苦。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史老师说，二十世纪发生了很多大事。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家是二十世纪最有名的诗人之一。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家是在二十世纪搬到北京的。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机在二十世纪才走进普通人家。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多二十世纪的老照片。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二十世紀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公元1900至1999年这一百年的历史时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是时期名词，可修饰“石油危机”，表示危机发生的时代，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是时间，不能修饰“石油危机”。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”是一天中的时段，不能修饰“石油危机”，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能用来表示时代。"}], "explanations": {"二十世纪": "正确：“二十世纪”是时期名词，可修饰“石油危机”，表示危机发生的时代，符合句意。", "鸡蛋": "语义：“鸡蛋”不是时间，不能修饰“石油危机”。", "上午": "搭配：“上午”是一天中的时段，不能修饰“石油危机”，句意不通。", "椅子": "语义：“椅子”是家具，不能用来表示时代。"}, "sentence_index": 0, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在我们生活在二十世纪。", "explanation": "这里应该用〈二十一世纪〉。说“现在”时身处的是二十一世纪，二十世纪已经过去。"}, {"text": "我们班有三个二十世纪。", "explanation": "这里应该用〈学生〉。二十世纪是一个历史时期，不是人，不能说班里“有三个二十世纪”。"}, {"text": "我明天要去二十世纪买东西。", "explanation": "这里应该用〈超市〉。二十世纪是一段已经过去的时期，不是可以去买东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是一个时代，可以修饰“诗人”，符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是地点，不能表示时代。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能用来限定诗人的时代。"}, {"text": "体育课", "is_correct": false, "explanation": "搭配：“体育课”不能用来表示诗人活跃的时代，句意不通。"}], "explanations": {"二十世纪": "正确：“二十世纪”是一个时代，可以修饰“诗人”，符合句意。", "公园": "语义：“公园”是地点，不能表示时代。", "西瓜": "语义：“西瓜”是水果，不能用来限定诗人的时代。", "体育课": "搭配：“体育课”不能用来表示诗人活跃的时代，句意不通。"}, "sentence_index": 6, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去了二十世纪旅行。", "explanation": "这里应该用〈北京〉。二十世纪是时期，不是地点，不能说“去了二十世纪”。"}, {"text": "二十世纪是晚上八点。", "explanation": "这里应该用〈现在〉。二十世纪是一段时期，不能表示某个钟点。"}, {"text": "这件二十世纪很有意思。", "explanation": "这里应该用〈这个时代〉。二十世纪是时期，不用“件”计量，应说“这个时代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
