INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些人的父母在二十世纪时候很少出国。", "corrected_sentence": "这些人的父母在二十世纪的时候很少出国。", "error_description": "“二十世纪”修饰“时候”时中间应加“的”，说“二十世纪的时候”，不能说“二十世纪时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
