INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "硅是一种非金属化学元素，符号Si，是地壳中含量第二多的元素，广泛用于制造半导体、玻璃和电子芯片。", "primary_collocate": null, "pronunciation": "guī", "ipa": "kweɪ˥", "syllable_count": 1, "sentences": [{"text": "第一代晶体硅太阳能电池虽转化效率不足15%，却证明了光能直接转化为电能的可行性。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "硅是地壳中含量很高的一种元素。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子里有很多硅。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用硅来做电子芯片。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人以为硅是金属，其实它是非金属元素。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块芯片是用硅做的。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多玻璃里都含有硅。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家把硅切成很薄的片。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半导体材料常常用硅制成。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地壳里的硅比铁多。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "化学元素硅，半导体与芯片的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅，guī（第一声），非金属元素，是半导体和芯片的材料。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是贵重。"}, {"text": "灰", "is_correct": false, "explanation": "h 与 g 声母不同，huī 意思是灰色。"}, {"text": "亏", "is_correct": false, "explanation": "k 与 g 声母不同，kuī 意思是亏损。"}], "explanations": {"硅": "硅，guī（第一声），非金属元素，是半导体和芯片的材料。", "鬼": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼。", "贵": "guì（第四声）与 guī（第一声）声调不同，意思是贵重。", "灰": "h 与 g 声母不同，huī 意思是灰色。", "亏": "k 与 g 声母不同，kuī 意思是亏损。"}, "sentence_index": null, "correct_answer": "硅"}, "level_3": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅是半导体材料，晶体硅太阳能电池就是用它制成的。"}, {"text": "铜", "is_correct": false, "explanation": "语义：铜是金属导体，不能作为把光能转为电能的半导体材料。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“晶体”修饰的是矿物或半导体，不能说“晶体木头”。"}, {"text": "钠", "is_correct": false, "explanation": "语义：钠是活泼金属，不能形成用于光电转换的晶体半导体。"}], "explanations": {"硅": "硅是半导体材料，晶体硅太阳能电池就是用它制成的。", "铜": "语义：铜是金属导体，不能作为把光能转为电能的半导体材料。", "木头": "搭配：“晶体”修饰的是矿物或半导体，不能说“晶体木头”。", "钠": "语义：钠是活泼金属，不能形成用于光电转换的晶体半导体。"}, "sentence_index": 0, "correct_answer": "硅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感冒了，就吃了两片硅退烧。", "explanation": "这里应该用〈药〉。硅是非金属元素，不能当药吃；“退烧”要用药物。"}, {"text": "我渴了，就喝了一杯硅。", "explanation": "这里应该用〈水〉。硅是固体元素，不能喝；“喝”的对象要是饮品。"}, {"text": "这栋小屋是用硅盖的。", "explanation": "这里应该用〈砖〉。硅是单质，不作盖房子的建筑材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13703, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅，guī（第一声），非金属元素，是半导体和芯片的材料。"}, {"text": "轨", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。"}, {"text": "柜", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。"}, {"text": "挥", "is_correct": false, "explanation": "h 与 g 声母不同，huī 意思是挥动。"}, {"text": "跪", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是下跪。"}], "explanations": {"硅": "硅，guī（第一声），非金属元素，是半导体和芯片的材料。", "轨": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。", "柜": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。", "挥": "h 与 g 声母不同，huī 意思是挥动。", "跪": "guì（第四声）与 guī（第一声）声调不同，意思是下跪。"}, "sentence_index": null, "correct_answer": "硅"}, "level_3": {"options": [{"text": "硅", "is_correct": true, "explanation": "玻璃中含有的是硅的化合物，硅是其中的成分。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖是有机物，不会存在于玻璃中。"}, {"text": "油", "is_correct": false, "explanation": "搭配：“含有”指材料的成分，油不会混入玻璃。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食物，不是玻璃的成分。"}], "explanations": {"硅": "玻璃中含有的是硅的化合物，硅是其中的成分。", "糖": "语义：糖是有机物，不会存在于玻璃中。", "油": "搭配：“含有”指材料的成分，油不会混入玻璃。", "面粉": "语义：面粉是食物，不是玻璃的成分。"}, "sentence_index": 6, "correct_answer": "硅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用硅炒了一盘青菜。", "explanation": "这里应该用〈油〉。硅不能用于烹饪，“炒”要用油。"}, {"text": "他用硅擦桌子。", "explanation": "这里应该用〈抹布〉。硅不是擦拭用具，“擦”要用布类工具。"}, {"text": "他用硅写字。", "explanation": "这里应该用〈笔〉。硅不是书写工具，“写字”要用笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂买了三条硅。", "corrected_sentence": "工厂买了三块硅。", "error_description": "量词错误。硅是块状固体，量词应用“块”；“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
