INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电池是一种储存电能的装置，可以为手机、玩具等设备提供电力。", "primary_collocate": null, "pronunciation": "diàn chí", "ipa": "tjɛn˥˩ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这块旧电池用久了，就充不进电了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具需要两节电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电池只剩百分之十了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池可以储存电能。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给遥控器换了新电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池没电了，灯就不亮了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种电池可以反复充电。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车的电池很重。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前要给电池充满电。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把用完的电池扔进垃圾桶。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "充电电池", "label": "复合"}, {"form": "電池", "label": "繁体"}], "register": "中性", "sense_fingerprint": "储存电能并给设备供电的装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池，diàn chí，储存电能的装置。"}, {"text": "电磁", "is_correct": false, "explanation": "c 与 ch 声母不同，diàn cí 意思是电磁。"}, {"text": "电石", "is_correct": false, "explanation": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。"}, {"text": "垫尺", "is_correct": false, "explanation": "chǐ（第三声）与 chí（第二声）声调不同，垫尺意思是写字时垫在纸下的尺板。"}], "explanations": {"电池": "电池，diàn chí，储存电能的装置。", "电磁": "c 与 ch 声母不同，diàn cí 意思是电磁。", "电石": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。", "垫尺": "chǐ（第三声）与 chí（第二声）声调不同，垫尺意思是写字时垫在纸下的尺板。"}, "sentence_index": null, "correct_answer": "电池"}, "level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池：储存电能的装置，“充不进电”的对象正是它。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能储存电能，与“充不进电”不合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能储存电能，与“充不进电”不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能充电，与“充不进电”不合。"}], "explanations": {"电池": "电池：储存电能的装置，“充不进电”的对象正是它。", "手套": "语义：手套不能储存电能，与“充不进电”不合。", "书包": "语义：书包不能储存电能，与“充不进电”不合。", "石头": "语义：石头不能充电，与“充不进电”不合。"}, "sentence_index": 0, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用电池梳头。", "explanation": "这里应该用〈梳子〉。电池是储存电能的装置，不能用来梳头；“梳头”要用梳子。"}, {"text": "我每天早上喝一杯电池。", "explanation": "这里应该用〈牛奶〉。电池不是饮品，不能喝。"}, {"text": "这栋小屋是用电池盖的。", "explanation": "这里应该用〈砖〉。电池不是建筑材料，不能用来盖房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池可以反复充电，“充电”的对象是电池。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不能充电，与“反复充电”矛盾。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不储存电能，不能反复充电。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不能充电。"}], "explanations": {"电池": "电池可以反复充电，“充电”的对象是电池。", "蔬菜": "语义：蔬菜不能充电，与“反复充电”矛盾。", "木头": "语义：木头不储存电能，不能反复充电。", "牛奶": "语义：牛奶是饮品，不能充电。"}, "sentence_index": 6, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，吃了一个电池。", "explanation": "这里应该用〈面包〉。电池不是食物，不能吃。"}, {"text": "妈妈在厨房用电池炒菜。", "explanation": "这里应该用〈油〉。电池不能用于烹饪，“炒”要用油。"}, {"text": "他用电池写字。", "explanation": "这里应该用〈笔〉。电池不是书写工具，“写字”要用笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前用过这本电池。", "corrected_sentence": "我们以前用过这种电池。", "error_description": "量词错误。“本”用于书册，不能修饰电池；这里应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把电池充满了电池。", "corrected_sentence": "我把电池充满了电。", "error_description": "宾语错误。“充满”的宾语应是“电”，不能说“充满了电池”；应说“充满了电”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
