INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13705, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用证据或推理来表明某个事实或结论是正确的。", "primary_collocate": null, "pronunciation": "zhèng míng", "ipa": "ʈʂɤŋ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他用实验证明了这个想法是对的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实证明，我们的办法很有用。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要拿出证据来证明自己没错。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛证明他已经长大了。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上证明了这个公式。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用很多数据证明了结果。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想证明自己可以做好这件事。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片能证明我昨天去过那里。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能证明他说的是真的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用检查结果证明她很健康。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "证明了", "label": "体标"}, {"form": "证明过", "label": "体标"}, {"form": "證明", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用证据或推理表明事实或结论正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13705, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明（zhèng míng）指用证据或推理表明事情正确，即本词。"}, {"text": "争鸣", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，争鸣意思是各抒己见地辩论。"}, {"text": "挣命", "is_correct": false, "explanation": "第二音节 mìng（第四声）与 míng（第二声）声调不同，挣命意思是拼命挣扎求生。"}, {"text": "争名", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，争名意思是争夺名声。"}], "explanations": {"证明": "证明（zhèng míng）指用证据或推理表明事情正确，即本词。", "争鸣": "zhēng（第一声）与 zhèng（第四声）声调不同，争鸣意思是各抒己见地辩论。", "挣命": "第二音节 mìng（第四声）与 míng（第二声）声调不同，挣命意思是拼命挣扎求生。", "争名": "zhēng（第一声）与 zhèng（第四声）声调不同，争名意思是争夺名声。"}, "sentence_index": null, "correct_answer": "证明"}, "level_3": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明：用实验表明这个想法正确，与“是对的”相合。"}, {"text": "相信", "is_correct": false, "explanation": "语义：相信是心理上的认可，不是实验能得出的结果，与“用实验”矛盾。"}, {"text": "修改", "is_correct": false, "explanation": "语义：修改用于需要改动的对象，与“这个想法是对的”矛盾。"}, {"text": "偷", "is_correct": false, "explanation": "搭配：“偷”的对象是财物，不能接“这个想法是对的”这样的命题。"}], "explanations": {"证明": "证明：用实验表明这个想法正确，与“是对的”相合。", "相信": "语义：相信是心理上的认可，不是实验能得出的结果，与“用实验”矛盾。", "修改": "语义：修改用于需要改动的对象，与“这个想法是对的”矛盾。", "偷": "搭配：“偷”的对象是财物，不能接“这个想法是对的”这样的命题。"}, "sentence_index": 0, "correct_answer": "证明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人证明了一把新椅子。", "explanation": "这里应该用〈做〉。证明的宾语只能是事实或结论，椅子是物件，应说做椅子。"}, {"text": "工程师证明了一座新桥。", "explanation": "这里应该用〈设计〉。设计指规划并画出方案，证明的宾语是事实或结论，不能是桥这样的具体事物。"}, {"text": "他证明了一种新的洗衣机。", "explanation": "这里应该用〈发明〉。发明指创造出新事物，证明的宾语只能是事实或结论，不能是洗衣机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明：想用行动表明自己的能力，与“做好这件事”相合。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”要求新事物作宾语，不能接“自己可以做好这件事”这样的小句。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是称赞别人，不能用来指“自己可以做好这件事”。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是对别人的羡慕或不满，与“想……自己可以做好”的意愿不合。"}], "explanations": {"证明": "证明：想用行动表明自己的能力，与“做好这件事”相合。", "发明": "配价：“发明”要求新事物作宾语，不能接“自己可以做好这件事”这样的小句。", "表扬": "语义：表扬是称赞别人，不能用来指“自己可以做好这件事”。", "嫉妒": "语义：嫉妒是对别人的羡慕或不满，与“想……自己可以做好”的意愿不合。"}, "sentence_index": 6, "correct_answer": "证明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生证明了一张病床。", "explanation": "这里应该用〈推〉。证明的宾语只能是事实或结论，病床是物件，应说推病床。"}, {"text": "护士证明了她的枕头。", "explanation": "这里应该用〈整理〉。证明的宾语须是事实或结论，枕头是物件，应说整理枕头。"}, {"text": "医生证明了她的药片。", "explanation": "这里应该用〈吃〉。药片是用来服用的物件，证明的宾语只能是事实或结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用数学方法证明了这张桌子。", "corrected_sentence": "他用数学方法证明了这个定理。", "error_description": "宾语错误。“证明”的宾语应是命题或结论，“桌子”不能被证明；应说“证明了这个定理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告证明得我们的判断是正确的。", "corrected_sentence": "这份报告证明了我们的判断是正确的。", "error_description": "错误：“证明得”；正确：“证明了”。“得”需要接补语成分，这里表示完成，应用完成标记“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
