INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光能是光辐射的能量形式，可转化为电能、热能等其他能量，如太阳能电池将光能转为电能。", "primary_collocate": null, "pronunciation": "guāng néng", "ipa": "kwɑŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "第一代晶体硅太阳能电池虽转化效率不足15%，却证明了光能直接转化为电能的可行性。", "target_word": "光能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "太阳能电池把光能转化成电能。", "target_word": "光能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物吸收光能，制造自己需要的养分。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光合作用需要光能才能进行。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块电池板能收集光能。", "target_word": "光能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光能可以转化为热能和电能。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阴天的时候，电池板接收的光能比较少。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家想提高光能的利用率。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "萤火虫发光时，化学能变成了光能。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳每天向地球送来大量光能。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "光辐射的能量形式，可转化为电能、热能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光能", "is_correct": true, "explanation": "光能：光辐射的能量，正是太阳能电池直接转化的对象，与语境相合。"}, {"text": "风能", "is_correct": false, "explanation": "语义：句中讲的是太阳能电池，风能不是光辐射，与“太阳能电池”的语境不合。"}, {"text": "电能", "is_correct": false, "explanation": "语义：“电能直接转化为电能”没有意义，与“转化为电能”的语境矛盾。"}, {"text": "电流", "is_correct": false, "explanation": "语义：电流本身已是电，不能再“转化为电能”。"}], "explanations": {"光能": "光能：光辐射的能量，正是太阳能电池直接转化的对象，与语境相合。", "风能": "语义：句中讲的是太阳能电池，风能不是光辐射，与“太阳能电池”的语境不合。", "电能": "语义：“电能直接转化为电能”没有意义，与“转化为电能”的语境矛盾。", "电流": "语义：电流本身已是电，不能再“转化为电能”。"}, "sentence_index": 0, "correct_answer": "光能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里没有光能，看不清东西。", "explanation": "这里应该用〈光线〉。看清东西需要的是亮光，光能指能量形式，不指照明的光线。"}, {"text": "这台冰箱要消耗大量光能。", "explanation": "这里应该用〈电能〉。冰箱靠电工作，消耗的是电能，光能不是冰箱的能量来源。"}, {"text": "汽油中的光能让汽车行驶。", "explanation": "这里应该用〈化学能〉。汽油储存的是化学能，光能指光辐射的能量，不是汽油的能量形式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光能", "is_correct": true, "explanation": "光能：电池板接收的是光辐射形式的能量，与“阴天”的语境相合。"}, {"text": "水分", "is_correct": false, "explanation": "语义：电池板接收的不是水分，水分与发电无关，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“接收”不能用来搭配“空气”指发电所需的能量。"}, {"text": "声音", "is_correct": false, "explanation": "语义：电池板是光电装置，接收的是光而不是声音，句意不合。"}], "explanations": {"光能": "光能：电池板接收的是光辐射形式的能量，与“阴天”的语境相合。", "水分": "语义：电池板接收的不是水分，水分与发电无关，句意不通。", "空气": "搭配：“接收”不能用来搭配“空气”指发电所需的能量。", "声音": "语义：电池板是光电装置，接收的是光而不是声音，句意不合。"}, "sentence_index": 6, "correct_answer": "光能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "发电厂把河水的光能变成电能。", "explanation": "这里应该用〈水能〉。水力发电利用的是水能，光能不是河水的能量形式。"}, {"text": "风车把光能变成电能。", "explanation": "这里应该用〈风能〉。风车靠风力发电，光能不能用来驱动风车。"}, {"text": "核电站利用光能发电。", "explanation": "这里应该用〈核能〉。核电站靠核反应获得能量，不是靠光辐射。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块电池板能收集一个光能。", "corrected_sentence": "这块电池板能收集一定量的光能。", "error_description": "错误：“一个光能”；正确：“一定量的光能”。光能是不可数的抽象名词，不能用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座工厂的屋顶能吸收很多个光能。", "corrected_sentence": "这座工厂的屋顶能吸收很多光能。", "error_description": "错误：“很多个光能”；正确：“很多光能”。光能是不可数名词，不能用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
