INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13709, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结是用绳子等打成的扣。", "primary_collocate": null, "pronunciation": "jié", "ipa": "tɕjɛ˧˥", "syllable_count": 1, "sentences": [{"text": "他在绳子的一头打了个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋带上的结松了，你快系紧一点。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用红绳在礼盒上系了一个漂亮的结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结太紧了，我怎么也解不开。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫用力拉紧绳子，结却越收越紧。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷的绳子上打了个结，风一吹就松了。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民在网绳上打了很多结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我怎么在围巾上打一个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子把木箱捆好，又打了一个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人手很巧，能打出各种各样的结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "绳子等打成的扣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结", "is_correct": true, "explanation": "jié（第二声），指用绳子等打成的扣，即正确答案。"}, {"text": "解", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是解开，不是绳扣。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是借用。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是接住。"}, {"text": "鞋", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}], "explanations": {"结": "jié（第二声），指用绳子等打成的扣，即正确答案。", "解": "jiě（第三声）与 jié（第二声）声调不同，意思是解开，不是绳扣。", "借": "jiè（第四声）与 jié（第二声）声调不同，意思是借用。", "接": "jiē（第一声）与 jié（第二声）声调不同，意思是接住。", "鞋": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}, "sentence_index": null, "correct_answer": "结"}, "level_3": {"options": [{"text": "结", "is_correct": true, "explanation": "正确：“打了个结”指在绳子上打出绳扣，句意通顺。"}, {"text": "哈欠", "is_correct": false, "explanation": "语义：“哈欠”是人张口发出的动作，不能打在绳子的一头。"}, {"text": "喷嚏", "is_correct": false, "explanation": "语义：“喷嚏”是人的生理反应，与在绳子上打扣的动作无关。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“打电话”的对象是人或电话机，不能说在绳子的一头“打电话”。"}], "explanations": {"结": "正确：“打了个结”指在绳子上打出绳扣，句意通顺。", "哈欠": "语义：“哈欠”是人张口发出的动作，不能打在绳子的一头。", "喷嚏": "语义：“喷嚏”是人的生理反应，与在绳子上打扣的动作无关。", "电话": "搭配：“打电话”的对象是人或电话机，不能说在绳子的一头“打电话”。"}, "sentence_index": 0, "correct_answer": "结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汤凉了以后，表面结了一层油。", "explanation": "这里的“结”是动词，指液体冷却后凝成油皮，是另一个意思，不指绳子打成的扣。"}, {"text": "水管里结了一层水垢，得找人清理。", "explanation": "这里的“结”是动词，指物质凝结附着，是另一个意思，不指绳子打成的扣。"}, {"text": "夜里气温降到零下，路面结冰了。", "explanation": "这里的“结”是动词，指水遇冷凝成冰，是另一个意思，不指绳子打成的扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13709, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "结", "is_correct": true, "explanation": "jié（第二声），指用绳子等打成的扣，即正确答案。"}, {"text": "姐", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是姐姐。"}, {"text": "界", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是界限。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是街道。"}, {"text": "斜", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是斜的。"}], "explanations": {"结": "jié（第二声），指用绳子等打成的扣，即正确答案。", "姐": "jiě（第三声）与 jié（第二声）声调不同，意思是姐姐。", "界": "jiè（第四声）与 jié（第二声）声调不同，意思是界限。", "街": "jiē（第一声）与 jié（第二声）声调不同，意思是街道。", "斜": "xié 与 jié 声母不同（x 与 j），意思是斜的。"}, "sentence_index": null, "correct_answer": "结"}, "level_3": {"options": [{"text": "结", "is_correct": true, "explanation": "正确：“打了很多结”指在网绳上打出许多绳扣，句意通顺。"}, {"text": "盹", "is_correct": false, "explanation": "语义：“打盹”是人打瞌睡，不是在网绳上做的动作。"}, {"text": "嗝", "is_correct": false, "explanation": "语义：“打嗝”是人的生理反应，不能在网绳上打很多嗝。"}, {"text": "招呼", "is_correct": false, "explanation": "搭配：“打招呼”的对象是人，不说在网绳上“打很多招呼”。"}], "explanations": {"结": "正确：“打了很多结”指在网绳上打出许多绳扣，句意通顺。", "盹": "语义：“打盹”是人打瞌睡，不是在网绳上做的动作。", "嗝": "语义：“打嗝”是人的生理反应，不能在网绳上打很多嗝。", "招呼": "搭配：“打招呼”的对象是人，不说在网绳上“打很多招呼”。"}, "sentence_index": 6, "correct_answer": "结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们去年秋天结了婚。", "explanation": "这里的“结”是动词“结婚”，指建立婚姻关系，是另一个意思，不指绳子打成的扣。"}, {"text": "他和邻居结了仇，两家多年不说话。", "explanation": "这里的“结”是动词“结仇”，指结下仇怨，是另一个意思，不指绳子打成的扣。"}, {"text": "这棵树今年结了很多苹果。", "explanation": "这里的“结”是动词，指植物长出果实，是另一个意思，不指绳子打成的扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在围巾的末端系了一条结。", "corrected_sentence": "她在围巾的末端系了一个结。", "error_description": "量词错误：“结”应搭配量词“个”，“条”用于细长的东西（如绳子、裤子），不能修饰“结”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔夫在网绳上打了一个结大。", "corrected_sentence": "渔夫在网绳上打了一个大结。", "error_description": "语序错误：形容词“大”修饰“结”时应放在名词前，说“一个大结”，不能说“一个结大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
