INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "复色光通过色散系统（如棱镜、光栅）进行分光后，按波长大小依次排列的图案。", "primary_collocate": null, "pronunciation": "guāng pǔ", "ipa": "kwɑŋ˥ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "光谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "三棱镜能把白光分成不同颜色的光谱。", "target_word": "光谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用光谱判断星星的成分。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彩虹是一种自然形成的光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台仪器可以测出物质的光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每种元素都有自己的特征光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红光在光谱的一端，紫光在另一端。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上展示了太阳的光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "通过光谱，人们发现了氦元素。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光谱中的每条线都对应一个波长。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "光谱仪", "label": "复合"}], "register": "科技", "sense_fingerprint": "复色光分光后按波长依次排列的图案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：光伏电池响应的是光，声音与光谱响应极限无关。"}, {"text": "光谱", "is_correct": true, "explanation": "正确：光谱是光按波长排列的分布，电池对不同波长的光有不同响应，与“突破光谱响应极限”相符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“响应极限”搭配光谱、频率等物理量，不搭配心情。"}, {"text": "摩擦力", "is_correct": false, "explanation": "语义：光伏电池响应的是光的波长分布，摩擦力与之无关。"}], "explanations": {"声音": "语义：光伏电池响应的是光，声音与光谱响应极限无关。", "光谱": "正确：光谱是光按波长排列的分布，电池对不同波长的光有不同响应，与“突破光谱响应极限”相符。", "心情": "搭配：“响应极限”搭配光谱、频率等物理量，不搭配心情。", "摩擦力": "语义：光伏电池响应的是光的波长分布，摩擦力与之无关。"}, "sentence_index": 0, "correct_answer": "光谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的光谱很鲜艳。", "explanation": "这里应该用〈颜色〉。光谱指光分出的彩色带，描述物体的颜色要用“颜色”。"}, {"text": "老师用光谱统计了全班的成绩。", "explanation": "这里应该用〈图表〉。光谱是光分出的彩色带，统计数据要用“图表”，光谱不能用来统计。"}, {"text": "这首歌的光谱很响亮。", "explanation": "这里应该用〈音量〉。光谱是光分出的彩色带，描述声音的大小要用“音量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：红光与紫光分布在光谱两端，不在地图的两端。"}, {"text": "亲情", "is_correct": false, "explanation": "搭配：“一端”指空间或序列，不搭配“亲情”。"}, {"text": "光谱", "is_correct": true, "explanation": "正确：红光与紫光分处光谱的两端，与句意相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：光不会分布在考试的一端。"}], "explanations": {"地图": "语义：红光与紫光分布在光谱两端，不在地图的两端。", "亲情": "搭配：“一端”指空间或序列，不搭配“亲情”。", "光谱": "正确：红光与紫光分处光谱的两端，与句意相符。", "考试": "语义：光不会分布在考试的一端。"}, "sentence_index": 6, "correct_answer": "光谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用光谱拍了一张照片。", "explanation": "这里应该用〈相机〉。光谱是光按波长排列的图案，不是拍照的工具。"}, {"text": "这束光谱照亮了整个房间。", "explanation": "这里应该用〈光线〉。光谱是按波长排列的色带图案，不能发光，照亮房间的是光线。"}, {"text": "这幅画用了许多光谱。", "explanation": "这里应该用〈颜料〉。光谱是光的分布图案，不是可以涂抹的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在黑板上画出了一根光谱。", "corrected_sentence": "老师在黑板上画出了一道光谱。", "error_description": "量词错误：光谱是光形成的彩色带，应用“道”计量；“根”用于细长的实物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三棱镜能把白光分解彩色光谱。", "corrected_sentence": "三棱镜能把白光分解成彩色光谱。", "error_description": "错误：“分解彩色光谱”；正确：“分解成彩色光谱”。“分解”后需接“成”引出结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
