INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13715, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特质指某人或某事物独有的、区别于其他的特征或性质。", "primary_collocate": null, "pronunciation": "tè zhì", "ipa": "tʰɤ˥˩ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "特质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个人都有自己的特质。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "善良是她最重要的特质。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的特质是安静和干净。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的领导需要有哪些特质？", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他身上有一种艺术家的特质。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种材料的特质是轻而且软。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师发现了孩子独特的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要看到每个孩子的特质。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有勇敢和诚实两种特质。", "target_word": "特质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "特質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物独有的、区别于其他的特征", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b37b86d-3dce-4b15-a8aa-9eaa55042092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特质", "is_correct": true, "explanation": "正确。“柔性特质”指材料独有的柔软性质，与句中的描述相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“柔性”形容的是材料的性质，不能用来修饰价格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“柔性”描述的是材料的性质，颜色不能与之并列来说明材料。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资与材料的“柔性”无关，句子讲的是材料的性质。"}], "explanations": {"特质": "正确。“柔性特质”指材料独有的柔软性质，与句中的描述相符。", "价格": "搭配：“柔性”形容的是材料的性质，不能用来修饰价格。", "颜色": "语义：“柔性”描述的是材料的性质，颜色不能与之并列来说明材料。", "工资": "语义：工资与材料的“柔性”无关，句子讲的是材料的性质。"}, "sentence_index": 0, "correct_answer": "特质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上有一只特质，很让人羡慕。", "explanation": "这里应该用〈种〉。特质是抽象的，量词要用“种”或“个”，不能用“只”。"}, {"text": "他在这家公司积累了很多特质。", "explanation": "“积累”多用于经验、知识，特质是人固有的特征，不能积累；这里应该用〈经验〉。"}, {"text": "他最近的特质很好。", "explanation": "这里应该用〈状态〉。状态会随时间变化，特质是长期稳定的，不说“最近的特质”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特质", "is_correct": true, "explanation": "正确。“这种材料的特质”指材料的性质，“轻而且软”正是对它的描述。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“轻而且软”说的是材料的性质，温度不能这样形容。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用“轻而且软”来描述。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄只说多少岁，不能用“轻而且软”形容。"}], "explanations": {"特质": "正确。“这种材料的特质”指材料的性质，“轻而且软”正是对它的描述。", "温度": "语义：“轻而且软”说的是材料的性质，温度不能这样形容。", "味道": "语义：味道不能用“轻而且软”来描述。", "年龄": "搭配：年龄只说多少岁，不能用“轻而且软”形容。"}, "sentence_index": 6, "correct_answer": "特质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次犯了一个特质。", "explanation": "这里应该用〈错误〉。“犯”搭配“错误”，特质不能被“犯”。"}, {"text": "这件商品的特质降了三成。", "explanation": "这里应该用〈价格〉。价格可以降低，特质是固有的，不能用“降”来衡量。"}, {"text": "他的特质在考试中提高了。", "explanation": "这里应该用〈成绩〉。成绩会在考试中提高，特质是人或事物固有的，不会因一次考试而变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只独特的特质。", "corrected_sentence": "他有一种独特的特质。", "error_description": "量词用错：特质是抽象名词，应说“一种特质”；“只”多用于动物或某些器物，不能用来数特质。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要尊重每位同学特质。", "corrected_sentence": "我们要尊重每位同学的特质。", "error_description": "漏掉“的”：“同学”修饰“特质”时需要“的”连接，去掉后不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
