INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指从根本上推翻或改变原有的局面、观念、理论等。", "primary_collocate": null, "pronunciation": "diān fù", "ipa": "tjɛn˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "颠覆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影颠覆了我的想象。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术正在颠覆这个行业。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究颠覆了旧的理论。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发现颠覆了人们的看法。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想颠覆传统的做法。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机颠覆了我们的生活方式。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书颠覆了我对历史的认识。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想颠覆这个国家的政权。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人常常想颠覆旧观念。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颠覆了", "label": "体标"}, {"form": "颠覆过", "label": "体标"}, {"form": "颠覆性", "label": "复合"}, {"form": "顛覆", "label": "繁体"}], "register": "书面", "sense_fingerprint": "颠覆：从根本上推翻、改变原有的观念、理论或局面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b37b86d-3dce-4b15-a8aa-9eaa55042092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颠覆", "is_correct": true, "explanation": "正确。“颠覆”指从根本上推翻传统的制造逻辑，与句中的进化语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有贬低之意，与技术进步的叙述不协调。"}, {"text": "尊重", "is_correct": false, "explanation": "配价：“尊重”的施事应是人，材料不能尊重制造逻辑。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”是赞美，与“颠覆”所指的破旧立新之意不符。"}], "explanations": {"颠覆": "正确。“颠覆”指从根本上推翻传统的制造逻辑，与句中的进化语境相符。", "嘲笑": "语义：“嘲笑”带有贬低之意，与技术进步的叙述不协调。", "尊重": "配价：“尊重”的施事应是人，材料不能尊重制造逻辑。", "歌颂": "语义：“歌颂”是赞美，与“颠覆”所指的破旧立新之意不符。"}, "sentence_index": 0, "correct_answer": "颠覆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他颠覆了世界纪录。", "explanation": "这里应该用〈打破〉。纪录要用“打破”，颠覆多用于理论、制度等抽象的东西。"}, {"text": "他颠覆了会场里的沉默。", "explanation": "这里应该用〈打破〉。沉默要用“打破”，颠覆指推翻原有的观念或局面。"}, {"text": "他颠覆了新衣服，很漂亮。", "explanation": "这里应该用〈穿〉。衣服要说“穿”，颠覆只用于推翻观念、理论或局面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颠覆", "is_correct": true, "explanation": "正确。手机从根本上改变了人们的生活方式，“颠覆”恰当。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是有形的物品，生活方式不能修理。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”要求有意识的主语，手机不能喜欢生活方式。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：收藏的是物品，不能收藏生活方式。"}], "explanations": {"颠覆": "正确。手机从根本上改变了人们的生活方式，“颠覆”恰当。", "修理": "语义：修理的对象是有形的物品，生活方式不能修理。", "喜欢": "配价：“喜欢”要求有意识的主语，手机不能喜欢生活方式。", "收藏": "语义：收藏的是物品，不能收藏生活方式。"}, "sentence_index": 6, "correct_answer": "颠覆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天颠覆房间。", "explanation": "这里应该用〈打扫〉。打扫的对象是房间，颠覆用于推翻观念、理论或局面。"}, {"text": "她颠覆了一张照片。", "explanation": "这里应该用〈拍〉。拍的是照片，颠覆不能用于照片。"}, {"text": "他颠覆了一本书。", "explanation": "这里应该用〈写〉。写的是书，颠覆不能用来说书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个决定被颠覆了大家的计划。", "corrected_sentence": "这个决定颠覆了大家的计划。", "error_description": "多用了“被”：“颠覆”是及物动词，“这个决定”是施事，应去掉“被”，说“这个决定颠覆了大家的计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项发明很颠覆了传统的生产方式。", "corrected_sentence": "这项发明彻底颠覆了传统的生产方式。", "error_description": "错误：“很”是程度副词，不能修饰动词“颠覆”。应把“很”换成“彻底”，说“彻底颠覆了”，表示从根本上改变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
