INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "双面指具有两个不同的表面，或用于形容事物有两方面的特性。", "primary_collocate": null, "pronunciation": "shuāng miàn", "ipa": "ʂwɑŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "双面", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这张卡片是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用双面打印，可以省纸。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套双面都能穿。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板双面都刷了漆。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè kuài mù bǎn shuāng miàn dōu shuā le qī.", "sentence_source": "generated"}, {"text": "网络有好的一面，也有坏的一面，是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面旗子双面都有图案。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策的影响是双面的，要全面看待。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè xiàng zhèng cè de yǐng xiǎng shì shuāng miàn de, yào quán miàn kàn dài.", "sentence_source": "generated"}, {"text": "这块磨刀石是双面的，两面都能磨。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè kuài mó dāo shí shì shuāng miàn de, liǎng miàn dōu néng mó.", "sentence_source": "generated"}, {"text": "这种布是双面的，两边颜色不同。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双面的", "label": "定语形式"}, {"form": "双面性", "label": "复合"}, {"form": "雙面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双面：有两个不同的面，或有两方面的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b37b86d-3dce-4b15-a8aa-9eaa55042092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：两面都能受光，正好配合“地面反射光捕获”。"}, {"text": "单面", "is_correct": false, "explanation": "语义：单面组件只有一面受光，无法借地面反射光发电，与句中“地面反射光捕获”相矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：光伏语境中的“组件”指发电部件，“窗户”不是光伏组件，句意不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“组件设计”搭配的是光伏设备，不能与“拖鞋”组合。"}], "explanations": {"双面": "双面：两面都能受光，正好配合“地面反射光捕获”。", "单面": "语义：单面组件只有一面受光，无法借地面反射光发电，与句中“地面反射光捕获”相矛盾。", "窗户": "语义：光伏语境中的“组件”指发电部件，“窗户”不是光伏组件，句意不通。", "拖鞋": "搭配：“组件设计”搭配的是光伏设备，不能与“拖鞋”组合。"}, "sentence_index": 0, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这次比赛的双面冠军。", "explanation": "这里应该用〈双料〉。双面只指物体的两面或两方面的特性，不能用来说同时获得两项荣誉。"}, {"text": "双面达成了协议。", "explanation": "这里应该用〈双方〉。双面指物体的两个面或事物的两方面特性，不能指参与的各方。"}, {"text": "这件事有很多双面。", "explanation": "这里应该用〈方面〉。双面只指两面或两方面的特性，不能用“很多”来计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：指旗子的两面，与“都有图案”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”本身不能“有图案”，句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”不是可以印图案的表面，与“都有图案”不合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以附着图案的表面，与“都有图案”不合。"}], "explanations": {"双面": "双面：指旗子的两面，与“都有图案”相合。", "颜色": "语义：“颜色”本身不能“有图案”，句意不通。", "重量": "语义：“重量”不是可以印图案的表面，与“都有图案”不合。", "声音": "语义：“声音”不是可以附着图案的表面，与“都有图案”不合。"}, "sentence_index": 6, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都拿双面的薪水。", "explanation": "这里应该用〈双倍〉。双面只指物体的两面或两方面的特性，不能用来说薪水加倍。"}, {"text": "这家公司实行双面周末制度。", "explanation": "这里应该用〈双休〉。双面不能用来说每周休息两天。"}, {"text": "那只母鸡生了一个双面蛋。", "explanation": "这里应该用〈双黄〉。双面指物体的两个面，不能用来说蛋黄成双。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请双面打印了这份报告。", "corrected_sentence": "请双面打印这份报告。", "error_description": "错误：祈使句“请……”后不能带“了”。“打印了”应为“打印”，正确句为“请双面打印这份报告。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把木椅双面的都刷了漆。", "corrected_sentence": "这把木椅双面都刷了漆。", "error_description": "错误：“双面”作状语修饰“刷”时后面不加“的”。加了“的”后“双面的”变成名词性短语，句子不通。应为“双面都刷了漆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组件是指构成整体系统的各个独立单元或部件。", "primary_collocate": null, "pronunciation": "zǔ jiàn", "ipa": "tsu˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "组件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器的每个组件都很重要。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在检查电脑里的组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组件坏了，整台机器不能用。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软件由很多组件组成。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了新的太阳能组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每天生产几千个组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把旧组件换成新的。", "target_word": "组件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的主要组件有屏幕和电池。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修车时，他先拆下了坏掉的组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套系统的组件都是独立的。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "光伏组件", "label": "复合"}], "register": "中性", "sense_fingerprint": "构成系统的独立部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件（zǔ jiàn）指构成整体的独立单元，是本词的读音和意思。"}, {"text": "主见", "is_correct": false, "explanation": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。"}, {"text": "组间", "is_correct": false, "explanation": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。"}, {"text": "足见", "is_correct": false, "explanation": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}], "explanations": {"组件": "组件（zǔ jiàn）指构成整体的独立单元，是本词的读音和意思。", "主见": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。", "组间": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。", "足见": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}, "sentence_index": null, "correct_answer": "组件"}, "level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：构成系统的独立部件。「双面组件设计」指光伏组件的双面结构，与前文的光伏技术语境一致。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是光伏电池的部件，放进「双面___设计」与语境不符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的液体，不能作为光伏设备的双面设计对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「双面天气设计」不成搭配，天气不能被设计成双面结构。"}], "explanations": {"组件": "组件：构成系统的独立部件。「双面组件设计」指光伏组件的双面结构，与前文的光伏技术语境一致。", "早餐": "语义：早餐是一顿饭，不是光伏电池的部件，放进「双面___设计」与语境不符。", "饮料": "语义：饮料是可以喝的液体，不能作为光伏设备的双面设计对象。", "天气": "搭配：「双面天气设计」不成搭配，天气不能被设计成双面结构。"}, "sentence_index": 0, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个组件有五百名成员，每天都开会。", "explanation": "这里应该用〈组织〉。组织指由人组成的团体，有成员和会议；组件是物体的独立部件，不能指团体。"}, {"text": "这家公司有三个组件，分别负责销售和财务。", "explanation": "这里应该用〈部门〉。部门是机构内按职能划分的单位；组件指机器或系统中的部件，不用来划分公司。"}, {"text": "我买了一只组件，装在电脑里了。", "explanation": "这里量词应与「组件」搭配：组件用〈个〉或〈套〉，不用〈只〉。「只」多用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：可以被生产出来的独立部件，与「工厂每天生产几千个」的语境相符。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不是工厂生产出来的产品，「生产几千个人」与语境不符。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是工厂生产的东西，「生产几千个星星」与语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是工厂生产的东西，不能「每天生产几千个天气」。"}], "explanations": {"组件": "组件：可以被生产出来的独立部件，与「工厂每天生产几千个」的语境相符。", "人": "语义：人不是工厂生产出来的产品，「生产几千个人」与语境不符。", "星星": "语义：星星不是工厂生产的东西，「生产几千个星星」与语境不符。", "天气": "语义：天气不是工厂生产的东西，不能「每天生产几千个天气」。"}, "sentence_index": 6, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的组件很高，一看就是运动员。", "explanation": "这里应该用〈身材〉。组件指构成机器或系统的部件，不能用来形容人的身形。"}, {"text": "这块地的组件有三亩，全种了麦子。", "explanation": "这里应该用〈面积〉。组件指构成系统的部件，不能用来说土地的大小。"}, {"text": "他用组件把螺丝拧紧了。", "explanation": "这里应该用〈工具〉。组件是机器里的一部分，不能拿来当工具使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器有十只组件。", "corrected_sentence": "这台机器有十个组件。", "error_description": "量词错误：「组件」应用量词「个」（或「套」），说「十只组件」是错误的，正确说法是「十个组件」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑里有一条组件坏了。", "corrected_sentence": "电脑里有一个组件坏了。", "error_description": "量词错误：「组件」应用量词「个」，「条」用于细长的东西，不能用来数组件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
