INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圆柱形零件，用于支撑轮子或传递动力。", "primary_collocate": null, "pronunciation": "zhóu", "ipa": "ʈʂou˧˥", "syllable_count": 1, "sentences": [{"text": "传统风车的水平轴结构被保留，但空气动力学模拟与复合材料的应用，使叶片长度突破百米级，扫风面积呈几何倍数增长。", "target_word": "轴", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这根轴断了，车轮不转了。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子套在轴上，才能转起来。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人给机器的轴上了油。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根轴很粗，能承受很大的力。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电机的轴带动着风扇转动。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把旧轴换成了新轴。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轴转得太快，机器开始发热。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢做的轴比木头做的更结实。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车的轴把动力传给发电机。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "车轴", "label": "复合"}, {"form": "轴承", "label": "复合"}, {"form": "軸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机械中支撑轮子、传递动力的圆柱形零件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。"}, {"text": "周", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}], "explanations": {"轴": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。", "周": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。", "肘": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。", "愁": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。", "皱": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指机械中支撑轮子、传递动力的零件，符合风车水平结构的语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不承担支撑或传动作用，与风车的水平结构不符。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是围挡用的墙体，与风车的传动结构无关。"}, {"text": "台阶", "is_correct": false, "explanation": "体貌：台阶呈阶梯状，不是水平的圆柱形传动件。"}], "explanations": {"轴": "正确。「轴」指机械中支撑轮子、传递动力的零件，符合风车水平结构的语境。", "窗户": "语义：窗户不承担支撑或传动作用，与风车的水平结构不符。", "围墙": "语义：围墙是围挡用的墙体，与风车的传动结构无关。", "台阶": "体貌：台阶呈阶梯状，不是水平的圆柱形传动件。"}, "sentence_index": 0, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用一根铁轴撑住了屋顶。", "explanation": "这里应该用〈铁杆〉。轴是支撑轮子、传递动力的零件，撑屋顶的长条要用「杆」。"}, {"text": "这座桥由几根石轴支撑。", "explanation": "这里应该用〈石柱〉。轴是支撑轮子、传递动力的零件，桥的支柱要用「柱」。"}, {"text": "他拿着一根木轴敲了敲门。", "explanation": "这里应该用〈木棍〉。轴是圆柱形传动零件，拿在手里敲门的棍子要用「棍」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。"}, {"text": "粥", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。"}, {"text": "州", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}], "explanations": {"轴": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。", "粥": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。", "昼": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。", "筹": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。", "州": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指机械中的传动零件，与「换成了新轴」的说法相合。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡与句中的「新轴」不是同类零件，换成这样的说法不通。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是餐具，无法与「新轴」对换，语境不符。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：皮鞋是穿着的物品，不与「换成新轴」这种机械说法搭配。"}], "explanations": {"轴": "正确。「轴」指机械中的传动零件，与「换成了新轴」的说法相合。", "灯泡": "语义：灯泡与句中的「新轴」不是同类零件，换成这样的说法不通。", "碗": "语义：碗是餐具，无法与「新轴」对换，语境不符。", "皮鞋": "搭配：皮鞋是穿着的物品，不与「换成新轴」这种机械说法搭配。"}, "sentence_index": 6, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔民用一根粗轴拴住了小船。", "explanation": "这里应该用〈绳子〉。轴是支撑轮子、传递动力的零件，拴船要用「绳子」。"}, {"text": "他用两根木轴搭起了屋子。", "explanation": "这里应该用〈木梁〉。轴是圆柱形零件，搭屋顶的横木要用「梁」。"}, {"text": "老人拄着一根铁轴走路。", "explanation": "这里应该用〈拐杖〉。轴是传动零件，拄着走路要用「拐杖」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台发动机里有一只轴断了。", "corrected_sentence": "这台发动机里有一根轴断了。", "error_description": "量词错误：轴是细长的棍状零件，应用「根」，「只」多用于动物。「一只轴」应改为「一根轴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给车床换了一颗新轴。", "corrected_sentence": "他给车床换了一根新轴。", "error_description": "量词错误：轴是细长的棍状零件，应用「根」，「颗」多用于小而圆的东西。「一颗新轴」应改为「一根新轴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "长度是物体在空间上两端之间的距离。", "primary_collocate": null, "pronunciation": "cháng dù", "ipa": "ʈʂʰɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "传统风车的水平轴结构被保留，但空气动力学模拟与复合材料的应用，使叶片长度突破百米级，扫风面积呈几何倍数增长。", "target_word": "长度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的长度有三百公里。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请量一下这块布的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的长度是两米。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的长度超过一千米。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这根绳子的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的长度太短，穿着不舒服。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把木板剪成同样的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头发的长度刚到肩膀。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条鱼长度差不多。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长度单位", "label": "复合"}, {"form": "長度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体两端之间的空间距离，可以测量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。长度指物体两端之间的距离，读 cháng dù。"}, {"text": "长途", "is_correct": false, "explanation": "tú（第二声）与 dù（第四声）声母与声调都不同，意思是远距离的路程。"}, {"text": "长处", "is_correct": false, "explanation": "chù 与 dù 声母不同（ch 与 d），声调相同（第四声），意思是优点。"}, {"text": "长裤", "is_correct": false, "explanation": "kù 与 dù 声母不同（k 与 d），声调相同（第四声），意思是长的裤子。"}], "explanations": {"长度": "正确。长度指物体两端之间的距离，读 cháng dù。", "长途": "tú（第二声）与 dù（第四声）声母与声调都不同，意思是远距离的路程。", "长处": "chù 与 dù 声母不同（ch 与 d），声调相同（第四声），意思是优点。", "长裤": "kù 与 dù 声母不同（k 与 d），声调相同（第四声），意思是长的裤子。"}, "sentence_index": null, "correct_answer": "长度"}, "level_3": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。“长度”指叶片两端之间的距离，与“突破百米级”的尺度相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量以千克计，不能与“百米级”这样的长度尺度搭配。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说升高或降低，不能说“突破百米级”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格以金额计算，与“百米级”的长度单位不相容。"}], "explanations": {"长度": "正确。“长度”指叶片两端之间的距离，与“突破百米级”的尺度相符。", "重量": "语义：重量以千克计，不能与“百米级”这样的长度尺度搭配。", "温度": "搭配：“温度”说升高或降低，不能说“突破百米级”。", "价格": "语义：价格以金额计算，与“百米级”的长度单位不相容。"}, "sentence_index": 0, "correct_answer": "长度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的长度是一米八。", "explanation": "这里应该用〈身高〉。长度指物体两端之间的距离，人的高矮要说身高。"}, {"text": "两座城市的长度是三百公里。", "explanation": "这里应该用〈距离〉。长度说物体自身的长短，两地之间的远近要用距离。"}, {"text": "这口井的长度是十米。", "explanation": "这里应该用〈深度〉。井是从地面向下挖的，从上到下的深浅要说深度；长度只用于两端之间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。长度指物体两端之间的距离，读 cháng dù。"}, {"text": "长路", "is_correct": false, "explanation": "lù 与 dù 声母不同（l 与 d），声调相同（第四声），意思是很长的道路。"}, {"text": "长短", "is_correct": false, "explanation": "duǎn（第三声）与 dù（第四声）韵母与声调都不同，意思是长和短。"}, {"text": "长笛", "is_correct": false, "explanation": "dí（第二声）与 dù（第四声）韵母与声调不同，意思是一种管乐器。"}], "explanations": {"长度": "正确。长度指物体两端之间的距离，读 cháng dù。", "长路": "lù 与 dù 声母不同（l 与 d），声调相同（第四声），意思是很长的道路。", "长短": "duǎn（第三声）与 dù（第四声）韵母与声调都不同，意思是长和短。", "长笛": "dí（第二声）与 dù（第四声）韵母与声调不同，意思是一种管乐器。"}, "sentence_index": null, "correct_answer": "长度"}, "level_3": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。这里说裤子的长短，“太短”正好与长度搭配。"}, {"text": "宽度", "is_correct": false, "explanation": "搭配：“宽度”只说宽窄，不说长短，这里不能说“太短”。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色没有长短之分，不能用“太短”来描述裤子。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用长短来描述，与“太短”的意思矛盾。"}], "explanations": {"长度": "正确。这里说裤子的长短，“太短”正好与长度搭配。", "宽度": "搭配：“宽度”只说宽窄，不说长短，这里不能说“太短”。", "颜色": "体貌：颜色没有长短之分，不能用“太短”来描述裤子。", "味道": "语义：味道不能用长短来描述，与“太短”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "长度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的长度是两个小时。", "explanation": "这里应该用〈时长〉。长度只用于空间上的长短，比赛持续的时间要说时长。"}, {"text": "这只猫的长度是四公斤。", "explanation": "这里应该用〈体重〉。公斤是重量单位，猫的重量要说体重，长度指两端之间的距离。"}, {"text": "这间屋子的长度是二十五摄氏度。", "explanation": "这里应该用〈温度〉。摄氏度是温度单位，屋子的冷热程度要说温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木棍的长度跟那根短一些。", "corrected_sentence": "这根木棍的长度比那根短一些。", "error_description": "比较词误用：比较长短要用“比”，“跟”不能引出比较对象。正确形式为“这根木棍的长度比那根短一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根管子的长度比那根很长。", "corrected_sentence": "这根管子的长度比那根更长。", "error_description": "程度副词误用：「比」字句里不能用「很」修饰形容词，要用「更」或「还」。正确形式为「这根管子的长度比那根更长」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
