INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "如果一个整数a能被非零整数b整除，那么a就是b的倍数。", "primary_collocate": null, "pronunciation": "bèi shù", "ipa": "pei˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "十八能被三整除，它是三的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十二是三的倍数，也是四的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能说出十个七的倍数吗？", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "偶数都是二的倍数。", "target_word": "倍数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题要求找出一百以内八的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们写出三的倍数，从三到三十。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数除以五没有余数，它是五的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "末尾是零的整数都是十的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百是二十五的倍数，也是五十的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把三的倍数都圈出来了。", "target_word": "倍数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公倍数", "label": "复合"}, {"form": "最小公倍数", "label": "复合"}, {"form": "倍數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "倍数：能被另一个整数整除的整数，数学概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“倍数”指能被另一个整数整除的数。"}, {"text": "背书", "is_correct": false, "explanation": "声调不同：“背书”（bèi shū）与“倍数”（bèi shù）后一音节声调不同（shū 与 shù），意思是背诵课文。"}, {"text": "倍速", "is_correct": false, "explanation": "声母不同：“倍速”（bèi sù）与“倍数”后一音节声母不同（s 与 sh），意思是播放或运行的速度倍率。"}, {"text": "杯数", "is_correct": false, "explanation": "声调不同：“杯数”（bēi shù）与“倍数”前一音节声调不同（bēi 与 bèi），意思是杯子的数量。"}], "explanations": {"倍数": "正确：“倍数”指能被另一个整数整除的数。", "背书": "声调不同：“背书”（bèi shū）与“倍数”（bèi shù）后一音节声调不同（shū 与 shù），意思是背诵课文。", "倍速": "声母不同：“倍速”（bèi sù）与“倍数”后一音节声母不同（s 与 sh），意思是播放或运行的速度倍率。", "杯数": "声调不同：“杯数”（bēi shù）与“倍数”前一音节声调不同（bēi 与 bèi），意思是杯子的数量。"}, "sentence_index": null, "correct_answer": "倍数"}, "level_3": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“十八能被三整除”即十八是三的倍数，“倍数”指能被另一个整数整除的数。"}, {"text": "因数", "is_correct": false, "explanation": "语义：“因数”指能整除某数的数。十八能被三整除，应说三是十八的因数，不能说十八是三的因数。"}, {"text": "周期", "is_correct": false, "explanation": "语义：“周期”指循环往复的时间段，与整除关系无关，不说“三的周期”。"}, {"text": "时长", "is_correct": false, "explanation": "搭配：“时长”指时间的长短，不说“三的时长”。"}], "explanations": {"倍数": "正确：“十八能被三整除”即十八是三的倍数，“倍数”指能被另一个整数整除的数。", "因数": "语义：“因数”指能整除某数的数。十八能被三整除，应说三是十八的因数，不能说十八是三的因数。", "周期": "语义：“周期”指循环往复的时间段，与整除关系无关，不说“三的周期”。", "时长": "搭配：“时长”指时间的长短，不说“三的时长”。"}, "sentence_index": 0, "correct_answer": "倍数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在三x里，三是x的倍数。", "explanation": "这里应该用〈系数〉。倍数指能被整除的整数，“三x”中的三是x的系数，不表示整除关系。"}, {"text": "三的倍数只有一和三。", "explanation": "这里应该用〈因数〉。三的因数只有一和三；三的倍数有无限个。"}, {"text": "二是四的倍数。", "explanation": "这里应该用〈约数〉。四能被二整除，二是四的约数；倍数指能被整除的那个数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“它是五的倍数”指它能被五整除，与“没有余数”的语境一致。"}, {"text": "余数", "is_correct": false, "explanation": "语义：句中已说“没有余数”，若说“它是五的余数”便与句意矛盾。"}, {"text": "分数", "is_correct": false, "explanation": "语义：整除得到的是整数，不是分数，与“除以五没有余数”的整除语境不符。"}, {"text": "尾数", "is_correct": false, "explanation": "搭配：“尾数”指末位数字，不说“五的尾数”。"}], "explanations": {"倍数": "正确：“它是五的倍数”指它能被五整除，与“没有余数”的语境一致。", "余数": "语义：句中已说“没有余数”，若说“它是五的余数”便与句意矛盾。", "分数": "语义：整除得到的是整数，不是分数，与“除以五没有余数”的整除语境不符。", "尾数": "搭配：“尾数”指末位数字，不说“五的尾数”。"}, "sentence_index": 6, "correct_answer": "倍数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在三的四次方中，四是三的倍数。", "explanation": "这里应该用〈指数〉。倍数表示能被整除，“三的四次方”中的四是指数，与整除无关。"}, {"text": "这个数是五的倍数，所以它能整除五。", "explanation": "词义错误：“倍数”是被整除的数，能整除别的数的是〈因数〉。这个数是五的倍数，不能说它整除五。"}, {"text": "这一百个数都是三的倍数，它们每个都能整除三。", "explanation": "词义错误：三的倍数是能被三整除的数，不能整除三。能整除三的应说〈因数〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "十五是三倍数，也是五的倍数。", "corrected_sentence": "十五是三的倍数，也是五的倍数。", "error_description": "“的”遗漏：“三的倍数”中间需要“的”，不能说“三倍数”。正确说法是“三的倍数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数是七的一只倍数，所以能被七整除。", "corrected_sentence": "这个数是七的一个倍数，所以能被七整除。", "error_description": "量词错误：“倍数”是数学概念，应该用“个”，不用“只”。正确说法是“七的一个倍数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
