INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大陆架是指大陆边缘被海水淹没的、向海缓倾的浅水地带，是大陆向海洋的自然延伸部分。", "primary_collocate": null, "pronunciation": "dà lù jià", "ipa": "ta˥˩ lu˥˩ tɕia˥˩", "syllable_count": 3, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "大陆架", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大陆架上的海水不深，鱼很多。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国东边的海下面有一片大陆架。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石油工人在大陆架上找到了石油。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆架是大陆向海里延伸的地方。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片大陆架很宽，海水浅，适合养鱼。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了一张大陆架的图。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆架的海底有很多石油和天然气。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在大陆架上航行，不用怕水太深。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了大陆架，海水一下子变深了。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大陸架", "label": "繁体"}], "register": "书面", "sense_fingerprint": "大陆边缘被海水淹没、向海缓倾的浅水地带，大陆的自然延伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大陆架", "is_correct": true, "explanation": "正确：大陆架指海底靠近陆地的浅水区，可以作为海上风电场的位置。"}, {"text": "内陆", "is_correct": false, "explanation": "语义：“内陆”在陆地内部，与前文“海上风电场”矛盾。"}, {"text": "高原", "is_correct": false, "explanation": "语义：“高原”是陆地上的高地，与“海上”矛盾。"}, {"text": "沙漠", "is_correct": false, "explanation": "搭配：“沙漠”是陆上地貌，与“海上风电场”迁移的区域不搭配。"}], "explanations": {"大陆架": "正确：大陆架指海底靠近陆地的浅水区，可以作为海上风电场的位置。", "内陆": "语义：“内陆”在陆地内部，与前文“海上风电场”矛盾。", "高原": "语义：“高原”是陆地上的高地，与“海上”矛盾。", "沙漠": "搭配：“沙漠”是陆上地貌，与“海上风电场”迁移的区域不搭配。"}, "sentence_index": 0, "correct_answer": "大陆架"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段海底很陡，大陆架又窄又深。", "explanation": "这里应该用〈大陆坡〉。大陆架是平缓的浅水地带，陡峭又深的海底要说“大陆坡”。"}, {"text": "我家的花园里有一片大陆架。", "explanation": "这里应该用〈草坪〉。大陆架是海底的浅水区，不在陆地上；花园里应该说草坪。"}, {"text": "我们在海底看到了一只大陆架。", "explanation": "这里应该用〈片〉。大陆架是成片的海底区域，量词用“片”；“只”多用于动物等单个的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大陆架", "is_correct": true, "explanation": "正确：大陆架可以画成图，“一张…的图”指地图或示意图。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“友谊”是抽象情感，不能画成图，与“一张…的图”搭配不当。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是声音作品，不能画成图，与“给我们看”的内容矛盾。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”不是可以画出来的事物，与句意矛盾。"}], "explanations": {"大陆架": "正确：大陆架可以画成图，“一张…的图”指地图或示意图。", "友谊": "搭配：“友谊”是抽象情感，不能画成图，与“一张…的图”搭配不当。", "歌曲": "语义：“歌曲”是声音作品，不能画成图，与“给我们看”的内容矛盾。", "感情": "语义：“感情”不是可以画出来的事物，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "大陆架"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的大陆架很深，船很难靠近。", "explanation": "这里应该用〈海沟〉。海沟很深，大陆架是浅水区，不能用来形容很深的地方。"}, {"text": "孩子们在大陆架上堆城堡。", "explanation": "这里应该用〈沙滩〉。城堡要堆在沙滩上；大陆架在海底，不能堆城堡。"}, {"text": "我们在地图上看到一条大陆架。", "explanation": "这里应该用〈片〉。大陆架是成片的海底区域，要用“片”，不能用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔民在一座大陆架上撒网捕鱼。", "corrected_sentence": "渔民在一片大陆架上撒网捕鱼。", "error_description": "“大陆架”指成片的海底区域，量词应用“片”；“座”多用于山、楼房等，不能用来计量大陆架。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船在大陆架附近的停了下来。", "corrected_sentence": "渔船在大陆架附近停了下来。", "error_description": "方位短语“在大陆架附近”后不能直接加“的”接动词“停”，“的”多余，应去掉，说“渔船在大陆架附近停了下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
