INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "风速指空气流动的速度，通常用风力等级或每秒多少米来表示。", "primary_collocate": null, "pronunciation": "fēng sù", "ipa": "fɤŋ˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "风力涡轮机用激光雷达预判风速变化。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风速很大，船都不出海了。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台预报明天的风速每秒十米。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风速超过一定数值，风机就会停止运转。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用仪器测量山顶的风速。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风速越大，风力发电机转得越快。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风中心附近的风速特别高。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的平均风速比去年低一些。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员起飞前要先了解跑道上的风速。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风速每秒三米，只是微风。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均风速", "label": "复合"}, {"form": "风速计", "label": "复合"}], "register": "中性", "sense_fingerprint": "空气流动的速度，用风力等级或米每秒表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风速", "is_correct": true, "explanation": "正确：“预判……变化”预判的是风速的变化，与风力涡轮机和风速的语境吻合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：激光雷达预判的是风的情况，颜色的变化与风力涡轮机的控制无关。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不是激光雷达预判的对象，与风力涡轮机的控制无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：激光雷达只能感知物理环境，无法预判价格的变化，与该语境不合。"}], "explanations": {"风速": "正确：“预判……变化”预判的是风速的变化，与风力涡轮机和风速的语境吻合。", "颜色": "语义：激光雷达预判的是风的情况，颜色的变化与风力涡轮机的控制无关。", "气味": "语义：气味不是激光雷达预判的对象，与风力涡轮机的控制无关。", "价格": "语义：激光雷达只能感知物理环境，无法预判价格的变化，与该语境不合。"}, "sentence_index": 0, "correct_answer": "风速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的风速很美，每年都有很多人来拍照。", "explanation": "这里应该用〈风景〉。风速指风的快慢，形容景色美要用“风景”。"}, {"text": "风速从东南转向西北了。", "explanation": "这里应该用〈风向〉。风速只说快慢，不说方向，描述转向要用“风向”。"}, {"text": "风速来了，树都倒了。", "explanation": "这里应该用〈风暴〉。风速是速度数值，不会“来”，描述风暴到来要用“风暴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风速", "is_correct": true, "explanation": "正确：台风中心附近的风速很高，符合句意。"}, {"text": "气压", "is_correct": false, "explanation": "语义：台风中心的气压很低，与“特别高”相矛盾。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：台风中心在海上，海拔概念不适用，与“特别高”的语境不合。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“收入”不能用于描述台风中心的状况，与“附近的……特别高”搭配不当。"}], "explanations": {"风速": "正确：台风中心附近的风速很高，符合句意。", "气压": "语义：台风中心的气压很低，与“特别高”相矛盾。", "海拔": "语义：台风中心在海上，海拔概念不适用，与“特别高”的语境不合。", "收入": "搭配：“收入”不能用于描述台风中心的状况，与“附近的……特别高”搭配不当。"}, "sentence_index": 6, "correct_answer": "风速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投资的风速很高，大家都很担心。", "explanation": "这里应该用〈风险〉。风速指风的快慢，说投资的危险程度要用“风险”。"}, {"text": "这个人的说话风速很幽默。", "explanation": "这里应该用〈风格〉。风速指风的快慢，描述说话特点要用“风格”。"}, {"text": "这个地方的风速很特别，过年要吃饺子。", "explanation": "这里应该用〈风俗〉。风速指风的快慢，地方习惯要用“风俗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仪器能测出了山顶的风速。", "corrected_sentence": "这个仪器能测出山顶的风速。", "error_description": "体标误用：“能”表示可能，与表示完成的“了”不能同时使用，应删去“了”，说“能测出山顶的风速”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气象员测了出今天的风速。", "corrected_sentence": "气象员测出了今天的风速。", "error_description": "补语位置错误：“测出”是动补结构，“了”应放在“出”之后，应说“测出了今天的风速”，不能说“测了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
