INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船上用来划水前进的工具，通常为长条形，一端有扁平的叶片。", "primary_collocate": null, "pronunciation": "jiǎng", "ipa": "tɕjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他用桨使劲拨水，船慢慢向前走。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他双手握紧桨，用力向后划。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支桨掉进河里，我们捡不回来。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船上只有一支桨。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "划船时，桨要整个插进水里。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桨放在船边，休息了一会儿。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桨的一端有扁平的叶片。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸换了一支新桨，船走得更快了。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人各拿一支桨，一起向前划。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "划了很久，桨上全是水。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "对", "label": "量词"}, {"form": "船桨", "label": "复合"}, {"form": "槳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "船上划水前进的长条形工具，一端有扁平叶片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13737, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "桨", "is_correct": true, "explanation": "jiǎng，船上划水前进的工具，为正确答案。"}, {"text": "江", "is_correct": false, "explanation": "声调不同：jiǎng（第三声）与 jiāng（第一声）不同，jiāng 意思是江河。"}, {"text": "降", "is_correct": false, "explanation": "声调不同：jiàng（第四声）意思是下降，与 jiǎng 声调不同。"}, {"text": "浆", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是液体，如豆浆。"}, {"text": "将", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是将要或将军，与 jiǎng 不同。"}, {"text": "抢", "is_correct": false, "explanation": "声母不同：qiǎng 的声母是 q，与 j 不同，意思是抢夺。"}], "explanations": {"桨": "jiǎng，船上划水前进的工具，为正确答案。", "江": "声调不同：jiǎng（第三声）与 jiāng（第一声）不同，jiāng 意思是江河。", "降": "声调不同：jiàng（第四声）意思是下降，与 jiǎng 声调不同。", "浆": "声调不同：jiāng（第一声）意思是液体，如豆浆。", "将": "声调不同：jiāng（第一声）意思是将要或将军，与 jiǎng 不同。", "抢": "声母不同：qiǎng 的声母是 q，与 j 不同，意思是抢夺。"}, "sentence_index": null, "correct_answer": "桨"}, "level_3": {"options": [{"text": "桨", "is_correct": true, "explanation": "正确：“用……拨水”的工具是桨。"}, {"text": "舵", "is_correct": false, "explanation": "语义：舵用来掌握方向，不用来拨水，“用舵拨水”不合理。"}, {"text": "船", "is_correct": false, "explanation": "语义：“船”是整体，不是拨水的工具，“用船拨水”不成立。"}, {"text": "塔", "is_correct": false, "explanation": "搭配：“用塔拨水”不成词，与语境不合。"}], "explanations": {"桨": "正确：“用……拨水”的工具是桨。", "舵": "语义：舵用来掌握方向，不用来拨水，“用舵拨水”不合理。", "船": "语义：“船”是整体，不是拨水的工具，“用船拨水”不成立。", "塔": "搭配：“用塔拨水”不成词，与语境不合。"}, "sentence_index": 0, "correct_answer": "桨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用桨炒菜，锅里的菜很快就熟了。", "explanation": "这里应该用〈锅铲〉。炒菜要用锅铲，桨是划船用的工具。"}, {"text": "他用桨扫地，地上很快就干净了。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，桨是划船时用来划水的工具。"}, {"text": "我在仓库里找到一头桨。", "explanation": "这里应该用〈支〉。桨是细长的工具，按“支”计量；“头”多用于牲畜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13737, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "桨", "is_correct": true, "explanation": "jiǎng，船上划水前进的工具，为正确答案。"}, {"text": "姜", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是生姜，与 jiǎng 不同。"}, {"text": "匠", "is_correct": false, "explanation": "声调不同：jiàng（第四声）意思是工匠，与 jiǎng 不同。"}, {"text": "剪", "is_correct": false, "explanation": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是剪刀。"}, {"text": "减", "is_correct": false, "explanation": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是减少。"}], "explanations": {"桨": "jiǎng，船上划水前进的工具，为正确答案。", "姜": "声调不同：jiāng（第一声）意思是生姜，与 jiǎng 不同。", "匠": "声调不同：jiàng（第四声）意思是工匠，与 jiǎng 不同。", "剪": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是剪刀。", "减": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是减少。"}, "sentence_index": null, "correct_answer": "桨"}, "level_3": {"options": [{"text": "桨", "is_correct": true, "explanation": "正确：“桨的一端有扁平的叶片”指划船用的桨。"}, {"text": "船", "is_correct": false, "explanation": "语义：“船”是整体，一端没有扁平叶片。"}, {"text": "帆", "is_correct": false, "explanation": "语义：“帆”是挂在船上受风的布，与扁平叶片无关。"}, {"text": "鞋", "is_correct": false, "explanation": "体貌：“鞋”不是长条形，一端也不会有扁平叶片。"}], "explanations": {"桨": "正确：“桨的一端有扁平的叶片”指划船用的桨。", "船": "语义：“船”是整体，一端没有扁平叶片。", "帆": "语义：“帆”是挂在船上受风的布，与扁平叶片无关。", "鞋": "体貌：“鞋”不是长条形，一端也不会有扁平叶片。"}, "sentence_index": 6, "correct_answer": "桨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用桨扇风，屋里凉快了一些。", "explanation": "这里应该用〈扇子〉。扇风要用扇子，桨是划船时用来划水的工具。"}, {"text": "风很大，他把桨升起来，借着风力向前走。", "explanation": "这里应该用〈帆〉。借风力前进的是帆，桨要靠人力划水，不能靠风。"}, {"text": "我们把一颗桨放在船底。", "explanation": "这里应该用〈支〉。颗用于小而圆的东西，桨应按“支”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸买了两本新桨。", "corrected_sentence": "爸爸买了两支新桨。", "error_description": "量词错误：“本”用于书本，桨是细长的工具，应说“两支桨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用力桨划，船快了起来。", "corrected_sentence": "他用力划桨，船快了起来。", "error_description": "语序错误：应说“划桨”，动词在前、名词“桨”在后；“桨划”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
