INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "转矩是使物体产生旋转运动的力矩，等于作用力与力臂的乘积。", "primary_collocate": null, "pronunciation": "zhuàn jǔ", "ipa": "tʂuan˥˩ tɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "转矩", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "转矩等于力乘以力臂。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扳手越长，产生的转矩越大。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电机的转矩很大。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转矩的单位是牛顿米。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力臂变短，转矩就会变小。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用长扳手增大转矩。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写出了转矩的公式。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车发动机的转矩决定了爬坡能力。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "测量转矩要用专门的仪器。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技术语", "sense_fingerprint": "转矩：物理量，作用力乘以力臂，使物体旋转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转矩", "is_correct": true, "explanation": "转矩：调节桨距角是为了优化转矩，符合句意。"}, {"text": "风速", "is_correct": false, "explanation": "语义：桨距角调节是为了优化转矩，「优化风速」与句意不符。"}, {"text": "塔筒", "is_correct": false, "explanation": "语义：桨距角调节作用于叶片，与塔筒无关，「优化塔筒」句意不通。"}, {"text": "地基", "is_correct": false, "explanation": "语义：桨距角调节作用于叶片，与地基无关，「优化地基」句意不通。"}], "explanations": {"转矩": "转矩：调节桨距角是为了优化转矩，符合句意。", "风速": "语义：桨距角调节是为了优化转矩，「优化风速」与句意不符。", "塔筒": "语义：桨距角调节作用于叶片，与塔筒无关，「优化塔筒」句意不通。", "地基": "语义：桨距角调节作用于叶片，与地基无关，「优化地基」句意不通。"}, "sentence_index": 0, "correct_answer": "转矩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电机的转矩很快。", "explanation": "这里应该用〈转速〉。转矩表示使物体转动的力的大小，说快慢要用转速。"}, {"text": "这块铁的转矩很大。", "explanation": "这里应该用〈质量〉。转矩指使物体旋转的力，不是物体本身的多少。"}, {"text": "地面的转矩很大。", "explanation": "这里应该用〈摩擦力〉。转矩与旋转有关，地面阻碍滑动的力不能说转矩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转矩", "is_correct": true, "explanation": "转矩：用长扳手增大的是转矩，符合句意。"}, {"text": "体积", "is_correct": false, "explanation": "语义：扳手不能增大物体的体积，「增大体积」与句意不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：用扳手不能直接增大温度，「增大温度」与句意不符。"}, {"text": "精度", "is_correct": false, "explanation": "搭配：「增大」一般不用于精度，通常说「提高精度」。"}], "explanations": {"转矩": "转矩：用长扳手增大的是转矩，符合句意。", "体积": "语义：扳手不能增大物体的体积，「增大体积」与句意不符。", "温度": "语义：用扳手不能直接增大温度，「增大温度」与句意不符。", "精度": "搭配：「增大」一般不用于精度，通常说「提高精度」。"}, "sentence_index": 6, "correct_answer": "转矩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的转矩很长。", "explanation": "转矩表示使物体旋转的力，不是长度，不能说「很长」。"}, {"text": "这首歌的转矩很动听。", "explanation": "这里应该用〈音色〉。转矩指使物体旋转的力，形容声音好听要用「音色」。"}, {"text": "这间教室的转矩很多。", "explanation": "这里应该用〈学生〉。转矩是物理量，不能说数量多少；说教室里人数多要用「学生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "发动机输出的转矩大越，车子就越有力。", "corrected_sentence": "发动机输出的转矩越大，车子就越有力。", "error_description": "错误：“越”应放在形容词之前，表示程度递增，“大越”不能说；正确应为“越大”，即“转矩越大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电机输出一台转矩。", "corrected_sentence": "这台电机输出一定的转矩。", "error_description": "错误：「转矩」是抽象的物理量，不用「台」（指机器）作量词，「一台转矩」搭配不当；正确应为「一定的转矩」，用「的」连接修饰语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
