INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指容器能够容纳物质或空间的大小。", "primary_collocate": null, "pronunciation": "róng liàng", "ipa": "ʐʊŋ³⁵ ljɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这种折叠背包的容量可以随物品多少伸缩，装满时能达到五十升。", "target_word": "容量", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这个水杯的容量是五百毫升。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个冰箱容量很大，能放很多菜。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个背包容量太小，装不下我的书。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买行李箱以前，请先看看它的容量。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池的容量有多少立方米？", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的油箱容量是五十升。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水壶容量大，一次能烧很多水。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们量一量瓶子的容量。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子的容量比那个大。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大容量", "label": "复合"}, {"form": "小容量", "label": "复合"}], "register": "中性", "sense_fingerprint": "容量：容器或空间能容纳物质的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '674055ee-37a4-449c-90de-84e97de325ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容量", "is_correct": true, "explanation": "正确：容量指容器能容纳的大小，此处指折叠背包可伸缩的容量。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不会随物品多少伸缩，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会随物品多少伸缩，句子说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命不随装载多少而伸缩，句子说不通。"}], "explanations": {"容量": "正确：容量指容器能容纳的大小，此处指折叠背包可伸缩的容量。", "价格": "语义：价格不会随物品多少伸缩，句子说不通。", "颜色": "语义：颜色不会随物品多少伸缩，句子说不通。", "寿命": "语义：寿命不随装载多少而伸缩，句子说不通。"}, "sentence_index": 0, "correct_answer": "容量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的容量很大，搬不动。", "explanation": "这里应该用〈体积〉。容量指容器能装多少，实心石头的大小用〈体积〉。"}, {"text": "我的心情容量很大，一点也不生气。", "explanation": "这里把“容量”用成了〈肚量〉的意思。容量指能装多少具体东西，不能用来形容心情。"}, {"text": "这段路的容量很远，走了一个小时。", "explanation": "这里应该用〈距离〉。容量是能装多少，不能用来说远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容量", "is_correct": true, "explanation": "正确：容量指能容纳的大小，此处指油箱能装多少升。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用“升”计量，“油箱颜色是五十升”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量用千克计，油箱的重量不用“升”来说。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度以千米每小时计，与“五十升”无关。"}], "explanations": {"容量": "正确：容量指能容纳的大小，此处指油箱能装多少升。", "颜色": "搭配：颜色不用“升”计量，“油箱颜色是五十升”不成立。", "重量": "语义：重量用千克计，油箱的重量不用“升”来说。", "速度": "语义：速度以千米每小时计，与“五十升”无关。"}, "sentence_index": 6, "correct_answer": "容量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个音响的容量很大，楼下都能听见。", "explanation": "这里应该用〈音量〉。音量指声音大小，容量指能装多少东西。"}, {"text": "他的容量很大，一口气能说三个小时。", "explanation": "这里把“容量”用成了〈口才〉的意思。容量只形容能装多少东西，不能形容说话的能力。"}, {"text": "这张桌子的容量很重，搬不动。", "explanation": "这里应该用〈重量〉。容量指容器能装多少东西，说东西轻重、搬不搬得动要用重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机的容量很重，一次能洗十公斤衣服。", "corrected_sentence": "这台洗衣机的容量很大，一次能洗十公斤衣服。", "error_description": "形容词搭配：“重”用于重量，不能用来形容容量，容量应说“很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个水壶容量大很，一次能烧很多水。", "corrected_sentence": "这个水壶容量很大，一次能烧很多水。", "error_description": "程度词位置错误：“很”修饰形容词，应放在“大”之前，说“容量很大”，不能说“大很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
