INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快速、大幅度地上升或提高。", "primary_collocate": null, "pronunciation": "yuè shēng", "ipa": "ɥe˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这些技术融合使单机容量从兆瓦级跃升至15兆瓦，度电成本较2010年下降70%。", "target_word": "跃升", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的收入今年跃升了一倍。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩从班里第二十名跃升到第三名。", "target_word": "跃升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新产品上市后，销量大幅跃升。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的排名跃升到全国前五。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年他的工资跃升了不少。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队的排名一个月内跃升了十位。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校的名气跃升得很快。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出口额从两亿元跃升至八亿元。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，她的英语水平跃升到了新的层次。", "target_word": "跃升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跃升了", "label": "体标"}, {"form": "跃升过", "label": "体标"}], "register": "书面", "sense_fingerprint": "跃升|动词|数量、水平、排名快速大幅提高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下跌", "is_correct": false, "explanation": "语义：下跌表示数值下降，与“单机容量从兆瓦级增至15兆瓦”的变化方向相反。"}, {"text": "维持", "is_correct": false, "explanation": "搭配：“维持”表示保持不变，不能与“从……至……”的变化结构搭配。"}, {"text": "回落", "is_correct": false, "explanation": "语义：回落表示回到较低水平，与容量增长的语境矛盾。"}, {"text": "跃升", "is_correct": true, "explanation": "正确。跃升表示快速大幅上升，此处指单机容量从兆瓦级大幅增至15兆瓦。"}], "explanations": {"下跌": "语义：下跌表示数值下降，与“单机容量从兆瓦级增至15兆瓦”的变化方向相反。", "维持": "搭配：“维持”表示保持不变，不能与“从……至……”的变化结构搭配。", "回落": "语义：回落表示回到较低水平，与容量增长的语境矛盾。", "跃升": "正确。跃升表示快速大幅上升，此处指单机容量从兆瓦级大幅增至15兆瓦。"}, "sentence_index": 0, "correct_answer": "跃升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "油价缓慢跃升，持续了半年。", "explanation": "这里应该用〈攀升〉。跃升指快速大幅上升，不能与“缓慢”搭配；逐步上涨要说攀升。"}, {"text": "这个数字只轻微跃升了一点。", "explanation": "这里应该用〈上升〉。跃升指快速、大幅地上升，只有轻微变化要说上升；“轻微”与“跃升”的程度不相容。"}, {"text": "这个村子的人口今年跃升了两个人。", "explanation": "这里应该用〈增加〉。跃升指快速、大幅地上升，只多了两个人只能说增加，不能用跃升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维持", "is_correct": false, "explanation": "语义：维持表示保持不变，与“排名上升了十位”的变化矛盾。"}, {"text": "流失", "is_correct": false, "explanation": "搭配：“流失”多用于人员或资源，“排名流失”不是常见搭配。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长指生物发育变大，不能用于球队排名的变化。"}, {"text": "跃升", "is_correct": true, "explanation": "正确。句中指球队排名在一个月内大幅上升了十位。"}], "explanations": {"维持": "语义：维持表示保持不变，与“排名上升了十位”的变化矛盾。", "流失": "搭配：“流失”多用于人员或资源，“排名流失”不是常见搭配。", "生长": "语义：生长指生物发育变大，不能用于球队排名的变化。", "跃升": "正确。句中指球队排名在一个月内大幅上升了十位。"}, "sentence_index": 6, "correct_answer": "跃升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "股价跃升到了谷底。", "explanation": "这里应该用〈滑落〉。跃升是向上升，谷底是最低处，两者方向相反，不能用跃升描述滑落。"}, {"text": "雨水从屋檐跃升，滴在地上。", "explanation": "这里应该用〈下落〉。跃升是向上快速升起，雨水滴在地上是向下落，方向相反。"}, {"text": "这家公司的业绩跃升，亏损了三百万。", "explanation": "这里应该用〈下滑〉。跃升是快速上升，句中“亏损”说明业绩下降，两者不相容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的收入今年跃升了三个。", "corrected_sentence": "这家公司的收入今年跃升了三倍。", "error_description": "量词错误：“跃升”后的倍数要用“倍”计量，不能说“三个”，正确说法是“跃升了三倍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的名气跃升地异常快。", "corrected_sentence": "这所学校的名气跃升得异常快。", "error_description": "补语标记错误：动词后的程度补语应用“得”，不能用“地”；“跃升地异常快”不成立，应说“跃升得异常快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
