INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体的一头或开始的地方。", "primary_collocate": null, "pronunciation": "duān", "ipa": "twan˥", "syllable_count": 1, "sentences": [{"text": "电线的两端分别接在插座和灯泡上。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的两端各有一座小塔。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把绳子的这一端交给我。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在长桌的另一端，笑着看我。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线的一端系在树上。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子的两端都用布堵住了。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你拿住尺子的这一端。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长椅的左端坐着一位老人。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车的前端有一盏大灯。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小路的一端是学校，另一端是公园。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "端点", "label": "复合"}, {"form": "末端", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：物体的一头，位置或起点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。duān，指物体的一头或开始的地方。"}, {"text": "短", "is_correct": false, "explanation": "duǎn（第三声）与 duān（第一声）声调不同，意思是长度不够，不指物体的末端。"}, {"text": "断", "is_correct": false, "explanation": "duàn（第四声）与 duān（第一声）声调不同，意思是断开。"}, {"text": "穿", "is_correct": false, "explanation": "chuān 与 duān 声母不同（ch 与 d），意思是穿过、穿上。"}, {"text": "酸", "is_correct": false, "explanation": "suān 与 duān 声母不同（s 与 d），意思是味道酸。"}, {"text": "关", "is_correct": false, "explanation": "guān 与 duān 声母不同（g 与 d），意思是关闭。"}], "explanations": {"端": "正确。duān，指物体的一头或开始的地方。", "短": "duǎn（第三声）与 duān（第一声）声调不同，意思是长度不够，不指物体的末端。", "断": "duàn（第四声）与 duān（第一声）声调不同，意思是断开。", "穿": "chuān 与 duān 声母不同（ch 与 d），意思是穿过、穿上。", "酸": "suān 与 duān 声母不同（s 与 d），意思是味道酸。", "关": "guān 与 duān 声母不同（g 与 d），意思是关闭。"}, "sentence_index": null, "correct_answer": "端"}, "level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。“两端”指电线的两头，正好一头接插座、一头接灯泡。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音无形，不能分别接在插座和灯泡上，句意不通。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”指车站等处所，“电线的两站”说不通，电线只有两头，不能分别接在插座和灯泡上。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”是抽象的数值属性，不能分别接在插座和灯泡上。"}], "explanations": {"端": "正确。“两端”指电线的两头，正好一头接插座、一头接灯泡。", "声音": "语义：声音无形，不能分别接在插座和灯泡上，句意不通。", "站": "语义：“站”指车站等处所，“电线的两站”说不通，电线只有两头，不能分别接在插座和灯泡上。", "重量": "搭配：“重量”是抽象的数值属性，不能分别接在插座和灯泡上。"}, "sentence_index": 0, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的一端很痛，医生说可能是骨折。", "explanation": "这里应该用〈腿〉。端指物体的一头，不指人身上的部位，人的腿要说“腿”。"}, {"text": "妈妈的一端很温柔，大家都喜欢她。", "explanation": "这里应该用〈性格〉。端指物体的一头，不能用来形容人的性格。"}, {"text": "他的一端很高，能够得着篮板。", "explanation": "这里应该用〈个子〉。端指物体的一头，不能用来说人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。duān，指物体的一头或开始的地方。"}, {"text": "专", "is_correct": false, "explanation": "zhuān 与 duān 声母不同（zh 与 d），意思是专门、专一。"}, {"text": "宽", "is_correct": false, "explanation": "kuān 与 duān 声母不同（k 与 d），意思是宽阔。"}, {"text": "欢", "is_correct": false, "explanation": "huān 与 duān 声母不同（h 与 d），意思是高兴、喜欢。"}, {"text": "钻", "is_correct": false, "explanation": "zuān 与 duān 声母不同（z 与 d），意思是钻进去。"}, {"text": "担", "is_correct": false, "explanation": "dān 与 duān 只少了韵头 u，声调相同，意思是担子、担任。"}], "explanations": {"端": "正确。duān，指物体的一头或开始的地方。", "专": "zhuān 与 duān 声母不同（zh 与 d），意思是专门、专一。", "宽": "kuān 与 duān 声母不同（k 与 d），意思是宽阔。", "欢": "huān 与 duān 声母不同（h 与 d），意思是高兴、喜欢。", "钻": "zuān 与 duān 声母不同（z 与 d），意思是钻进去。", "担": "dān 与 duān 只少了韵头 u，声调相同，意思是担子、担任。"}, "sentence_index": null, "correct_answer": "端"}, "level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。“这一端”指尺子的一头，与“拿住”的动作相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观属性，不是能被“拿住”的部分，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音无形，不能被拿住，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“拿住”不搭配“味道”，味道不是可以握住的东西。"}], "explanations": {"端": "正确。“这一端”指尺子的一头，与“拿住”的动作相符。", "颜色": "语义：颜色是外观属性，不是能被“拿住”的部分，句意不通。", "声音": "语义：声音无形，不能被拿住，句意不通。", "味道": "搭配：“拿住”不搭配“味道”，味道不是可以握住的东西。"}, "sentence_index": 6, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的一端很聪明，考试总是第一名。", "explanation": "这里应该用〈头脑〉。端指物体的一头，不能用来形容人的聪明程度。"}, {"text": "爸爸的一端很健康，很少生病。", "explanation": "这里应该用〈身体〉。端指物体的一头，不能用来说人的健康状况。"}, {"text": "老师的一端很严格，同学们都有点怕他。", "explanation": "这里应该用〈作风〉。端指物体的一头，不能用来形容人的作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿着绳子的一条端，不肯松手。", "corrected_sentence": "他拿着绳子的一端，不肯松手。", "error_description": "错误在“端”前的量词：“端”不用“条”来计量。正确形式是“绳子的一端”，直接用“一端”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把铁丝了一端弯成了钩子。", "corrected_sentence": "他把铁丝的一端弯成了钩子。", "error_description": "错误在“铁丝”和“一端”之间：领属关系要用“的”，写成“了”不通。正确形式是“他把铁丝的一端弯成了钩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
