INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把电能或其他形式的能量收集并保存起来，供以后使用的技术或设备。", "primary_collocate": null, "pronunciation": "chǔ néng", "ipa": "ʈʂʰu˨˩˦ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当分布式光伏与储能系统构成“产消者”网络，传统自上而下的电网架构正被去中心化模式解构。", "target_word": "储能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个小区新装了一套储能设备。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "储能可以把白天的电留到晚上用。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能发电需要储能来帮忙。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做储能电池。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "储能技术让风电更稳定。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上建了一座大型储能站。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的屋顶装了光伏和储能系统。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家储能企业工作了五年。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有储能，太阳下山后就没电了。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "储能设备", "label": "复合"}, {"form": "储能电池", "label": "复合"}], "register": "书面", "sense_fingerprint": "储能：保存能量供以后使用的技术或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '674055ee-37a4-449c-90de-84e97de325ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储能", "is_correct": true, "explanation": "正确。“储能系统”指保存能量的系统，与分布式光伏、产消者网络的语境相符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸系统”属于生物体，与分布式光伏和电网架构的语境不合。"}, {"text": "消化", "is_correct": false, "explanation": "语义：“消化系统”属于生物体，与电网架构的语境不合。"}, {"text": "神经", "is_correct": false, "explanation": "搭配：“神经系统”不与“构成产消者网络”搭配，此处语境不合。"}], "explanations": {"储能": "正确。“储能系统”指保存能量的系统，与分布式光伏、产消者网络的语境相符。", "呼吸": "语义：“呼吸系统”属于生物体，与分布式光伏和电网架构的语境不合。", "消化": "语义：“消化系统”属于生物体，与电网架构的语境不合。", "神经": "搭配：“神经系统”不与“构成产消者网络”搭配，此处语境不合。"}, "sentence_index": 0, "correct_answer": "储能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把雨水储能在水箱里，留着浇花。", "explanation": "这里应该用〈储存〉。储能指把电或能量存起来，雨水要说储存。"}, {"text": "这家公司多年来储能了很多经验，值得学习。", "explanation": "这里应该用〈积累〉。经验要说积累；储能只指把电或能量存起来，不能用于经验。"}, {"text": "这位收藏家储能了很多名画，价值很高。", "explanation": "这里应该用〈收藏〉。储能只指保存能量，名画要说收藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储能", "is_correct": true, "explanation": "正确。“大型储能站”指储存能量的设施，符合句意。"}, {"text": "海底", "is_correct": false, "explanation": "语义：“海底站”位于海底，与“山上”的位置冲突。"}, {"text": "海上", "is_correct": false, "explanation": "语义：“海上站”位于海面，与“山上”的位置冲突。"}, {"text": "深海", "is_correct": false, "explanation": "搭配：“深海站”多指深海研究站，与“山上”搭配不当。"}], "explanations": {"储能": "正确。“大型储能站”指储存能量的设施，符合句意。", "海底": "语义：“海底站”位于海底，与“山上”的位置冲突。", "海上": "语义：“海上站”位于海面，与“山上”的位置冲突。", "深海": "搭配：“深海站”多指深海研究站，与“山上”搭配不当。"}, "sentence_index": 6, "correct_answer": "储能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每年都储能很多蔬菜，卖给超市。", "explanation": "这里应该用〈种植〉。蔬菜要说种植；储能指把电或能量存起来，不能用于蔬菜。"}, {"text": "他储能了很多单词，考试时都用上了。", "explanation": "这里应该用〈记住〉。储能只指保存能量，记单词要说记住。"}, {"text": "这家博物馆专门储能古代文物。", "explanation": "这里应该用〈展览〉。储能只用于能量，古代文物要说展览或保管。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区新装了一条储能设备，晚上也能用上白天的电。", "corrected_sentence": "这个小区新装了一套储能设备，晚上也能用上白天的电。", "error_description": "量词错误：“储能设备”是成套的装置，应该用“一套”；“条”用于细长的东西，不能用来计量储能设备。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛上建了一座大型地储能电站，白天储存太阳能。", "corrected_sentence": "这座岛上建了一座大型储能电站，白天储存太阳能。", "error_description": "“大型”与“储能”之间不能用“地”，“地”用于状语；修饰名词“电站”时应直接说“大型储能电站”，去掉多余的“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
