INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电网是由发电、输电、变电、配电等设备组成的电力系统网络。", "primary_collocate": null, "pronunciation": "diàn wǎng", "ipa": "tjɛn˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "当分布式光伏与储能系统构成“产消者”网络，传统自上而下的电网架构正被去中心化模式解构。", "target_word": "电网", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市的电网很安全。", "target_word": "电网", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚大风吹断了电线，电网出了问题。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在检查山区的电网。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天用电多，电网压力很大。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家一直在改造老旧电网。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能发的电可以送进电网。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电网公司提前通知了停电时间。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新电网建好以后，村里不再经常停电。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电网需要定期维护，才能保持稳定。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "電網", "label": "繁体"}, {"form": "智能电网", "label": "复合"}, {"form": "国家电网", "label": "复合"}], "register": "书面", "sense_fingerprint": "电网：由发电、输电、变电、配电设备组成的电力系统网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电网", "is_correct": true, "explanation": "「电网」指由发电、输电、变电、配电设备组成的电力系统网络，与「架构」及光伏、储能的语境相符。"}, {"text": "水网", "is_correct": false, "explanation": "语义：句中讲的是光伏、储能与电能，「水网」指水系网络，与电力系统无关。"}, {"text": "管网", "is_correct": false, "explanation": "语义：「管网」指输送气体或液体的管道系统，不是输送电能的电力网络。"}, {"text": "电台", "is_correct": false, "explanation": "搭配：「电台」不是能够构成「架构」的输电网络，「电台架构」搭配不当。"}], "explanations": {"电网": "「电网」指由发电、输电、变电、配电设备组成的电力系统网络，与「架构」及光伏、储能的语境相符。", "水网": "语义：句中讲的是光伏、储能与电能，「水网」指水系网络，与电力系统无关。", "管网": "语义：「管网」指输送气体或液体的管道系统，不是输送电能的电力网络。", "电台": "搭配：「电台」不是能够构成「架构」的输电网络，「电台架构」搭配不当。"}, "sentence_index": 0, "correct_answer": "电网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把手机充电器插进了墙上的电网。", "explanation": "这里应该用〈插座〉。「电网」是大范围的输配电系统，充电器要插在〈插座〉上，不能说「插进电网」。"}, {"text": "这座电网每天负责给学生做午饭。", "explanation": "这里应该用〈食堂〉。「电网」是输送电能的系统，不负责做饭；给学生做午饭的应是〈食堂〉。"}, {"text": "房间的电网老化了，需要换新的。", "explanation": "这里应该用〈电路〉。「电网」指城乡大范围的输配电系统，室内线路老化应说〈电路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电网", "is_correct": true, "explanation": "「电网」是接收并输送电能的系统，可以接收太阳能发的电，与「送进」搭配得当。"}, {"text": "交通网", "is_correct": false, "explanation": "语义：「交通网」是道路系统，与输送电能无关。"}, {"text": "通信网", "is_correct": false, "explanation": "语义：「通信网」传输的是信息，不能接收太阳能发的电，与「送进」的对象不符。"}, {"text": "下水道", "is_correct": false, "explanation": "搭配：「下水道」是排放污水的设施，「送进」的电能不能排入，搭配不当。"}], "explanations": {"电网": "「电网」是接收并输送电能的系统，可以接收太阳能发的电，与「送进」搭配得当。", "交通网": "语义：「交通网」是道路系统，与输送电能无关。", "通信网": "语义：「通信网」传输的是信息，不能接收太阳能发的电，与「送进」的对象不符。", "下水道": "搭配：「下水道」是排放污水的设施，「送进」的电能不能排入，搭配不当。"}, "sentence_index": 6, "correct_answer": "电网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市新装了一只电网。", "explanation": "这里量词用错。「只」多用于动物或成对的物品，电网是一整套系统，应用〈个〉或〈套〉。"}, {"text": "我们村新装了一头电网。", "explanation": "这里量词用错。「头」用于牲畜，不用于电网，应用〈个〉或〈套〉。"}, {"text": "城里新建了一台电网。", "explanation": "这里量词用错。「台」用于机器设备，电网是输电网络，应用〈个〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只电网去年升级了。", "corrected_sentence": "这个电网去年升级了。", "error_description": "量词错误：「电网」应用量词「个」，不能用「只」（「只」多用于动物或成对的物品）。应改为「这个电网去年升级了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区有一个安全地电网。", "corrected_sentence": "这个小区有一个安全的电网。", "error_description": "的地误用：「安全」修饰名词「电网」，应用结构助词「的」，不能用「地」（「地」用于修饰动词）。应改为「安全的电网」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
