INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "买卖双方通过协商，以货币或实物交换商品或服务的行为。", "primary_collocate": null, "pronunciation": "jiāo yì", "ipa": "tɕjɑʊ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这笔交易很顺利。", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天他们完成了一次交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司的交易价格已经谈好了。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上交易一定要注意安全。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次交易给公司带来了很多钱。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交易结束后，买家收到了商品。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的交易是公平的。", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们每天有上百笔交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的交易记录都保存着。", "target_word": "交易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖双方在交易前先谈好价格。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "交易所", "label": "复合"}, {"form": "交易员", "label": "复合"}], "register": "中性", "sense_fingerprint": "交易：买卖双方协商后，用货币或实物交换商品或服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「这笔交易」指一次买卖，「很顺利」说的是交易的进展。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票是纸币，不是双方协商的买卖行为，不能说「这笔钞票很顺利」。"}, {"text": "奖金", "is_correct": false, "explanation": "搭配：「顺利」形容事情的进展，不能用来形容奖金本身。"}, {"text": "金子", "is_correct": false, "explanation": "语义：金子是贵金属，本身不能「顺利」，不符合这个句子的语境。"}], "explanations": {"交易": "正确。「这笔交易」指一次买卖，「很顺利」说的是交易的进展。", "钞票": "语义：钞票是纸币，不是双方协商的买卖行为，不能说「这笔钞票很顺利」。", "奖金": "搭配：「顺利」形容事情的进展，不能用来形容奖金本身。", "金子": "语义：金子是贵金属，本身不能「顺利」，不符合这个句子的语境。"}, "sentence_index": 0, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和朋友交易了心事。", "explanation": "这里应该用〈交流〉。交流心事是互相诉说，「交易」指买卖商品或服务，不能用于心事。"}, {"text": "我们交易了一下计划。", "explanation": "这里应该用〈商量〉。商量计划是共同讨论，「交易」指买卖或以货币、实物交换，计划不能交易。"}, {"text": "他很会交易朋友。", "explanation": "这里应该用〈交朋友〉。「交朋友」指建立友谊，「交易」指买卖，不能说「交易朋友」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「我们的交易」指双方的买卖，「是公平的」评价的是这次交易。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「公平」用于待遇、竞争、分配，不能用来修饰颜色。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能说「身高是公平的」。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的体貌特征，不能说「体重是公平的」。"}], "explanations": {"交易": "正确。「我们的交易」指双方的买卖，「是公平的」评价的是这次交易。", "颜色": "搭配：「公平」用于待遇、竞争、分配，不能用来修饰颜色。", "身高": "体貌：身高是人的体貌特征，不能说「身高是公平的」。", "体重": "体貌：体重是人的体貌特征，不能说「体重是公平的」。"}, "sentence_index": 6, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会上，大家交易了意见。", "explanation": "这里应该用〈交换〉。「交换意见」是固定说法；「交易」指买卖商品或服务，不能和「意见」搭配。"}, {"text": "同学们交易了一个笑容。", "explanation": "这里应该用〈交换〉。交换笑容是互相回应，不是买卖，也不是以实物交换；「交易」只用于商品或服务。"}, {"text": "我们交易了彼此的感受。", "explanation": "这里应该用〈分享〉。分享感受是与人共同体会心情，「交易」指买卖或以实物交换，感受不是交易的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们和客户谈成了一张交易。", "corrected_sentence": "我们和客户谈成了一笔交易。", "error_description": "量词错误：「张」用于纸、桌子等扁平物，交易应该用量词「笔」，应说「一笔交易」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把交易很划算。", "corrected_sentence": "这笔交易很划算。", "error_description": "错误：「这把交易」；正确：「这笔交易」。「把」用于有柄的器具，交易应该用量词「笔」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
