INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大气中的各种天气现象，如风、雨、雪等。", "primary_collocate": null, "pronunciation": "qì xiàng", "ipa": "tɕʰi˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "气象", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山上的气象变化很快。", "target_word": "气象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "气象专家说今年夏天会很热。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的气象常常不稳定。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天观察气象变化。", "target_word": "气象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "台风来了，气象部门发出了提醒。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的气象资料保存了五十年。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的气象非常复杂，雨雪经常突然出现。", "target_word": "气象", "complexity_tier": "T3", "furigana": "zhè gè dìqū de qìxiàng fēicháng fùzá, yǔ xuě jīngcháng tūrán chūxiàn.", "sentence_source": "generated"}, {"text": "海上的气象对船很重要。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请看一下明天的气象预报。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "气象台", "label": "复合"}, {"form": "气象局", "label": "复合"}], "register": "中性", "sense_fingerprint": "大气中风、雨、雪等天气现象的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气象", "is_correct": true, "explanation": "正确。“气象数据”指天气现象的数据，可用来预测用电行为。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，与预测用电行为无关。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不能作为预测用电行为的数据来源。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色数据”不是常用说法，且颜色与用电行为无关。"}], "explanations": {"气象": "正确。“气象数据”指天气现象的数据，可用来预测用电行为。", "诗歌": "语义：诗歌是文学作品，与预测用电行为无关。", "花园": "语义：花园是一个地方，不能作为预测用电行为的数据来源。", "颜色": "搭配：“颜色数据”不是常用说法，且颜色与用电行为无关。"}, "sentence_index": 0, "correct_answer": "气象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月食是一种常见的气象。", "explanation": "这里应该用〈天象〉。天象指日月星辰等天文现象，月食属于此类，不属于大气中的天气现象。"}, {"text": "今天的气象是三十度。", "explanation": "这里应该用〈气温〉。气温指空气的冷热程度，可以用度数表示；气象是天气现象的总称，不能用来指温度数值。"}, {"text": "今天的气象是百分之八十。", "explanation": "这里应该用〈湿度〉。湿度指空气中水汽的多少，常用百分数表示；气象是天气现象的总称，不能用来指湿度数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气象", "is_correct": true, "explanation": "正确。“气象资料”指记录天气现象的资料，可以长期保存。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的特点，不是可以保存五十年的资料。"}, {"text": "步伐", "is_correct": false, "explanation": "搭配：“资料”不搭配“步伐”，步伐是走路的动作，不能说“步伐资料”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的情绪习惯，不是可以保存的资料内容。"}], "explanations": {"气象": "正确。“气象资料”指记录天气现象的资料，可以长期保存。", "性格": "语义：性格是人的特点，不是可以保存五十年的资料。", "步伐": "搭配：“资料”不搭配“步伐”，步伐是走路的动作，不能说“步伐资料”。", "脾气": "语义：脾气是人的情绪习惯，不是可以保存的资料内容。"}, "sentence_index": 6, "correct_answer": "气象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球绕着太阳转是一种气象。", "explanation": "这里应该用〈天象〉。地球绕太阳转是天文现象，不是大气中的风、雨、雪等天气现象。"}, {"text": "今天的气象是每秒五米。", "explanation": "这里应该用〈风速〉。风速是风的快慢，可以用每秒几米表示；气象是天气现象的总称，不能指一个数值。"}, {"text": "地震是一种常见的气象。", "explanation": "这里应该用〈地质现象〉。地震发生在地下，不是大气中的天气现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只气象变化很大，大家要注意。", "corrected_sentence": "这次气象变化很大，大家要注意。", "error_description": "量词错误：“气象变化”是一次变化的事件，应说“这次气象变化”；“只”多用于动物，不能修饰“气象变化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天得气象很复杂，大家要注意。", "corrected_sentence": "今天的气象很复杂，大家要注意。", "error_description": "结构助词错误：“气象”前的修饰成分要用“的”，不能用“得”，应说“今天的气象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
