INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使用电力来驱动设备或照明。", "primary_collocate": null, "pronunciation": "yòng diàn", "ipa": "jʊŋ˥˩ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "用电", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夏天空调多，用电很多。", "target_word": "用电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请注意用电安全。", "target_word": "用电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上是用电最多的时间。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每个月用电很多。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校提醒学生节约用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我们家用电比夏天少。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电的时候，手不能是湿的。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里终于可以用电了。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电太多，电费就会很高。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用电量", "label": "复合"}], "register": "中性", "sense_fingerprint": "使用电力来驱动设备或照明的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。“用电行为”指使用电力的行为，与气象数据一起用于预测。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是用电的行为，无法用来预测用电。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不能说“花园行为”，与用电无关。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，与用电行为无关。"}], "explanations": {"用电": "正确。“用电行为”指使用电力的行为，与气象数据一起用于预测。", "颜色": "语义：颜色不是用电的行为，无法用来预测用电。", "花园": "语义：花园是一个地方，不能说“花园行为”，与用电无关。", "诗歌": "语义：诗歌是文学作品，与用电行为无关。"}, "sentence_index": 0, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰箱是一种用电。", "explanation": "这里应该用〈用电器〉。用电器是用电工作的器具，冰箱是器具；“用电”指使用电能的行为，不能指物品。"}, {"text": "昨晚突然用电了，全家只好点蜡烛。", "explanation": "这里应该用〈停电〉。停电指供电突然中断，所以全家只好点蜡烛；“用电”是使用电能的行为，不能表示电被切断。"}, {"text": "学校的用电有三层楼。", "explanation": "这里应该用〈教学楼〉。“用电”是使用电能的行为，不能指建筑物，所以不能说“有三层楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。“用电”指使用电力，冬天家里用电比夏天少。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事情，不能用家里的多少来和夏天比较。"}, {"text": "教授", "is_correct": false, "explanation": "搭配：“我们家教授”不能这样说，人不是家里的用量，不能和夏天比多少。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是音乐的音高组合，与家里的用量无关。"}], "explanations": {"用电": "正确。“用电”指使用电力，冬天家里用电比夏天少。", "历史": "语义：历史是过去的事情，不能用家里的多少来和夏天比较。", "教授": "搭配：“我们家教授”不能这样说，人不是家里的用量，不能和夏天比多少。", "旋律": "语义：旋律是音乐的音高组合，与家里的用量无关。"}, "sentence_index": 6, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块用电很耐用，可以用两年。", "explanation": "这里应该用〈电池〉。电池是可以耐用的物品；“用电”是行为，不能说“很耐用”。"}, {"text": "用电是一种能量。", "explanation": "这里应该用〈电能〉。电能是一种能量；“用电”是使用电能的行为，不能说“是一种能量”。"}, {"text": "这根用电很粗，能承受大电流。", "explanation": "这里应该用〈电线〉。电线是可以粗细的物体；“用电”是行为，不能用来形容粗细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校终于可以用电着。", "corrected_sentence": "学校终于可以用电了。", "error_description": "了/着错误：“终于可以……了”表示状态发生变化，应说“可以用电了”；“着”表示动作持续，不能说“用电着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我们家用电得很多，电费也高。", "corrected_sentence": "这个月我们家用电很多，电费也高。", "error_description": "补语错误：“用电”后面直接说程度时不能加“得”，应说“用电很多”（或“用电用得很多”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据已知情况，对未来的事情进行推测或估计。", "primary_collocate": null, "pronunciation": "yù cè", "ipa": "y˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "预测", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家预测明年天气会更热。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也无法预测比赛的结果。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据数据，他预测房价会下降。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台预测明天有大雨。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预测这次考试不太难。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预测得很准。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预测今年的销量会增加。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人预测过这样的变化。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以预测下个月的客流量。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预测了", "label": "体标"}, {"form": "预测过", "label": "体标"}], "register": "中性", "sense_fingerprint": "根据已知情况推测未来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：预测指根据已知数据推断将来的情况，与“气象数据与用电行为”的推算一致。"}, {"text": "感受", "is_correct": false, "explanation": "语义：感受指亲身体会，不能“通过气象数据与用电行为”来推算未来的用电情况，句意不通。"}, {"text": "享用", "is_correct": false, "explanation": "语义：享用指享受使用某物，与“通过数据推算、实现动态平衡”的语境不合，句意不通。"}, {"text": "检修", "is_correct": false, "explanation": "语义：检修是对设备的检查和修理，与通过数据推算未来的语境不合。"}], "explanations": {"预测": "语义：预测指根据已知数据推断将来的情况，与“气象数据与用电行为”的推算一致。", "感受": "语义：感受指亲身体会，不能“通过气象数据与用电行为”来推算未来的用电情况，句意不通。", "享用": "语义：享用指享受使用某物，与“通过数据推算、实现动态平衡”的语境不合，句意不通。", "检修": "语义：检修是对设备的检查和修理，与通过数据推算未来的语境不合。"}, "sentence_index": 0, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法医预测死者死于昨天夜里。", "explanation": "这里应该用〈推断〉。昨天夜里已经发生的事只能推断，不能用预测；预测只用于尚未发生的事。"}, {"text": "她预测了童年的那次旅行。", "explanation": "这里应该用〈回忆〉。童年的事已经过去，预测只能用于将来的事。"}, {"text": "警察预测了事故的原因。", "explanation": "这里应该用〈查明〉。事故已经发生，原因要去查明，不能用预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：“预测得很准”指推断的结果准确，与句意相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与“准不准”无关，“哭得很准”说不通。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：睡觉不能用“准”来形容，“睡得很准”不成立。"}, {"text": "笑", "is_correct": false, "explanation": "语义：笑没有准确与否的问题，“笑得很准”说不通。"}], "explanations": {"预测": "语义：“预测得很准”指推断的结果准确，与句意相符。", "哭": "语义：哭与“准不准”无关，“哭得很准”说不通。", "睡": "搭配：睡觉不能用“准”来形容，“睡得很准”不成立。", "笑": "语义：笑没有准确与否的问题，“笑得很准”说不通。"}, "sentence_index": 6, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士预测了病人此刻的体温。", "explanation": "这里应该用〈测量〉。预测是推断将来的情况，此刻的体温已经是已知的，应该用测量。"}, {"text": "店员预测了店里此刻的客人数。", "explanation": "这里应该用〈统计〉。此刻的人数是已知的事实，要用统计；预测只用于将来的情况。"}, {"text": "司机预测了仪表盘上的数字。", "explanation": "这里应该用〈读取〉。仪表盘上的数字就在眼前，应该读取，不能预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老专家预测地很准。", "corrected_sentence": "这位老专家预测得很准。", "error_description": "错误形式：“地”。正确形式：“得”。“地”用在动词前作状语，动词后引出补语要用“得”，所以应说“预测得很准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员已经预测着明年的销量。", "corrected_sentence": "研究人员已经预测了明年的销量。", "error_description": "错误形式：“预测着”。正确形式：“预测了”。“着”表示动作持续的状态，与“已经”表示的完成相矛盾，应用“了”表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物具有补充、增加以完善整体的特性。", "primary_collocate": null, "pronunciation": "bǔ chōng xìng", "ipa": "pu˨˩˦ ʈʂʰʊŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种系统级创新使清洁能源从补充性能源，进化为新型电力系统的基石。", "target_word": "补充性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这本书的补充性很强，可以和课本一起用。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络课程有补充性，不能代替学校教育。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些练习题具有补充性，做不做都可以。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案只有补充性，不是主要办法。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把兼职当作补充性收入，不影响正式工作。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的数据只起补充性作用。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种维生素起补充性的作用，不能代替正常饮食。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发言有补充性，让大家听得更明白。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图只是补充性资料，不是考试的重点。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "補充性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "补充性：事物起补充、完善整体作用的特性，不是主要部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“补充性能源”指起辅助作用的能源，与“进化为……基石”的上升关系相符。"}, {"text": "主导性", "is_correct": false, "explanation": "语义：“主导性”本身已居核心地位，与“从……进化为基石”由次要到核心的转变相矛盾。"}, {"text": "污染性", "is_correct": false, "explanation": "语义：“污染性”与句中的“清洁能源”相冲突，无法与“进化为基石”搭配理解。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”指起美化作用，与能源的功能无关，不说“装饰性能源”。"}], "explanations": {"补充性": "正确：“补充性能源”指起辅助作用的能源，与“进化为……基石”的上升关系相符。", "主导性": "语义：“主导性”本身已居核心地位，与“从……进化为基石”由次要到核心的转变相矛盾。", "污染性": "语义：“污染性”与句中的“清洁能源”相冲突，无法与“进化为基石”搭配理解。", "装饰性": "语义：“装饰性”指起美化作用，与能源的功能无关，不说“装饰性能源”。"}, "sentence_index": 0, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案的补充性很强，是整个计划的核心。", "explanation": "这里应该用〈主导性〉。补充性指起补充、完善作用，不是主要部分；说“是……核心”要用〈主导性〉。"}, {"text": "这条规定的补充性很强，任何人都不能省略。", "explanation": "这里应该用〈必要性〉。补充性指增加内容使整体更完善，不表示不可缺少；说“任何人都不能省略”要用〈必要性〉。"}, {"text": "他的补充性很强，总是乐于帮别人做事。", "explanation": "用法错误：补充性用来说事物所起的补充作用，不用来形容人的性格。描述人乐于帮忙应说〈热心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
